struct MatchEventInput<'a> {
    tick: i32,
    half: i32,
    possession_id: i32,
    event_type: &'a str,
    team_home: bool,
    player: serde_json::Value,
    target_player: serde_json::Value,
    assist_player: serde_json::Value,
    outcome: &'a str,
    xg: f64,
    origin: Option<(f64, f64)>,
    target: Option<(f64, f64)>,
    tags: EventTags<'a>,
    score_before: Option<(i32, i32)>,
}

const MAX_EVENT_TAGS: usize = 12;

struct EventTags<'a> {
    values: [&'a str; MAX_EVENT_TAGS],
    len: usize,
}

impl<'a> EventTags<'a> {
    fn empty() -> Self {
        Self {
            values: [""; MAX_EVENT_TAGS],
            len: 0,
        }
    }

    fn one(tag: &'a str) -> Self {
        let mut tags = Self::empty();
        tags.push(tag);
        tags
    }

    fn from_slice(values: &[&'a str]) -> Self {
        assert!(
            values.len() <= MAX_EVENT_TAGS,
            "event tags exceed fixed capacity"
        );
        let mut tags = Self::empty();
        tags.values[..values.len()].copy_from_slice(values);
        tags.len = values.len();
        tags
    }

    fn push(&mut self, tag: &'a str) {
        assert!(
            self.len < MAX_EVENT_TAGS,
            "event tags exceed fixed capacity"
        );
        self.values[self.len] = tag;
        self.len += 1;
    }

    fn as_slice(&self) -> &[&'a str] {
        &self.values[..self.len]
    }
}

fn event_player(player: Option<&RunnerPlayer>) -> serde_json::Value {
    player
        .map(|player| {
            json!({
                "player_id": player.player_id,
                "name": player.name,
                "color": player.color,
                "colored_name": player.colored_name,
                "position": player.position,
            })
        })
        .unwrap_or(serde_json::Value::Null)
}

fn event_position(position: Option<(f64, f64)>) -> serde_json::Value {
    position
        .map(|position| json!([round_one(position.0), round_one(position.1)]))
        .unwrap_or(serde_json::Value::Null)
}

fn record_match_event(
    state: &mut RunnerMatchState,
    config: &RunnerRuntimeConfig,
    input: MatchEventInput<'_>,
) {
    state.event_seq += 1;
    let match_second = (input.tick as f64 * config.tick_duration)
        .floor()
        .clamp(0.0, 90.0 * 60.0 - 1.0) as i32;
    let score_before = input
        .score_before
        .unwrap_or((state.home_score, state.away_score));
    state.events.push(json!({
        "seq": state.event_seq,
        "tick": input.tick,
        "match_second": match_second,
        "minute": match_second / 60,
        "second": match_second % 60,
        "half": input.half,
        "possession_id": input.possession_id,
        "event_type": input.event_type,
        "team_side": if input.team_home { "home" } else { "away" },
        "player": input.player,
        "target_player": input.target_player,
        "assist_player": input.assist_player,
        "outcome": input.outcome,
        "xg": round_two(input.xg),
        "score_before": [score_before.0, score_before.1],
        "score_after": [state.home_score, state.away_score],
        "origin": event_position(input.origin),
        "target": event_position(input.target),
        "tags": input.tags.as_slice(),
    }));
}

fn record_technical_control_error(
    state: &mut RunnerMatchState,
    config: &RunnerRuntimeConfig,
    tick: i32,
    half: i32,
    possession_id: i32,
    event_type: &'static str,
    team_home: bool,
    player: serde_json::Value,
    origin: (f64, f64),
    loose_pos: (f64, f64),
) {
    record_match_event(
        state,
        config,
        MatchEventInput {
            tick,
            half,
            possession_id,
            event_type,
            team_home,
            player,
            target_player: serde_json::Value::Null,
            assist_player: serde_json::Value::Null,
            outcome: "loose",
            xg: 0.0,
            origin: Some(origin),
            target: Some(loose_pos),
            tags: EventTags::from_slice(&["technical_error", "second_ball"]),
            score_before: None,
        },
    );
}

fn record_shot_mishit(
    state: &mut RunnerMatchState,
    config: &RunnerRuntimeConfig,
    tick: i32,
    half: i32,
    possession_id: i32,
    team_home: bool,
    player: serde_json::Value,
    origin: (f64, f64),
    loose_pos: (f64, f64),
) {
    record_match_event(
        state,
        config,
        MatchEventInput {
            tick,
            half,
            possession_id,
            event_type: "shot",
            team_home,
            player,
            target_player: serde_json::Value::Null,
            assist_player: serde_json::Value::Null,
            outcome: "mishit",
            xg: 0.0,
            origin: Some(origin),
            target: Some(loose_pos),
            tags: EventTags::from_slice(&["mishit", "technical_error", "second_ball"]),
            score_before: None,
        },
    );
}

fn player_identity(players: &[RunnerPlayer], index: usize) -> serde_json::Value {
    event_player(players.get(index))
}

fn pass_event_tags(
    flight: &RunnerFlight,
    receive_pos: (f64, f64),
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
) -> EventTags<'static> {
    let pass_stats = track_pass_stats(&PassStatInput {
        origin: flight.origin,
        target: receive_pos,
        attacking_right: attacking_right_for(flight.passer_team_home, home_attacking_right),
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
    });
    let mut tags = EventTags::one(if flight.is_long { "long" } else { "short" });
    tags.push(if flight.target_is_space {
        "space"
    } else {
        "feet"
    });
    if pass_stats.progressive_passes > 0 {
        tags.push("progressive");
    }
    if pass_stats.passes_into_final_third > 0 {
        tags.push("into_final_third");
    }
    if pass_stats.passes_into_box > 0 {
        tags.push("into_box");
    }
    if pass_stats.crosses_attempted > 0 {
        tags.push("cross");
    }
    if flight.target_is_space && pass_stats.progressive_passes > 0 {
        tags.push("through_ball");
    }
    tags
}

fn pass_execution_tags(
    flight: &RunnerFlight,
    receive_pos: (f64, f64),
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
) -> EventTags<'static> {
    let mut tags = pass_event_tags(flight, receive_pos, config, home_attacking_right);
    tags.push(if flight.delivery_miss {
        "delivery_error"
    } else {
        "delivery_clean"
    });
    tags
}

fn shot_event_tags(flight: &RunnerFlight, in_box: bool, outcome: &str) -> EventTags<'static> {
    let mut tags = EventTags::one(if in_box { "in_box" } else { "outside_box" });
    if flight.on_target {
        tags.push("on_target");
    }
    if flight.xg >= 0.3 {
        tags.push("big_chance");
    }
    if outcome == "goal" {
        tags.push("scored");
    }
    tags
}

