    #[test]
    fn shot_choice_uses_holder_belief_while_execution_resolves_hidden_blocker() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Home {index}").as_str(), 82.0, 82.0))
            .collect::<Vec<_>>();
        let opponent_cards = (0..11)
            .map(|index| runner_test_card(format!("Away {index}").as_str(), 82.0, 82.0))
            .collect::<Vec<_>>();
        let mut teammates = build_players(&cards, formation_data("433"), true, 105.0, 68.0);
        let mut opponents =
            build_players(&opponent_cards, formation_data("433"), false, 105.0, 68.0);
        let holder_idx = 10;
        teammates[holder_idx].pos = (92.0, 34.0);
        teammates[holder_idx].target_pos = teammates[holder_idx].pos;
        teammates[holder_idx].last_receive_origin = (84.0, 34.0);
        opponents[0].pos = (102.0, 34.0);
        opponents[1].pos = (96.0, 34.0);
        let config = runtime_config(&json!({}));
        let cache = RefCell::new(HashMap::new());
        let mut scratch = RunnerHeldDecisionScratch::new();
        scratch.prepare(holder_idx, &teammates, &opponents, &config);
        let hidden_blocker = [ShotContestDefender {
            index: 1,
            pos: opponents[1].pos,
            projected_pos: opponents[1].pos,
            speed: opponents[1].speed,
            defence: opponents[1].defence,
            intent: crate::ShotContestIntent::BlockLane,
            engagement_weight: 0.0,
            engagement_reach: 0.0,
            is_goalkeeper: false,
        }];

        let unobserved_candidate = build_shot_candidate_with_scratch(
            holder_idx,
            &teammates[holder_idx],
            true,
            PossessionControlState::default(),
            &opponents,
            &[],
            0.18,
            true,
            1,
            &cache,
            &config,
            &scratch,
        );
        let same_belief_candidate = build_shot_candidate_with_scratch(
            holder_idx,
            &teammates[holder_idx],
            true,
            PossessionControlState::default(),
            &opponents,
            &hidden_blocker,
            0.18,
            true,
            1,
            &cache,
            &config,
            &scratch,
        );
        let (
            candidate_xg,
            candidate_release_probability,
            candidate_block_probability,
            candidate_block_point,
        ) = match unobserved_candidate.action {
            RunnerHeldAction::Shoot {
                xg,
                release_probability,
                block_probability,
                block_point,
                ..
            } => (xg, release_probability, block_probability, block_point),
            action => panic!("expected shot candidate, got {action:?}"),
        };
        let (
            same_belief_xg,
            same_belief_release_probability,
            same_belief_block_probability,
            same_belief_block_point,
        ) = match same_belief_candidate.action {
            RunnerHeldAction::Shoot {
                xg,
                release_probability,
                block_probability,
                block_point,
                ..
            } => (xg, release_probability, block_probability, block_point),
            action => panic!("expected shot candidate, got {action:?}"),
        };
        assert_eq!(candidate_xg.to_bits(), same_belief_xg.to_bits());
        assert_eq!(
            candidate_release_probability.to_bits(),
            same_belief_release_probability.to_bits()
        );
        assert_eq!(
            candidate_block_probability.to_bits(),
            same_belief_block_probability.to_bits()
        );
        assert_eq!(candidate_block_point, same_belief_block_point);

        let unblocked_execution = evaluate_real_shot_execution(
            holder_idx,
            &teammates[holder_idx],
            true,
            &opponents,
            &[],
            PossessionControlState::default(),
            true,
            1,
            &cache,
            &config,
        );
        let blocked_execution = evaluate_real_shot_execution(
            holder_idx,
            &teammates[holder_idx],
            true,
            &opponents,
            &hidden_blocker,
            PossessionControlState::default(),
            true,
            1,
            &cache,
            &config,
        );
        assert_eq!(candidate_block_probability.to_bits(), 0.0f64.to_bits());
        assert!(
            blocked_execution.outcome.block_probability
                > unblocked_execution.outcome.block_probability + 0.05,
            "a hidden defender must remain absent from choice scoring but participate in the real shot contest"
        );
    }

    #[test]
    fn visible_defender_convergence_reduces_believed_shot_release() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Home {index}").as_str(), 82.0, 82.0))
            .collect::<Vec<_>>();
        let opponent_cards = (0..11)
            .map(|index| runner_test_card(format!("Away {index}").as_str(), 82.0, 82.0))
            .collect::<Vec<_>>();
        let mut teammates = build_players(&cards, formation_data("433"), true, 105.0, 68.0);
        let mut opponents =
            build_players(&opponent_cards, formation_data("433"), false, 105.0, 68.0);
        let holder_idx = 10;
        teammates[holder_idx].pos = (92.0, 34.0);
        teammates[holder_idx].target_pos = teammates[holder_idx].pos;
        teammates[holder_idx].last_receive_origin = (84.0, 34.0);
        opponents[0].pos = (102.0, 34.0);
        opponents[1].pos = (95.0, 34.0);
        let config = runtime_config(&json!({}));
        let cache = RefCell::new(HashMap::new());

        opponents[1].velocity = (0.0, 0.0);
        let static_scratch = held_decision_scratch_with_full_observation(
            holder_idx, &teammates, &opponents, &config,
        );
        let static_candidate = build_shot_candidate_with_scratch(
            holder_idx,
            &teammates[holder_idx],
            true,
            PossessionControlState::default(),
            &opponents,
            &[],
            0.18,
            true,
            1,
            &cache,
            &config,
            &static_scratch,
        );

        opponents[1].velocity = (-1.8, 0.0);
        let closing_scratch = held_decision_scratch_with_full_observation(
            holder_idx, &teammates, &opponents, &config,
        );
        let closing_candidate = build_shot_candidate_with_scratch(
            holder_idx,
            &teammates[holder_idx],
            true,
            PossessionControlState::default(),
            &opponents,
            &[],
            0.18,
            true,
            1,
            &cache,
            &config,
            &closing_scratch,
        );

        let body_release = |candidate: RunnerEvaluatedAction| match candidate.action {
            RunnerHeldAction::Shoot {
                body_release_probability,
                ..
            } => body_release_probability,
            action => panic!("expected shot candidate, got {action:?}"),
        };
        assert!(
            body_release(closing_candidate) < body_release(static_candidate),
            "visible radial convergence must reduce the holder's believed ability to release a shot"
        );
    }

    #[test]
    fn projected_controller_selection_preserves_reference_iteration_order() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Player {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let mut players = build_players(&cards, formation_data("433"), true, 105.0, 68.0);
        players[0].position = "GK".to_string();
        players[0].state = "off_ball".to_string();
        players[1].state = "stunned".to_string();
        for player in &mut players[2..] {
            player.state = "off_ball".to_string();
        }
        let projected_positions = [
            (0, 48.0, 34.0),
            (1, 51.5, 34.0),
            (2, 53.0, 34.0),
            (3, 53.0, 34.0),
            (4, 60.0, 34.0),
        ];
        let ball_pos = (52.0, 34.0);

        let reference_controller = players
            .iter()
            .enumerate()
            .filter(|(_, player)| player.position != "GK" && player.state != "stunned")
            .min_by(|(left_index, left), (right_index, right)| {
                distance(
                    projected_position(&projected_positions, *left_index, left.pos),
                    ball_pos,
                )
                .partial_cmp(&distance(
                    projected_position(&projected_positions, *right_index, right.pos),
                    ball_pos,
                ))
                .unwrap_or(std::cmp::Ordering::Equal)
            })
            .map(|(index, _)| index);

        assert_eq!(
            runner_projected_controller_index(&players, &projected_positions, ball_pos),
            reference_controller
        );
    }

    #[test]
    fn runner_rng_matches_python_random_seed_for_known_sequence() {
        let mut rng = RunnerRng::new(20260708);
        let expected = [
            0.03745044616550175,
            0.5373435693444919,
            0.42743285789357766,
            0.36923587014317016,
            0.2655924554793485,
            0.024004317727937985,
            0.6547114417572446,
            0.7083697411687409,
            0.5148515095807112,
            0.5818085255195788,
        ];
        for expected_value in expected {
            assert!((rng.random() - expected_value).abs() < 1e-15);
        }
    }

    #[test]
    fn runner_rng_preview_preserves_clone_semantics_across_twist_boundaries() {
        let mut rng = RunnerRng::new(20260708);
        for _ in 0..310 {
            let _ = rng.random();
        }

        for preview_count in [1usize, 2, 3] {
            let before = rng.clone();
            let mut expected_rng = rng.clone();
            let mut expected = [0.0; 3];
            for value in expected.iter_mut().take(preview_count) {
                *value = expected_rng.random();
            }

            let actual = match preview_count {
                1 => {
                    let values = preview_randoms::<1>(&rng);
                    [values[0], 0.0, 0.0]
                }
                2 => {
                    let values = preview_randoms::<2>(&rng);
                    [values[0], values[1], 0.0]
                }
                3 => preview_randoms::<3>(&rng),
                _ => unreachable!(),
            };
            for index in 0..preview_count {
                assert_eq!(actual[index].to_bits(), expected[index].to_bits());
            }
            assert_eq!(rng.index, before.index);
            assert_eq!(rng.draws, before.draws);
            assert_eq!(rng.mt, before.mt);
            assert_eq!(rng.gauss_next, before.gauss_next);

            let _ = rng.random();
        }
    }

    #[test]
    fn runner_rng_gauss_matches_python_random_seed_for_known_sequence() {
        let mut rng = RunnerRng::new(20260708);
        let expected = [
            1.2073731435999857,
            0.2894670856190923,
            -0.8619500061098534,
            0.4227159413127983,
            -0.021562136205345174,
        ];
        for expected_value in expected {
            assert!((rng.gauss(0.0, 1.0) - expected_value).abs() < 1e-15);
        }
    }

