fn pitch_clamp(pos: (f64, f64), length: f64, width: f64) -> (f64, f64) {
    (
        pos.0.clamp(0.5, length - 0.5),
        pos.1.clamp(0.5, width - 0.5),
    )
}

fn formation_to_pitch(
    coord: (f64, f64),
    attacking_right: bool,
    length: f64,
    width: f64,
) -> (f64, f64) {
    let depth_pct = (100.0 - coord.1) / 100.0;
    let x = if attacking_right {
        depth_pct * length
    } else {
        (1.0 - depth_pct) * length
    };
    pitch_clamp((x, coord.0), length, width)
}

fn initial_facing_direction(attacking_right: bool) -> f64 {
    if attacking_right {
        0.0
    } else {
        180.0
    }
}

fn card_string(card: &serde_json::Value, key: &str, default: String) -> String {
    card.get(key)
        .and_then(|value| value.as_str())
        .map(|value| value.to_string())
        .unwrap_or(default)
}

fn card_identity(card: &serde_json::Value, key: &str) -> serde_json::Value {
    card.get(key).cloned().unwrap_or(serde_json::Value::Null)
}

fn card_color(card: &serde_json::Value) -> String {
    match card.get("color").and_then(|value| value.as_str()) {
        Some("w" | "g" | "b" | "p" | "o" | "r" | "f" | "x" | "$") => {
            card_string(card, "color", "w".to_string())
        }
        _ => "w".to_string(),
    }
}

fn card_ability(card: &serde_json::Value, key: &str, default: f64) -> f64 {
    card.get(key)
        .and_then(|value| value.as_f64())
        .or_else(|| {
            card.get("abilities")
                .and_then(|abilities| abilities.get(key))
                .and_then(|value| value.as_f64())
        })
        .unwrap_or(default)
}

fn build_players(
    cards: &[serde_json::Value],
    formation: Formation,
    attacking_right: bool,
    length: f64,
    width: f64,
) -> Vec<RunnerPlayer> {
    (0..11)
        .map(|idx| {
            let empty = serde_json::Value::Null;
            let card = cards.get(idx).unwrap_or(&empty);
            let pos =
                formation_to_pitch(formation.coordinates[idx], attacking_right, length, width);
            let initial_facing_direction = initial_facing_direction(attacking_right);
            let name = card_string(card, "name", format!("Player {}", idx + 1));
            let color = card_color(card);
            RunnerPlayer {
                player_id: card_identity(card, "player_id"),
                colored_name: format!("/~{color}{name}/"),
                name,
                position: formation.positions[idx].to_string(),
                color,
                base_pos: pos,
                tactical_anchor: pos,
                pos,
                target_pos: pos,
                velocity: (0.0, 0.0),
                facing_direction: initial_facing_direction,
                last_receive_origin: pos,
                state: "off_ball".to_string(),
                stun_ticks_remaining: 0,
                movement_intent: "support".to_string(),
                last_def_action: String::new(),
                last_pressure_tick: -9999,
                goal_type: None,
                goal_phase: None,
                goal_target: pos,
                goal_value: 0.0,
                goal_created_tick: 0,
                goal_action_code: 3,
                tactical_task: TacticalTask::inactive(pos),
                tactical_belief: PlayerBelief::default(),
                tactical_task_tick: 0,
                finishing: card_ability(card, "Finishing", 50.0),
                long_shot: card_ability(card, "Long_Shot", 50.0),
                short_passing: card_ability(card, "Short_Passing", 50.0),
                long_passing: card_ability(card, "Long_Passing", 50.0),
                dribbling: card_ability(card, "Dribbling", 50.0),
                tackling: card_ability(card, "Tackling", 50.0),
                defence: card_ability(card, "Defence", 50.0),
                speed: card_ability(card, "Speed", 50.0),
                iq: card_ability(card, "IQ", 50.0),
                gk_saving: card_ability(card, "GK_Saving", 50.0),
                gk_positioning: card_ability(card, "GK_Positioning", 50.0),
                gk_reaction: card_ability(card, "GK_Reaction", 50.0),
                shots: 0,
                xg: 0.0,
                goals: 0,
                assists: 0,
                shots_on_target: 0,
                post_shot_xg: 0.0,
                saves: 0,
                goals_conceded: 0,
                psxg_faced: 0.0,
                shot_log: Vec::new(),
                holds: 0,
                passes_attempted: 0,
                passes_completed: 0,
                key_passes: 0,
                progressive_passes: 0,
                passes_into_final_third: 0,
                passes_into_box: 0,
                long_passes: 0,
                completed_long_passes: 0,
                crosses_attempted: 0,
                crosses_completed: 0,
                carries_attempted: 0,
                carries_completed: 0,
                dribbles_attempted: 0,
                dribbles_completed: 0,
                progressive_carries: 0,
                carries_into_final_third: 0,
                carries_into_box: 0,
                clearances: 0,
                blocks: 0,
                interceptions: 0,
                pressures: 0,
                successful_pressures: 0,
                tackles_attempted: 0,
                tackles_won: 0,
                turnovers: 0,
                dispossessed: 0,
                offsides: 0,
                distance_covered: 0.0,
                position_samples: Vec::new(),
                hold_ticks: 0,
                possession_ticks: 0,
                consecutive_carries: 0,
            }
        })
        .collect()
}

fn replay_header(
    home: &[RunnerPlayer],
    away: &[RunnerPlayer],
    home_formation: &str,
    away_formation: &str,
    width: f64,
    length: f64,
) -> serde_json::Value {
    json!({
        "type": "header",
        "home": {
            "name": "Home Team",
            "players": home.iter().map(|p| json!({
                "name": p.name,
                "player_id": p.player_id,
                "pos": p.position,
                "color": p.color,
                "colored_name": p.colored_name
            })).collect::<Vec<_>>()
        },
        "away": {
            "name": "Away Team",
            "players": away.iter().map(|p| json!({
                "name": p.name,
                "player_id": p.player_id,
                "pos": p.position,
                "color": p.color,
                "colored_name": p.colored_name
            })).collect::<Vec<_>>()
        },
        "formation_home": home_formation,
        "formation_away": away_formation,
        "field": {"width": width, "length": length}
    })
}

fn frame(
    tick: i32,
    tick_duration: f64,
    half: i32,
    home: &[RunnerPlayer],
    away: &[RunnerPlayer],
    ball_pos: (f64, f64),
    ball_holder_idx: Option<usize>,
    ball_team: Option<&'static str>,
    score: (i32, i32),
    cut: Option<bool>,
    ball_flight: Option<RunnerReplayBallFlight>,
    event_text: Option<&'static str>,
    pause_ms: Option<i32>,
) -> RunnerReplayFrame {
    assert!(
        home.len() == RUNNER_TEAM_SIZE && away.len() == RUNNER_TEAM_SIZE,
        "replay frames require two eleven-player teams"
    );
    let player_positions = |players: &[RunnerPlayer]| {
        std::array::from_fn(|idx| {
            let player = &players[idx];
            [round_one(player.pos.1), round_one(player.pos.0)]
        })
    };
    let player_goals = |players: &[RunnerPlayer]| {
        std::array::from_fn(|idx| {
            players[idx]
                .goal_type
                .as_deref()
                .map(RunnerReplayGoalText::from_player_goal)
        })
    };
    RunnerReplayFrame {
        entry_type: "frame",
        t: round_one(tick as f64 * tick_duration),
        half,
        home: player_positions(home),
        away: player_positions(away),
        home_player_goals: player_goals(home),
        away_player_goals: player_goals(away),
        ball: [round_one(ball_pos.1), round_one(ball_pos.0)],
        ball_holder: ball_holder_idx,
        ball_team,
        score: [score.0, score.1],
        ball_flight,
        event_text,
        pause_ms,
        cut,
    }
}

fn ball_state_name(state: RunnerBallState) -> &'static str {
    match state {
        RunnerBallState::Held => "held",
        RunnerBallState::InFlight => "in_flight",
        RunnerBallState::Dead => "dead",
        RunnerBallState::Contested => "contested",
    }
}

fn replay_flight_effective_end(flight: &RunnerFlight, config: &RunnerRuntimeConfig) -> (f64, f64) {
    if is_out_of_bounds(flight.target, config) {
        return crate::segment_pitch_boundary_crossing(
            flight.origin,
            flight.target,
            config.pitch_length,
            config.pitch_width,
        )
        .map(|crossing| crossing.point)
        .unwrap_or(flight.target);
    }
    if flight.kind == RunnerFlightKind::Pass {
        if let Some(arrival) = flight.arrival_plan.as_ref() {
            return arrival.contact_pos;
        }
    }
    flight.target
}

fn replay_flight_total_ticks(flight: &RunnerFlight) -> i32 {
    if flight.kind == RunnerFlightKind::Pass {
        if let Some(arrival) = flight.arrival_plan.as_ref() {
            if arrival.outcome_code == 1 && arrival.contact_tick < flight.ticks_total {
                return arrival.contact_tick.max(1);
            }
        }
    }
    flight.ticks_total.max(1)
}

fn replay_ball_flight(
    flight: Option<&RunnerFlight>,
    config: &RunnerRuntimeConfig,
) -> Option<RunnerReplayBallFlight> {
    let Some(flight) = flight else {
        return None;
    };
    let flight_type = match flight.kind {
        RunnerFlightKind::Pass => "pass",
        RunnerFlightKind::Clearance => "clear",
        RunnerFlightKind::Shot => "shot",
    };
    let effective_end = replay_flight_effective_end(flight, config);
    let total_ticks = replay_flight_total_ticks(flight);
    Some(RunnerReplayBallFlight {
        id: flight.replay_id,
        from: [round_one(flight.origin.1), round_one(flight.origin.0)],
        to: [round_one(flight.target.1), round_one(flight.target.0)],
        end: [round_one(effective_end.1), round_one(effective_end.0)],
        flight_type,
        on_target: flight.on_target,
        start_tick: flight.replay_start_tick,
        elapsed_ticks: flight.ticks_elapsed.min(total_ticks),
        total_ticks,
        complete: false,
        end_reason: None,
    })
}

fn terminal_replay_ball_flight(
    flight: &RunnerFlight,
    end_pos: (f64, f64),
    end_reason: &'static str,
    config: &RunnerRuntimeConfig,
) -> RunnerReplayBallFlight {
    let mut replay = replay_ball_flight(Some(flight), config)
        .expect("terminal replay flight requires an active flight");
    replay.end = [round_one(end_pos.1), round_one(end_pos.0)];
    replay.elapsed_ticks = replay.total_ticks;
    replay.complete = true;
    replay.end_reason = Some(end_reason);
    replay
}

fn reconcile_replay_flight_terminal_frames(
    replay: &mut [RunnerReplayEntry],
    terminal_frames: &[RunnerReplayFrame],
) {
    for terminal_frame in terminal_frames {
        let Some(terminal_flight) = terminal_frame.ball_flight.as_ref() else {
            continue;
        };
        if !terminal_flight.complete {
            continue;
        }
        let mut found_flight_sample = false;
        for entry in replay.iter_mut().rev() {
            let RunnerReplayEntry::Frame(frame) = entry else {
                continue;
            };
            let Some(flight) = frame.ball_flight.as_mut() else {
                if found_flight_sample {
                    break;
                }
                continue;
            };
            if flight.id == terminal_flight.id {
                flight.end = terminal_flight.end;
                found_flight_sample = true;
            } else if found_flight_sample {
                break;
            }
        }
    }
}

fn next_replay_flight_id(state: &mut RunnerMatchState) -> u64 {
    let id = state.next_replay_flight_id;
    state.next_replay_flight_id = state.next_replay_flight_id.saturating_add(1);
    id
}

fn queue_replay_frame(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    home: &[RunnerPlayer],
    away: &[RunnerPlayer],
    config: &RunnerRuntimeConfig,
    ball_flight: Option<RunnerReplayBallFlight>,
    event_text: Option<&'static str>,
    pause_ms: Option<i32>,
    ball_holder_idx: Option<usize>,
    ball_team: Option<&'static str>,
) {
    state.pending_replay_frames.push(frame(
        tick,
        config.tick_duration,
        half,
        home,
        away,
        state.ball.position,
        ball_holder_idx.or(state.ball.holder_idx),
        ball_team.or_else(|| {
            state
                .ball
                .holder_team_home
                .map(|home| if home { "home" } else { "away" })
        }),
        (state.home_score, state.away_score),
        ball_flight.as_ref().and_then(|flight| {
            flight
                .end_reason
                .and_then(RunnerReplayFlightEnd::from_name)
                .filter(|end| flight.complete && end.requires_replay_cut())
                .map(|_| true)
        }),
        ball_flight,
        event_text,
        pause_ms,
    ));
}

#[allow(clippy::too_many_arguments)]
fn queue_replay_flight_terminal_frame(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    home: &[RunnerPlayer],
    away: &[RunnerPlayer],
    config: &RunnerRuntimeConfig,
    flight: &RunnerFlight,
    ball_pos: (f64, f64),
    end_pos: (f64, f64),
    end: RunnerReplayFlightEnd,
    event_text: Option<&'static str>,
    pause_ms: Option<i32>,
    ball_holder_idx: Option<usize>,
    ball_team: Option<&'static str>,
) {
    state.pending_replay_frames.push(frame(
        tick,
        config.tick_duration,
        half,
        home,
        away,
        ball_pos,
        ball_holder_idx,
        ball_team,
        (state.home_score, state.away_score),
        end.requires_replay_cut().then_some(true),
        Some(terminal_replay_ball_flight(
            flight,
            end_pos,
            end.name(),
            config,
        )),
        event_text,
        pause_ms,
    ));
}

fn queue_restart_cut_frame(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    home: &[RunnerPlayer],
    away: &[RunnerPlayer],
    config: &RunnerRuntimeConfig,
) {
    state.pending_replay_frames.push(frame(
        tick,
        config.tick_duration,
        half,
        home,
        away,
        state.ball.position,
        state.ball.holder_idx,
        state
            .ball
            .holder_team_home
            .map(|home| if home { "home" } else { "away" }),
        (state.home_score, state.away_score),
        Some(true),
        None,
        None,
        None,
    ));
}

fn sample_player_positions(players: &mut [RunnerPlayer]) {
    for player in players {
        player
            .position_samples
            .push([round_one(player.pos.0), round_one(player.pos.1)]);
    }
}

fn all_ball_states() -> [RunnerBallState; 4] {
    [
        RunnerBallState::Held,
        RunnerBallState::InFlight,
        RunnerBallState::Dead,
        RunnerBallState::Contested,
    ]
}

fn round_one(value: f64) -> f64 {
    (value * 10.0).round_ties_even() / 10.0
}

fn round_two(value: f64) -> f64 {
    (value * 100.0).round_ties_even() / 100.0
}

fn round_rating(value: f64) -> f64 {
    format!("{:.1}", value)
        .parse::<f64>()
        .unwrap_or_else(|_| round_one(value))
}

fn player_rating(player: &RunnerPlayer, team_conceded: i32) -> f64 {
    let mut base = 6.0;
    base += player.goals as f64 * 1.0;
    base += player.assists as f64 * 0.5;
    if player.shots > 0 {
        base += (player.shots_on_target as f64 * 0.15).min(0.5);
    }
    if player.passes_attempted > 5 {
        let pass_rate = player.passes_completed as f64 / player.passes_attempted as f64;
        base += (pass_rate - 0.7) * 1.5;
    }
    if player.tackles_attempted > 0 {
        let tackle_rate = player.tackles_won as f64 / player.tackles_attempted as f64;
        base += tackle_rate * 0.3;
    }
    base += player.interceptions as f64 * 0.1;
    if player.position == "GK" {
        base += player.saves as f64 * 0.3;
        base -= team_conceded as f64 * 0.2;
    }
    if player.dribbles_attempted > 0 {
        let dribble_rate = player.dribbles_completed as f64 / player.dribbles_attempted as f64;
        base += dribble_rate * 0.2;
    }
    if player.carries_attempted > 0 {
        let carry_rate = player.carries_completed as f64 / player.carries_attempted as f64;
        base += carry_rate * 0.15;
    }
    if player.crosses_attempted > 0 {
        let cross_rate = player.crosses_completed as f64 / player.crosses_attempted as f64;
        base += cross_rate * 0.2;
    }
    round_rating(base.clamp(1.0, 10.0))
}

fn team_ratings(players: &[RunnerPlayer], team_conceded: i32) -> Vec<serde_json::Value> {
    players
        .iter()
        .map(|player| {
            json!({
                "name": player.name,
                "player_id": player.player_id,
                "color": player.color,
                "colored_name": player.colored_name,
                "position": player.position,
                "rating": player_rating(player, team_conceded)
            })
        })
        .collect()
}

fn player_stat_skeleton(
    players: &[RunnerPlayer],
    _team_home: bool,
    _pass_network: &RunnerPassNetwork,
) -> Vec<serde_json::Value> {
    players
        .iter()
        .enumerate()
        .map(|(_idx, player)| {
            let _ability_read = player.finishing
                + player.long_shot
                + player.short_passing
                + player.long_passing
                + player.dribbling
                + player.speed
                + player.iq
                + player.gk_saving
                + player.gk_positioning
                + player.gk_reaction
                + player.holds as f64;
            json!({
                "name": player.name,
                "player_id": player.player_id,
                "color": player.color,
                "colored_name": player.colored_name,
                "position": player.position,
                "goals": player.goals,
                "assists": player.assists,
                "shots": player.shots,
                "shots_on_target": player.shots_on_target,
                "xg": round_two(player.xg),
                "npxg": round_two(player.xg),
                "post_shot_xg": round_two(player.post_shot_xg),
                "big_chances": player.shot_log.iter().filter(|shot| shot.get("xg").and_then(|value| value.as_f64()).unwrap_or(0.0) > 0.3).count(),
                "big_chances_missed": player.shot_log.iter().filter(|shot| {
                    shot.get("xg").and_then(|value| value.as_f64()).unwrap_or(0.0) > 0.3
                        && shot.get("outcome").and_then(|value| value.as_str()).unwrap_or("") != "goal"
                }).count(),
                "passes": player.passes_attempted,
                "completed_passes": player.passes_completed,
                "key_passes": player.key_passes,
                "xa": round_two(player.key_passes as f64 * 0.12),
                "progressive_passes": player.progressive_passes,
                "passes_into_final_third": player.passes_into_final_third,
                "passes_into_box": player.passes_into_box,
                "long_passes": player.long_passes,
                "completed_long_passes": player.completed_long_passes,
                "crosses": player.crosses_attempted,
                "successful_crosses": player.crosses_completed,
                "carries": player.carries_attempted,
                "carries_completed": player.carries_completed,
                "progressive_carries": player.progressive_carries,
                "carries_into_final_third": player.carries_into_final_third,
                "carries_into_box": player.carries_into_box,
                "take_ons": player.dribbles_attempted,
                "successful_take_ons": player.dribbles_completed,
                "tackles_attempted": player.tackles_attempted,
                "tackles_won": player.tackles_won,
                "interceptions": player.interceptions,
                "blocks": player.blocks,
                "clearances": player.clearances,
                "pressures": player.pressures,
                "successful_pressures": player.successful_pressures,
                "turnovers": player.turnovers,
                "dispossessed": player.dispossessed,
                "offsides": player.offsides,
                "saves": player.saves,
                "goals_conceded": player.goals_conceded,
                "psxg_faced": round_two(player.psxg_faced),
                "goals_prevented": if player.position == "GK" { round_two(player.psxg_faced - player.goals_conceded as f64) } else { 0.0 },
                "rating": player_rating(player, player.goals_conceded),
                "shot_log": player.shot_log,
                "pass_network": {},
                "position_samples": player.position_samples,
                "distance_covered": round_one(player.distance_covered)
            })
        })
        .collect()
}

fn team_stats(
    players: &[RunnerPlayer],
    possession: f64,
    events: &[serde_json::Value],
    team_home: bool,
) -> serde_json::Value {
    let passes = players
        .iter()
        .map(|player| player.passes_attempted)
        .sum::<i32>();
    let completed = players
        .iter()
        .map(|player| player.passes_completed)
        .sum::<i32>();
    let shots_in_box = players
        .iter()
        .flat_map(|player| player.shot_log.iter())
        .filter(|shot| {
            shot.get("in_box")
                .and_then(|value| value.as_bool())
                .unwrap_or(false)
        })
        .count() as i32;
    let shots = players.iter().map(|player| player.shots).sum::<i32>();
    let xg = players.iter().map(|player| player.xg).sum::<f64>();
    let post_shot_xg = players
        .iter()
        .map(|player| player.post_shot_xg)
        .sum::<f64>();
    let event_side = if team_home { "home" } else { "away" };
    let event_count = |event_type: &str, outcome: Option<&str>| -> i32 {
        events
            .iter()
            .filter(|event| {
                event.get("team_side").and_then(|value| value.as_str()) == Some(event_side)
                    && event.get("event_type").and_then(|value| value.as_str()) == Some(event_type)
                    && outcome
                        .map(|expected| {
                            event.get("outcome").and_then(|value| value.as_str()) == Some(expected)
                        })
                        .unwrap_or(true)
            })
            .count() as i32
    };
    json!({
        "shots": shots,
        "shots_on_target": players.iter().map(|player| player.shots_on_target).sum::<i32>(),
        "shots_in_box": shots_in_box,
        "shots_outside_box": (shots - shots_in_box).max(0),
        "passes": passes,
        "passes_completed": completed,
        "pass_success_rate": if passes > 0 { round_one(completed as f64 / passes as f64 * 100.0) } else { 0.0 },
        "progressive_passes": players.iter().map(|player| player.progressive_passes).sum::<i32>(),
        "passes_into_final_third": players.iter().map(|player| player.passes_into_final_third).sum::<i32>(),
        "passes_into_box": players.iter().map(|player| player.passes_into_box).sum::<i32>(),
        "long_passes": players.iter().map(|player| player.long_passes).sum::<i32>(),
        "completed_long_passes": players.iter().map(|player| player.completed_long_passes).sum::<i32>(),
        "tackles": players.iter().map(|player| player.tackles_won).sum::<i32>(),
        "tackles_won": players.iter().map(|player| player.tackles_won).sum::<i32>(),
        "tackle_attempts": players.iter().map(|player| player.tackles_attempted).sum::<i32>(),
        "interceptions": players.iter().map(|player| player.interceptions).sum::<i32>(),
        "clearances": players.iter().map(|player| player.clearances).sum::<i32>(),
        "dribbles": players.iter().map(|player| player.dribbles_completed).sum::<i32>(),
        "dribbles_completed": players.iter().map(|player| player.dribbles_completed).sum::<i32>(),
        "take_ons": players.iter().map(|player| player.dribbles_attempted).sum::<i32>(),
        "successful_take_ons": players.iter().map(|player| player.dribbles_completed).sum::<i32>(),
        "saves": players.iter().map(|player| player.saves).sum::<i32>(),
        "goals": players.iter().map(|player| player.goals).sum::<i32>(),
        "distance_covered": players.iter().map(|player| player.distance_covered).sum::<f64>(),
        "carries": players.iter().map(|player| player.carries_attempted).sum::<i32>(),
        "carries_completed": players.iter().map(|player| player.carries_completed).sum::<i32>(),
        "progressive_carries": players.iter().map(|player| player.progressive_carries).sum::<i32>(),
        "carries_into_final_third": players.iter().map(|player| player.carries_into_final_third).sum::<i32>(),
        "carries_into_box": players.iter().map(|player| player.carries_into_box).sum::<i32>(),
        "crosses": players.iter().map(|player| player.crosses_attempted).sum::<i32>(),
        "crosses_completed": players.iter().map(|player| player.crosses_completed).sum::<i32>(),
        "key_passes": players.iter().map(|player| player.key_passes).sum::<i32>(),
        "pressures": players.iter().map(|player| player.pressures).sum::<i32>(),
        "successful_pressures": players.iter().map(|player| player.successful_pressures).sum::<i32>(),
        "blocks": players.iter().map(|player| player.blocks).sum::<i32>(),
        "turnovers": players.iter().map(|player| player.turnovers).sum::<i32>(),
        "offsides": players.iter().map(|player| player.offsides).sum::<i32>(),
        "xg": round_two(xg),
        "post_shot_xg": round_two(post_shot_xg),
        "big_chances": players.iter().flat_map(|player| player.shot_log.iter()).filter(|shot| shot.get("xg").and_then(|value| value.as_f64()).unwrap_or(0.0) >= 0.3).count(),
        "corners": event_count("restart", Some("corner")),
        "goal_kicks": event_count("restart", Some("goal_kick")),
        "throw_ins": event_count("restart", Some("throw_in")),
        "free_kicks": event_count("restart", Some("offside")),
        "headers": 0,
        "headers_won": 0,
        "possession": possession
    })
}

fn shot_log_sum(player: &RunnerPlayer) -> f64 {
    player
        .shot_log
        .iter()
        .map(|entry| {
            entry
                .get("xg")
                .and_then(|value| value.as_f64())
                .unwrap_or(0.0)
        })
        .sum()
}

fn shot_log_json(entry: &ShotLogEntryOutput) -> serde_json::Value {
    let mut value = json!({
        "x": entry.x,
        "y": entry.y,
        "xg": entry.xg,
        "in_box": entry.in_box,
        "outcome": entry.outcome,
    });
    if let serde_json::Value::Object(ref mut map) = value {
        if let Some(target_x) = entry.target_x {
            map.insert("target_x".to_string(), json!(target_x));
        }
        if let Some(target_y) = entry.target_y {
            map.insert("target_y".to_string(), json!(target_y));
        }
    }
    value
}

fn reset_formation_slots(
    players: &mut [RunnerPlayer],
    formation: Formation,
    attacking_right: bool,
    length: f64,
    width: f64,
) {
    for (idx, player) in players.iter_mut().enumerate() {
        let pos = formation_to_pitch(formation.coordinates[idx], attacking_right, length, width);
        player.base_pos = pos;
        player.tactical_anchor = pos;
        player.pos = pos;
        player.target_pos = pos;
        player.velocity = (0.0, 0.0);
        player.facing_direction = initial_facing_direction(attacking_right);
        player.tactical_task = TacticalTask::inactive(pos);
        player.tactical_belief = PlayerBelief::default();
        player.tactical_task_tick = 0;
    }
}

fn reset_players_to_current_formation_slots(players: &mut [RunnerPlayer], attacking_right: bool) {
    for player in players.iter_mut() {
        let pos = player.base_pos;
        player.tactical_anchor = pos;
        player.pos = pos;
        player.target_pos = pos;
        player.velocity = (0.0, 0.0);
        player.facing_direction = initial_facing_direction(attacking_right);
        player.tactical_task = TacticalTask::inactive(pos);
        player.tactical_belief = PlayerBelief::default();
        player.tactical_task_tick = 0;
    }
}

fn clear_player_goal(player: &mut RunnerPlayer) {
    player.goal_type = None;
    player.goal_phase = None;
    player.goal_target = player.pos;
    player.goal_value = 0.0;
    player.goal_created_tick = 0;
    player.goal_action_code = 3;
    player.tactical_task = TacticalTask::inactive(player.tactical_anchor);
}

fn clear_team_goals(players: &mut [RunnerPlayer]) {
    for player in players {
        clear_player_goal(player);
    }
}

fn possession_team_changes(current_team_home: Option<bool>, next_team_home: bool) -> bool {
    current_team_home != Some(next_team_home)
}

fn attacking_right_for(holder_home: bool, home_attacking_right: bool) -> bool {
    if holder_home {
        home_attacking_right
    } else {
        !home_attacking_right
    }
}

fn phase_name(phase_code: u8) -> &'static str {
    match phase_code {
        1 => "transition_atk",
        2 => "defending",
        3 => "transition_def",
        4 => "contesting",
        _ => "attacking",
    }
}

fn update_team_phases(state: &mut RunnerMatchState, config: &RunnerRuntimeConfig) {
    let ball_contested = state.ball.state == RunnerBallState::Contested;
    let home_update = crate::team_phase_update(&TeamPhaseUpdateInput {
        has_possession: state.ball.state == RunnerBallState::Held
            && state.ball.holder_team_home == Some(true),
        ball_contested,
        had_possession_last_tick: state.home_had_possession_last_tick,
        ticks_since_possession_change: state.home_ticks_since_possession_change,
        transition_ticks: config.transition_ticks,
    });
    state.home_phase_code = home_update.phase_code;
    state.home_had_possession_last_tick = home_update.had_possession_last_tick;
    state.home_ticks_since_possession_change = home_update.ticks_since_possession_change;

    let away_update = crate::team_phase_update(&TeamPhaseUpdateInput {
        has_possession: state.ball.state == RunnerBallState::Held
            && state.ball.holder_team_home == Some(false),
        ball_contested,
        had_possession_last_tick: state.away_had_possession_last_tick,
        ticks_since_possession_change: state.away_ticks_since_possession_change,
        transition_ticks: config.transition_ticks,
    });
    state.away_phase_code = away_update.phase_code;
    state.away_had_possession_last_tick = away_update.had_possession_last_tick;
    state.away_ticks_since_possession_change = away_update.ticks_since_possession_change;
}

fn execution_opponents_into(
    players: &[RunnerPlayer],
    output: &mut [ExecutionOpponent; RUNNER_TEAM_SIZE],
) -> usize {
    assert!(
        players.len() <= RUNNER_TEAM_SIZE,
        "execution opponents expect eleven-player teams"
    );
    for (index, player) in players.iter().enumerate() {
        output[index] = ExecutionOpponent {
            pos: player.pos,
            is_goalkeeper: player.position == "GK",
        };
    }
    players.len()
}

fn runner_static_movement_intent(intent: &str) -> &'static str {
    match intent {
        "idle" => "idle",
        "attack_run" => "attack_run",
        "press" => "press",
        "contest" => "contest",
        "mark" => "mark",
        "block_lane" => "block_lane",
        "recover_shape" => "recover_shape",
        "defend_shape" => "defend_shape",
        _ => "support",
    }
}

fn runner_arrival_player_input(
    index: usize,
    player: &RunnerPlayer,
    is_passer: bool,
    is_intended: bool,
    is_passer_team: bool,
) -> ArrivalPlayerInput {
    ArrivalPlayerInput {
        index,
        pos: player.pos,
        velocity: player.velocity,
        target_pos: player.target_pos,
        current_goal_pos: Some(player.target_pos),
        movement_intent: runner_static_movement_intent(player.movement_intent.as_str()),
        speed: player.speed.round() as i32,
        can_arrive: player.state != "stunned",
        is_passer,
        is_intended,
        is_passer_team,
    }
}

fn runner_pass_arrival_plan(
    passer_idx: usize,
    intended_receiver_idx: Option<usize>,
    target: (f64, f64),
    origin: (f64, f64),
    flight_speed: f64,
    flight_ticks_total: i32,
    receivers: &[RunnerPlayer],
    opponents: &[RunnerPlayer],
    config: &RunnerRuntimeConfig,
) -> crate::PassArrivalPlanOutput {
    let snapshot = runner_pass_arrival_snapshot(
        passer_idx,
        intended_receiver_idx,
        target,
        receivers,
        opponents,
    );
    runner_pass_arrival_plan_from_snapshot(
        snapshot,
        target,
        origin,
        flight_speed,
        flight_ticks_total,
        config,
    )
}

fn runner_pass_arrival_snapshot(
    passer_idx: usize,
    intended_receiver_idx: Option<usize>,
    target: (f64, f64),
    receivers: &[RunnerPlayer],
    opponents: &[RunnerPlayer],
) -> RunnerPassArrivalSnapshot {
    assert!(
        receivers.len() <= RUNNER_TEAM_SIZE && opponents.len() <= RUNNER_TEAM_SIZE,
        "pass arrival expects eleven-player teams"
    );
    let mut arrival_receivers = [ArrivalPlayerInput {
        index: 0,
        pos: (0.0, 0.0),
        velocity: (0.0, 0.0),
        target_pos: (0.0, 0.0),
        current_goal_pos: None,
        movement_intent: "idle",
        speed: 0,
        can_arrive: false,
        is_passer: false,
        is_intended: false,
        is_passer_team: true,
    }; RUNNER_TEAM_SIZE];
    let mut arrival_opponents = [ArrivalPlayerInput {
        index: 0,
        pos: (0.0, 0.0),
        velocity: (0.0, 0.0),
        target_pos: (0.0, 0.0),
        current_goal_pos: None,
        movement_intent: "idle",
        speed: 0,
        can_arrive: false,
        is_passer: false,
        is_intended: false,
        is_passer_team: false,
    }; RUNNER_TEAM_SIZE];
    for (index, player) in receivers.iter().enumerate() {
        arrival_receivers[index] = runner_arrival_player_input(
            index,
            player,
            index == passer_idx,
            intended_receiver_idx == Some(index),
            true,
        );
        if intended_receiver_idx == Some(index) {
            arrival_receivers[index].target_pos = target;
            arrival_receivers[index].current_goal_pos = Some(target);
        }
    }
    for (index, player) in opponents.iter().enumerate() {
        arrival_opponents[index] = runner_arrival_player_input(index, player, false, false, false);
    }
    RunnerPassArrivalSnapshot {
        receivers: arrival_receivers,
        receiver_count: receivers.len(),
        opponents: arrival_opponents,
        opponent_count: opponents.len(),
    }
}

fn runner_pass_arrival_plan_from_snapshot(
    snapshot: RunnerPassArrivalSnapshot,
    target: (f64, f64),
    origin: (f64, f64),
    flight_speed: f64,
    flight_ticks_total: i32,
    config: &RunnerRuntimeConfig,
) -> crate::PassArrivalPlanOutput {
    pass_arrival_plan(&PassArrivalPlanInput {
        target_pos: target,
        flight_origin: origin,
        flight_speed,
        flight_ticks_total,
        contest_radius: config.contest_radius,
        player_max_speed: config.player_max_speed,
        player_min_speed: config.player_min_speed,
        target_occupation_weight: 0.18,
        receivers: &snapshot.receivers[..snapshot.receiver_count],
        opponents: &snapshot.opponents[..snapshot.opponent_count],
    })
}

fn runner_receiver_arrival_index(arrival: &crate::PassArrivalPlanOutput) -> Option<usize> {
    (arrival.outcome_code == 0 && arrival.receiver_control > arrival.loose_control)
        .then_some(arrival.receiver_index)
        .flatten()
}

fn clearance_players(players: &[RunnerPlayer]) -> Vec<ClearancePlayerInput> {
    players
        .iter()
        .enumerate()
        .map(|(idx, player)| ClearancePlayerInput {
            index: idx,
            pos: player.pos,
        })
        .collect()
}

fn contested_target_players_into(
    players: &[RunnerPlayer],
    output: &mut [ContestedTargetPlayerInput; RUNNER_TEAM_SIZE],
) -> usize {
    assert!(
        players.len() <= RUNNER_TEAM_SIZE,
        "contested target players exceed team size"
    );
    for (idx, player) in players.iter().enumerate() {
        output[idx] = ContestedTargetPlayerInput {
            index: idx,
            pos: player.pos,
            tactical_anchor: player.tactical_anchor,
            is_goalkeeper: player.position == "GK",
            is_stunned: player.state == "stunned",
            speed: player.speed.round() as i32,
            iq: player.iq,
        };
    }
    players.len()
}

fn runner_single_active_indices(
    active_index: usize,
    player_count: usize,
) -> [bool; RUNNER_TEAM_SIZE] {
    assert!(
        player_count <= RUNNER_TEAM_SIZE && active_index < player_count,
        "active player index exceeds team size"
    );
    let mut active_indices = [false; RUNNER_TEAM_SIZE];
    active_indices[active_index] = true;
    active_indices
}

fn runner_flight_defense_active_indices(
    players: &[RunnerPlayer],
    target_pos: (f64, f64),
    race_radius: f64,
    interceptor_index: Option<usize>,
) -> [bool; RUNNER_TEAM_SIZE] {
    assert!(
        players.len() <= RUNNER_TEAM_SIZE,
        "flight defense active players exceed team size"
    );
    let mut active_indices = [false; RUNNER_TEAM_SIZE];
    for (index, player) in players.iter().enumerate() {
        active_indices[index] = player.state != "stunned"
            && player.position != "GK"
            && interceptor_index != Some(index)
            && distance(player.pos, target_pos) < race_radius * 1.25;
    }
    active_indices
}

fn give_ball(state: &mut RunnerMatchState, idx: usize, team_home: bool, pos: (f64, f64)) {
    state.ball.state = RunnerBallState::Held;
    state.ball.position = pos;
    state.ball.holder_idx = Some(idx);
    state.ball.holder_team_home = Some(team_home);
    state.ball.flight = None;
    state.ball.loose_velocity = (0.0, 0.0);
    state.ball.contested_ticks = 0;
    state.ball.contest_challenge = None;
    state.action_commitment = None;
}

fn set_offside_phase(
    state: &mut RunnerMatchState,
    passer_team_home: bool,
    passer_idx: usize,
    origin: (f64, f64),
    flags: [bool; RUNNER_TEAM_SIZE],
) {
    state.ball.offside_phase = Some(RunnerOffsidePhase {
        passer_team_home,
        passer_idx,
        origin,
        flags,
        possession_id: state.possession_id,
    });
}

fn offside_phase_flagged_receiver(
    state: &RunnerMatchState,
    team_home: bool,
    player_idx: usize,
) -> Option<RunnerOffsidePhase> {
    state.ball.offside_phase.filter(|phase| {
        phase.passer_team_home == team_home
            && phase.passer_idx != player_idx
            && phase.possession_id == state.possession_id
            && phase.flags.get(player_idx).copied().unwrap_or(false)
    })
}

fn clear_offside_phase_after_touch(state: &mut RunnerMatchState) {
    state.ball.offside_phase = None;
}

fn enforce_offside_phase_at_touch(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    team_home: bool,
    player_idx: usize,
    touch_pos: (f64, f64),
    config: &RunnerRuntimeConfig,
) -> bool {
    let Some(phase) = offside_phase_flagged_receiver(state, team_home, player_idx) else {
        return false;
    };
    let passer_identity = if phase.passer_team_home {
        player_identity(home, phase.passer_idx)
    } else {
        player_identity(away, phase.passer_idx)
    };
    let receiver_identity = if team_home {
        player_identity(home, player_idx)
    } else {
        player_identity(away, player_idx)
    };
    let receiver_name = {
        let team = if team_home { &mut *home } else { &mut *away };
        team.get_mut(player_idx)
            .map(|player| {
                player.offsides += 1;
                player.name.clone()
            })
            .unwrap_or_default()
    };
    set_dead_ball_and_clear_goals(
        state,
        home,
        away,
        "offside",
        !phase.passer_team_home,
        2,
        touch_pos,
    );
    trace_entry!(
        state,
        json!({
            "tick": tick,
            "type": "event",
            "event": "offside",
            "player": receiver_name,
            "team": if team_home { "home" } else { "away" },
            "source": "offside_phase",
            "origin": [round_one(phase.origin.0), round_one(phase.origin.1)]
        })
    );
    record_match_event(
        state,
        config,
        MatchEventInput {
            tick,
            half,
            possession_id: phase.possession_id,
            event_type: "offside",
            team_home: phase.passer_team_home,
            player: passer_identity,
            target_player: receiver_identity,
            assist_player: serde_json::Value::Null,
            outcome: "offside",
            xg: 0.0,
            origin: Some(phase.origin),
            target: Some(touch_pos),
            tags: EventTags::from_slice(&["offside", "second_ball"]),
            score_before: None,
        },
    );
    true
}

fn give_ball_to_player(
    state: &mut RunnerMatchState,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    idx: usize,
    team_home: bool,
    pos: (f64, f64),
    receive_origin: Option<(f64, f64)>,
    home_attacking_right: bool,
    config: &RunnerRuntimeConfig,
) {
    let possession_changed = possession_team_changes(state.possession_team_home, team_home);
    let controller_changed = !matches!(
        (state.ball.holder_idx, state.ball.holder_team_home),
        (Some(previous_idx), Some(previous_home))
            if previous_idx == idx && previous_home == team_home
    );
    let previous_control = if possession_changed || controller_changed || receive_origin.is_none() {
        PossessionControlState::default()
    } else {
        state.ball.control
    };
    if possession_changed {
        state.possession_id += 1;
        state.possession_team_home = Some(team_home);
        clear_team_goals(home);
        clear_team_goals(away);
    }
    clear_offside_phase_after_touch(state);
    if let (Some(prev_idx), Some(prev_home)) = (state.ball.holder_idx, state.ball.holder_team_home)
    {
        if prev_home {
            if let Some(player) = home.get_mut(prev_idx) {
                update_runner_text(&mut player.state, "off_ball");
                clear_player_goal(player);
            }
        } else if let Some(player) = away.get_mut(prev_idx) {
            update_runner_text(&mut player.state, "off_ball");
            clear_player_goal(player);
        }
    }
    let mut ball_pos = pos;
    let mut arrival_heading = receive_origin
        .map(|origin| angle_between_points(pos, origin))
        .unwrap_or(0.0);
    if team_home {
        if let Some(player) = home.get_mut(idx) {
            update_runner_text(&mut player.state, "on_ball");
            player.hold_ticks = 0;
            player.possession_ticks = 0;
            player.consecutive_carries = 0;
            player.last_receive_origin = receive_origin.unwrap_or(player.pos);
            ball_pos = player.pos;
            arrival_heading = receive_origin
                .map(|origin| angle_between_points(ball_pos, origin))
                .unwrap_or(player.facing_direction);
            clear_player_goal(player);
        }
    } else if let Some(player) = away.get_mut(idx) {
        update_runner_text(&mut player.state, "on_ball");
        player.hold_ticks = 0;
        player.possession_ticks = 0;
        player.consecutive_carries = 0;
        player.last_receive_origin = receive_origin.unwrap_or(player.pos);
        ball_pos = player.pos;
        arrival_heading = receive_origin
            .map(|origin| angle_between_points(ball_pos, origin))
            .unwrap_or(player.facing_direction);
        clear_player_goal(player);
    }
    give_ball(state, idx, team_home, ball_pos);
    let (controlling_players, defending_players) = if team_home {
        (&*home, &*away)
    } else {
        (&*away, &*home)
    };
    let ownership_continuity = if possession_changed || controller_changed {
        0.0
    } else if receive_origin.is_some() {
        1.0
    } else {
        0.0
    };
    state.ball.control = runner_live_control_transition(
        previous_control,
        idx,
        ball_pos,
        controlling_players,
        defending_players,
        attacking_right_for(team_home, home_attacking_right),
        arrival_heading,
        ownership_continuity,
        0.0,
        receive_origin.map(|_| 1).unwrap_or(0),
        receive_origin
            .map(|origin| distance(origin, ball_pos))
            .unwrap_or(0.0),
        None,
        config.pitch_length,
        config.pitch_width,
    );
}

fn tick_player_stun(player: &mut RunnerPlayer) {
    if player.state != "stunned" {
        return;
    }
    let stun = player_tick_stun(&PlayerTickStunInput {
        state: player.state.as_str(),
        stun_ticks_remaining: player.stun_ticks_remaining,
    });
    player.state = stun.state;
    player.stun_ticks_remaining = stun.stun_ticks_remaining;
}

fn tick_stunned_players(players: &mut [RunnerPlayer]) {
    for player in players {
        tick_player_stun(player);
    }
}

fn apply_stun_to_player(player: &mut RunnerPlayer, config: &RunnerRuntimeConfig) {
    let stun = player_apply_stun(&PlayerApplyStunInput {
        tackle_fail_stun_seconds: config.tackle_fail_stun_seconds,
        tick_duration: config.tick_duration,
    });
    player.state = stun.state;
    player.stun_ticks_remaining = stun.stun_ticks_remaining;
}

fn set_dead_ball(
    state: &mut RunnerMatchState,
    reason: &str,
    restart_team_home: bool,
    restart_ticks: i32,
    ball_pos: (f64, f64),
) {
    state.ball.state = RunnerBallState::Dead;
    state.ball.position = ball_pos;
    state.ball.holder_idx = None;
    state.ball.holder_team_home = None;
    state.ball.flight = None;
    state.ball.loose_velocity = (0.0, 0.0);
    state.ball.contest_challenge = None;
    state.ball.offside_phase = None;
    state.action_commitment = None;
    state.dead_reason = Some(reason.to_string());
    state.restart_team_home = Some(restart_team_home);
    state.restart_ticks_remaining = restart_ticks.max(0);
}

fn set_dead_ball_and_clear_goals(
    state: &mut RunnerMatchState,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    reason: &str,
    restart_team_home: bool,
    restart_ticks: i32,
    ball_pos: (f64, f64),
) {
    clear_team_goals(home);
    clear_team_goals(away);
    set_dead_ball(state, reason, restart_team_home, restart_ticks, ball_pos);
}

fn set_contested(state: &mut RunnerMatchState, pos: (f64, f64), loose_velocity: (f64, f64)) {
    state.ball.state = RunnerBallState::Contested;
    state.ball.position = pos;
    state.ball.holder_idx = None;
    state.ball.holder_team_home = None;
    state.ball.flight = None;
    state.ball.loose_velocity = loose_velocity;
    state.ball.contested_ticks = 0;
    state.ball.contest_challenge = None;
    state.action_commitment = None;
}

fn set_contested_from_challenge(
    state: &mut RunnerMatchState,
    pos: (f64, f64),
    loose_velocity: (f64, f64),
    challenge: RunnerContestChallenge,
) {
    set_contested(state, pos, loose_velocity);
    state.ball.contest_challenge = Some(challenge);
}

fn set_contested_and_clear_goals(
    state: &mut RunnerMatchState,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    pos: (f64, f64),
    loose_velocity: (f64, f64),
) {
    clear_team_goals(home);
    clear_team_goals(away);
    set_contested(state, pos, loose_velocity);
}

fn set_contested_from_challenge_and_clear_goals(
    state: &mut RunnerMatchState,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    pos: (f64, f64),
    loose_velocity: (f64, f64),
    challenge: RunnerContestChallenge,
) {
    clear_team_goals(home);
    clear_team_goals(away);
    set_contested_from_challenge(state, pos, loose_velocity, challenge);
}

fn settle_contest_challenge(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    winner_idx: usize,
    winner_home: bool,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    config: &RunnerRuntimeConfig,
) {
    let Some(challenge) = state.ball.contest_challenge.take() else {
        return;
    };
    let challenger_identity = if challenge.challenger_team_home {
        player_identity(home, challenge.challenger_idx)
    } else {
        player_identity(away, challenge.challenger_idx)
    };
    let holder_identity = if challenge.holder_team_home {
        player_identity(home, challenge.holder_idx)
    } else {
        player_identity(away, challenge.holder_idx)
    };
    let challenger_name = if challenge.challenger_team_home {
        runner_player_name(home, challenge.challenger_idx)
    } else {
        runner_player_name(away, challenge.challenger_idx)
    }
    .to_string();
    let holder_name = if challenge.holder_team_home {
        runner_player_name(home, challenge.holder_idx)
    } else {
        runner_player_name(away, challenge.holder_idx)
    }
    .to_string();
    let winner_name = if winner_home {
        runner_player_name(home, winner_idx)
    } else {
        runner_player_name(away, winner_idx)
    }
    .to_string();
    let recovered = winner_home == challenge.challenger_team_home;
    let event_type = if challenge.records_tackle_attempt {
        "tackle"
    } else {
        "duel"
    };
    let context = match challenge.context {
        RunnerDuelContext::Carry => "carry",
        RunnerDuelContext::Hold | RunnerDuelContext::Reorient => "control",
        RunnerDuelContext::Pass => "pass_release",
    };

    trace_entry!(
        state,
        json!({
            "tick": tick,
            "type": "event",
            "event": if challenge.records_tackle_attempt {
                "tackle_settlement"
            } else {
                "pressure_settlement"
            },
            "outcome": if recovered { "won" } else { "lost" },
            "challenger": challenger_name,
            "holder": holder_name,
            "recovered_by": winner_name,
            "recovery_team": if winner_home { "home" } else { "away" },
            "context": context,
            "origin": [round_one(challenge.origin.0), round_one(challenge.origin.1)]
        })
    );

    if !recovered {
        if challenge.records_tackle_attempt {
            let challenger = if challenge.challenger_team_home {
                home.get_mut(challenge.challenger_idx)
            } else {
                away.get_mut(challenge.challenger_idx)
            };
            if let Some(challenger) = challenger {
                apply_stun_to_player(challenger, config);
            }
        }
        return;
    }

    if challenge.challenger_team_home {
        if let Some(challenger) = home.get_mut(challenge.challenger_idx) {
            if challenge.records_tackle_attempt {
                challenger.tackles_won += 1;
            }
        }
        if let Some(holder) = away.get_mut(challenge.holder_idx) {
            holder.dispossessed += 1;
            holder.turnovers += 1;
        }
    } else {
        if let Some(challenger) = away.get_mut(challenge.challenger_idx) {
            if challenge.records_tackle_attempt {
                challenger.tackles_won += 1;
            }
        }
        if let Some(holder) = home.get_mut(challenge.holder_idx) {
            holder.dispossessed += 1;
            holder.turnovers += 1;
        }
    }

    let mut tags = EventTags::from_slice(&["possession_won", "second_ball", "challenge_recovery"]);
    if !challenge.records_tackle_attempt {
        tags.push("pressure_recovery");
    }
    if challenge.context == RunnerDuelContext::Pass {
        tags.push("pass_release");
    }
    record_match_event(
        state,
        config,
        MatchEventInput {
            tick,
            half,
            possession_id: challenge.possession_id,
            event_type,
            team_home: challenge.challenger_team_home,
            player: challenger_identity,
            target_player: holder_identity,
            assist_player: serde_json::Value::Null,
            outcome: "won",
            xg: 0.0,
            origin: Some(challenge.origin),
            target: Some(state.ball.position),
            tags,
            score_before: None,
        },
    );
}

fn record_unprovenanced_opponent_recovery(
    state: &mut RunnerMatchState,
    config: &RunnerRuntimeConfig,
    tick: i32,
    half: i32,
    winner_idx: usize,
    winner_home: bool,
    winner_pos: (f64, f64),
    home: &[RunnerPlayer],
    away: &[RunnerPlayer],
    had_challenge: bool,
) {
    if had_challenge || !possession_team_changes(state.possession_team_home, winner_home) {
        return;
    }
    let winner = if winner_home {
        player_identity(home, winner_idx)
    } else {
        player_identity(away, winner_idx)
    };
    record_match_event(
        state,
        config,
        MatchEventInput {
            tick,
            half,
            possession_id: state.possession_id,
            event_type: "recovery",
            team_home: winner_home,
            player: winner,
            target_player: serde_json::Value::Null,
            assist_player: serde_json::Value::Null,
            outcome: "won",
            xg: 0.0,
            origin: Some(state.ball.position),
            target: Some(winner_pos),
            tags: EventTags::from_slice(&["possession_won", "second_ball"]),
            score_before: None,
        },
    );
}

fn restart_players(players: &[RunnerPlayer]) -> Vec<RestartPlayerInput> {
    players
        .iter()
        .enumerate()
        .map(|(idx, player)| RestartPlayerInput {
            index: idx,
            pos: player.pos,
            is_goalkeeper: player.position == "GK",
        })
        .collect()
}

fn restart_shape_players(
    players: &[RunnerPlayer],
    team_code: u8,
    team_is_restart: bool,
    team_attacking_right: bool,
    restart_attacking_right: bool,
) -> Vec<RestartShapePlayerInput<'_>> {
    players
        .iter()
        .enumerate()
        .map(|(idx, player)| RestartShapePlayerInput {
            index: idx,
            team_code,
            team_is_restart,
            team_attacking_right,
            restart_attacking_right,
            base_pos: player.base_pos,
            current_pos: player.pos,
            is_goalkeeper: player.position == "GK",
            is_attacker: is_attacker_position(player.position.as_str()),
            is_midfielder: is_midfielder_position(player.position.as_str()),
            is_defender: is_defender_position(player.position.as_str()),
            position: player.position.as_str(),
        })
        .collect()
}

fn carry_target(
    holder: &RunnerPlayer,
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
) -> (f64, f64) {
    let dir = if attacking_right { 1.0 } else { -1.0 };
    let center_pull = (config.pitch_width / 2.0 - holder.pos.1).clamp(-4.0, 4.0);
    (holder.pos.0 + dir * 12.0, holder.pos.1 + center_pull * 0.35)
}

fn clear_target(
    holder: &RunnerPlayer,
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
) -> (f64, f64) {
    let dir = if attacking_right { 1.0 } else { -1.0 };
    let center_y = config.pitch_width / 2.0;
    pitch_clamp(
        (
            holder.pos.0 + dir * 34.0,
            holder.pos.1 + (center_y - holder.pos.1) * 0.25,
        ),
        config.pitch_length,
        config.pitch_width,
    )
}

fn choose_pass_receiver(
    holder_idx: usize,
    holder: &RunnerPlayer,
    teammates: &[RunnerPlayer],
    attacking_right: bool,
) -> Option<usize> {
    let dir = if attacking_right { 1.0 } else { -1.0 };
    let mut best: Option<(usize, f64)> = None;
    for (idx, teammate) in teammates.iter().enumerate() {
        if idx == holder_idx || teammate.position == "GK" {
            continue;
        }
        let forward = (teammate.pos.0 - holder.pos.0) * dir;
        let dist = ((teammate.pos.0 - holder.pos.0).powi(2)
            + (teammate.pos.1 - holder.pos.1).powi(2))
        .sqrt();
        let forward_bonus = if forward > 1.0 { 14.0 } else { 0.0 };
        let score = dist - forward_bonus;
        if best
            .map(|(_, best_score)| score < best_score)
            .unwrap_or(true)
        {
            best = Some((idx, score));
        }
    }
    best.map(|(idx, _)| idx)
}

fn goalkeeper_attributes(
    goalkeeper: Option<&RunnerPlayer>,
    config: &RunnerRuntimeConfig,
) -> GkSaveAttributes {
    GkSaveAttributes {
        gk_saving: goalkeeper.map(|player| player.gk_saving).unwrap_or(50.0),
        gk_positioning: goalkeeper
            .map(|player| player.gk_positioning)
            .unwrap_or(50.0),
        gk_reaction: goalkeeper.map(|player| player.gk_reaction).unwrap_or(50.0),
        gk_position_error_factor: config.gk_position_error_factor,
        gk_reaction_delay_factor: config.gk_reaction_delay_factor,
        gk_save_base: config.gk_save_base,
    }
}

fn opposing_goalkeeper_context(
    opponents: &[RunnerPlayer],
    config: &RunnerRuntimeConfig,
) -> (GkSaveAttributes, Option<(f64, f64)>) {
    let goalkeeper = opponents.iter().find(|player| player.position == "GK");
    (
        goalkeeper_attributes(goalkeeper, config),
        goalkeeper.map(|player| player.pos),
    )
}

fn unknown_goalkeeper_attributes(config: &RunnerRuntimeConfig) -> GkSaveAttributes {
    goalkeeper_attributes(None, config)
}

struct RunnerShotExecutionEvaluation {
    outcome: crate::ShotOutput,
    gk_attributes: GkSaveAttributes,
}

fn evaluate_real_shot_execution(
    holder_idx: usize,
    holder: &RunnerPlayer,
    holder_home: bool,
    opponents: &[RunnerPlayer],
    contest_defenders: &[ShotContestDefender],
    control_state: PossessionControlState,
    attacking_right: bool,
    tick: i32,
    shot_quality_cache: &ShotQualityCache,
    config: &RunnerRuntimeConfig,
) -> RunnerShotExecutionEvaluation {
    let (gk_attributes, gk_pos) = opposing_goalkeeper_context(opponents, config);
    let outcome = evaluate_shot(&ShotInput {
        tick,
        shooter_index: holder_idx,
        shooter_team_home: holder_home,
        shooter_pos: holder.pos,
        finishing: holder.finishing / 100.0,
        long_shot: holder.long_shot / 100.0,
        possession_ticks: holder.possession_ticks,
        consecutive_carries: holder.consecutive_carries,
        last_receive_origin: holder.last_receive_origin,
        opponents: &[],
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
        attacking_right,
        shot_on_target_base: config.shot_on_target_base,
        gk_save_base: config.gk_save_base,
        gk_attributes: Some(gk_attributes),
        gk_pos,
        contest_defenders: Some(contest_defenders),
        shot_ideal_distance: config.shot_ideal_distance,
        shot_quality_cache: Some(shot_quality_cache),
        control_state: Some(control_state),
    });
    RunnerShotExecutionEvaluation {
        outcome,
        gk_attributes,
    }
}

fn runner_live_control_transition(
    previous: PossessionControlState,
    controller_idx: usize,
    controller_pos: (f64, f64),
    controlling_players: &[RunnerPlayer],
    defending_players: &[RunnerPlayer],
    attacking_right: bool,
    arrival_heading: f64,
    ownership_continuity: f64,
    contact_load: f64,
    settling_ticks: i32,
    movement_distance: f64,
    turn_target: Option<f64>,
    pitch_length: f64,
    pitch_width: f64,
) -> PossessionControlState {
    assert!(
        controlling_players.len() <= RUNNER_TEAM_SIZE
            && defending_players.len() <= RUNNER_TEAM_SIZE,
        "live control transition expects eleven-player teams"
    );
    let mut controlling_positions = [(0, 0.0, 0.0); RUNNER_TEAM_SIZE];
    let mut teammate_goalkeeper_indices = [0; RUNNER_TEAM_SIZE];
    let mut teammate_goalkeeper_count = 0;
    for (index, player) in controlling_players.iter().enumerate() {
        controlling_positions[index] = (index, player.pos.0, player.pos.1);
        if player.position == "GK" {
            teammate_goalkeeper_indices[teammate_goalkeeper_count] = index;
            teammate_goalkeeper_count += 1;
        }
    }
    let mut opponent_positions = [(0.0, 0.0); RUNNER_TEAM_SIZE];
    let mut opponent_count = 0;
    for player in defending_players {
        if player.position != "GK" {
            opponent_positions[opponent_count] = player.pos;
            opponent_count += 1;
        }
    }
    crate::transition_possession_control(&PossessionControlTransitionInput {
        previous,
        observation: PossessionControlObservation {
            controller_index: controller_idx,
            controller_pos,
            teammate_positions: &controlling_positions[..controlling_players.len()],
            teammate_goalkeeper_indices: &teammate_goalkeeper_indices[..teammate_goalkeeper_count],
            opponent_positions: &opponent_positions[..opponent_count],
            pitch_length,
            pitch_width,
            attacking_right,
        },
        arrival_heading,
        ownership_continuity,
        contact_load,
        settling_ticks,
        movement_distance,
        turn_target,
    })
}

const RUNNER_TEAM_SIZE: usize = 11;
type RunnerPassNetwork = [[[i32; RUNNER_TEAM_SIZE]; RUNNER_TEAM_SIZE]; 2];
const RUNNER_DEFENSE_RANDOM_SAMPLE_COUNT: usize = 3;
const RUNNER_MAX_CARRY_CANDIDATES: usize = MAX_CARRY_TARGET_OFFSETS;
const RUNNER_MAX_PASS_CANDIDATES: usize = (RUNNER_TEAM_SIZE - 1) * MAX_PASS_CANDIDATES_PER_RECEIVER;
const RUNNER_MAX_HELD_ACTIONS: usize = RUNNER_MAX_CARRY_CANDIDATES + RUNNER_MAX_PASS_CANDIDATES + 4;
const RUNNER_MAX_CARRY_RESPONSE_SEGMENTS: usize = 4;
const RUNNER_MAX_SPECIALIZED_GOALS: usize = 9;
