fn runner_action_code(action: RunnerHeldAction) -> u8 {
    match action {
        RunnerHeldAction::Carry { .. } => 0,
        RunnerHeldAction::Pass { .. } => 1,
        RunnerHeldAction::Shoot { .. } => 2,
        RunnerHeldAction::Hold { .. } | RunnerHeldAction::Reorient { .. } => 3,
        RunnerHeldAction::Clear { .. } => 4,
    }
}

fn runner_action_target(action: RunnerHeldAction, holder_pos: (f64, f64)) -> Option<(f64, f64)> {
    match action {
        RunnerHeldAction::Carry { target } => Some(target),
        RunnerHeldAction::Pass { target, .. } => Some(target),
        RunnerHeldAction::Clear { target } => Some(target),
        RunnerHeldAction::Shoot { target, .. } => Some(target),
        RunnerHeldAction::Reorient { target } => Some(target),
        RunnerHeldAction::Hold { .. } => Some(holder_pos),
    }
}

fn runner_action_name(action: RunnerHeldAction) -> &'static str {
    match action {
        RunnerHeldAction::Carry { .. } => "carry",
        RunnerHeldAction::Pass { .. } => "pass",
        RunnerHeldAction::Shoot { .. } => "shoot",
        RunnerHeldAction::Reorient { .. } => "reorient",
        RunnerHeldAction::Hold { .. } => "hold",
        RunnerHeldAction::Clear { .. } => "clear",
    }
}

fn sync_holder_tactical_task_from_action(
    holder: &mut RunnerPlayer,
    action: RunnerHeldAction,
    tick: i32,
    plan_signals: TeamPlanSignals,
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
) -> Option<crate::TaskAcceptance> {
    let (intent_type, phase, target, value) = match action {
        RunnerHeldAction::Carry { target } => ("carry", "drive", target, holder.goal_value),
        RunnerHeldAction::Hold { opportunity_target } => (
            "hold_for_opportunity",
            "scan",
            opportunity_target.unwrap_or(holder.pos),
            holder.goal_value,
        ),
        RunnerHeldAction::Reorient { target } => ("recycle", "scan", target, holder.goal_value),
        RunnerHeldAction::Pass { .. }
        | RunnerHeldAction::Clear { .. }
        | RunnerHeldAction::Shoot { .. } => return None,
    };
    Some(accept_player_tactical_task(
        holder,
        intent_type,
        phase,
        target,
        value.max(0.12),
        tick,
        plan_signals,
        attacking_right,
        config,
    ))
}

fn runner_action_timing(
    action: RunnerHeldAction,
    origin: (f64, f64),
    plan_signals: TeamPlanSignals,
    pressure: f64,
    opportunity: f64,
    config: &RunnerRuntimeConfig,
) -> Option<ActionTimingPlan> {
    let (kind, target) = match action {
        RunnerHeldAction::Carry { target } => (TemporalActionKind::Carry, target),
        RunnerHeldAction::Reorient { .. } | RunnerHeldAction::Hold { .. } => {
            (TemporalActionKind::Hold, origin)
        }
        RunnerHeldAction::Pass { .. }
        | RunnerHeldAction::Clear { .. }
        | RunnerHeldAction::Shoot { .. } => return None,
    };
    Some(action_timing_plan(&ActionTimingInput {
        kind,
        target_distance: distance(origin, target),
        nominal_step_distance: config.carrier_speed.max(0.1),
        pressure,
        tempo: plan_signals.tempo,
        risk_budget: plan_signals.risk_budget,
        opportunity,
    }))
}

fn start_action_commitment(
    state: &mut RunnerMatchState,
    action: RunnerHeldAction,
    candidate: Option<RunnerEvaluatedAction>,
    origin: (f64, f64),
    plan_signals: TeamPlanSignals,
    pressure: f64,
    opportunity: f64,
    config: &RunnerRuntimeConfig,
) {
    let Some(candidate) = candidate else {
        state.action_commitment = None;
        return;
    };
    state.action_commitment =
        runner_action_timing(action, origin, plan_signals, pressure, opportunity, config).map(
            |timing| RunnerActionCommitment {
                action,
                continuation_value: candidate.decision_value(),
                candidate,
                remaining_ticks: timing.initial_ticks,
                initial_ticks: timing.initial_ticks,
                completion_distance: timing.completion_distance,
                requires_target_completion: timing.requires_target_completion,
            },
        );
}

fn continuing_held_action(
    state: &mut RunnerMatchState,
    holder_pos: (f64, f64),
) -> Option<RunnerHeldAction> {
    if let Some(commitment) = state.action_commitment.as_ref() {
        let target = runner_action_target(commitment.action, holder_pos).unwrap_or(holder_pos);
        if should_continue_action(
            ActionTimingPlan {
                initial_ticks: commitment.initial_ticks,
                completion_distance: commitment.completion_distance,
                requires_target_completion: commitment.requires_target_completion,
            },
            commitment.remaining_ticks,
            distance(holder_pos, target),
        ) {
            return Some(commitment.action);
        }
        state.action_commitment = None;
    }
    None
}

fn advance_action_commitment(state: &mut RunnerMatchState, holder_pos: (f64, f64)) {
    let Some(mut commitment) = state.action_commitment.clone() else {
        return;
    };
    commitment.remaining_ticks -= 1;
    let target = runner_action_target(commitment.action, holder_pos).unwrap_or(holder_pos);
    if should_continue_action(
        ActionTimingPlan {
            initial_ticks: commitment.initial_ticks,
            completion_distance: commitment.completion_distance,
            requires_target_completion: commitment.requires_target_completion,
        },
        commitment.remaining_ticks,
        distance(holder_pos, target),
    ) {
        state.action_commitment = Some(commitment);
    } else {
        state.action_commitment = None;
    }
}

fn runner_action_source(action: RunnerHeldAction) -> &'static str {
    match action {
        RunnerHeldAction::Carry { .. } => "carry",
        RunnerHeldAction::Pass { is_long, .. } => {
            if is_long {
                "long_pass"
            } else {
                "pass"
            }
        }
        RunnerHeldAction::Shoot { .. } => "shot",
        RunnerHeldAction::Reorient { .. } => "reorient",
        RunnerHeldAction::Hold { .. } => "hold",
        RunnerHeldAction::Clear { .. } => "clear",
    }
}

fn runner_action_transition_components(action: &RunnerEvaluatedAction) -> serde_json::Value {
    match action.action {
        RunnerHeldAction::Shoot {
            xg,
            on_target_prob,
            body_release_probability,
            release_probability,
            block_probability,
            ..
        } => {
            let transition = crate::execution_transition::ShotExecutionTransition::new(
                body_release_probability,
                release_probability,
                block_probability,
            )
            .mass();
            json!({
                "mishit_probability": transition.mishit,
                "blocked_probability": transition.blocked,
                "released_probability": transition.released,
                "on_target_probability": transition.released * on_target_prob,
                "goal_probability": (body_release_probability * xg)
                    .min(transition.released * on_target_prob),
            })
        }
        RunnerHeldAction::Pass {
            retention_probability,
            technical_probability,
            ..
        } => {
            let transition = crate::execution_transition::PassExecutionTransition::new(
                technical_probability,
                0.0,
            );
            json!({
                "candidate_retention_probability": retention_probability,
                "technical_delivery_probability": transition.delivery.success_probability,
                "technical_delivery_failure_probability": transition.delivery.failure_probability,
            })
        }
        _ => serde_json::Value::Null,
    }
}

