fn is_defender_position(position: &str) -> bool {
    matches!(position, "CB" | "LCB" | "RCB" | "LB" | "RB" | "LWB" | "RWB")
}

fn is_midfielder_position(position: &str) -> bool {
    matches!(
        position,
        "CM" | "LCM" | "RCM" | "CDM" | "LDM" | "RDM" | "CAM" | "RAM" | "LAM" | "LM" | "RM" | "AM"
    )
}

fn is_attacker_position(position: &str) -> bool {
    matches!(
        position,
        "ST" | "CF" | "LW" | "RW" | "LF" | "RF" | "LS" | "RS"
    )
}

fn update_runner_movement_target(
    player: &mut RunnerPlayer,
    requested_target: (f64, f64),
    requested_intent: Option<&str>,
) {
    let movement_target = player_set_movement_target_ref(&PlayerSetMovementTargetInput {
        current_target: player.target_pos,
        requested_target,
        current_intent: player.movement_intent.as_str(),
        requested_intent,
    });
    player.target_pos = movement_target.target_pos;
    if let Some(requested_intent) = requested_intent {
        update_runner_text(&mut player.movement_intent, requested_intent);
    }
}

fn update_runner_text(text: &mut String, requested_value: &str) {
    if text != requested_value {
        text.clear();
        text.push_str(requested_value);
    }
}

fn update_runner_optional_text(text: &mut Option<String>, requested_value: Option<&str>) {
    match (text.as_mut(), requested_value) {
        (Some(text), Some(requested_value)) => update_runner_text(text, requested_value),
        (None, Some(requested_value)) => *text = Some(requested_value.to_string()),
        (Some(_), None) => *text = None,
        (None, None) => {}
    }
}

fn is_wide_position(position: &str) -> bool {
    matches!(
        position,
        "LW" | "RW" | "LM" | "RM" | "LB" | "RB" | "LWB" | "RWB"
    )
}

fn refresh_player_tactical_belief_from_team_parts(
    player: &mut RunnerPlayer,
    self_index: usize,
    teammates_before: &[RunnerPlayer],
    teammates_after: &[RunnerPlayer],
    opponents: &[RunnerPlayer],
    ball_pos: (f64, f64),
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
) {
    let vision = build_vision_context(&VisionContextInput {
        iq: player.iq,
        facing_direction: player.facing_direction,
        attacking_right,
        vision_base_fov: config.vision_base_fov,
        vision_iq_bonus_factor: config.vision_iq_bonus_factor,
        vision_base_distance: config.vision_base_distance,
        vision_iq_distance_bonus_factor: config.vision_iq_distance_bonus_factor,
        vision_max_distance: config.vision_max_distance,
    });
    let mut visible = [VisibleEntity {
        index: 0,
        pos: (0.0, 0.0),
        velocity: (0.0, 0.0),
        confidence: 0.0,
        is_teammate: false,
        is_goalkeeper: false,
    }; MAX_PLAYER_OBSERVED_ENTITIES];
    let mut count = 0;
    let mut observe = |index, candidate: &RunnerPlayer, is_teammate| {
        if count == visible.len() {
            return;
        }
        let confidence = vision.confidence(player.pos, candidate.pos);
        if confidence <= 0.0 {
            return;
        }
        visible[count] = VisibleEntity {
            index,
            pos: candidate.pos,
            velocity: candidate.velocity,
            confidence,
            is_teammate,
            is_goalkeeper: candidate.position == "GK",
        };
        count += 1;
    };
    for (index, teammate) in teammates_before.iter().enumerate() {
        observe(index, teammate, true);
    }
    for (offset, teammate) in teammates_after.iter().enumerate() {
        observe(self_index + offset + 1, teammate, true);
    }
    for (index, opponent) in opponents.iter().enumerate() {
        observe(RUNNER_TEAM_SIZE + index, opponent, false);
    }
    let observation = PlayerObservation {
        self_index,
        self_pos: player.pos,
        facing_direction: player.facing_direction,
        ball_pos,
        ball_confidence: vision.confidence(player.pos, ball_pos),
        visible_entities: &visible[..count],
    };
    update_player_belief(&mut player.tactical_belief, &observation, player.iq);
}

fn refresh_team_tactical_beliefs(
    players: &mut [RunnerPlayer],
    opponents: &[RunnerPlayer],
    ball_pos: (f64, f64),
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
) {
    for index in 0..players.len() {
        let (before, rest) = players.split_at_mut(index);
        let (player, after) = rest
            .split_first_mut()
            .expect("team belief refresh index must be in bounds");
        refresh_player_tactical_belief_from_team_parts(
            player,
            index,
            before,
            after,
            opponents,
            ball_pos,
            attacking_right,
            config,
        );
    }
}

fn publish_team_communication(
    state: &mut RunnerMatchState,
    players: &[RunnerPlayer],
    team_home: bool,
    tick: i32,
    config: &RunnerRuntimeConfig,
) {
    if !config.team_communication_enabled {
        return;
    }
    for (index, player) in players.iter().enumerate() {
        state.team_communication.publish(
            team_home,
            TeamCommunicationPublishInput {
                sender_index: index,
                task: player
                    .tactical_task
                    .active(tick)
                    .then_some(player.tactical_task),
                observed_tick: tick,
            },
        );
    }
}

fn initialize_team_communication(
    state: &mut RunnerMatchState,
    delivery_tick: i32,
    config: &RunnerRuntimeConfig,
) {
    if !config.team_communication_enabled {
        return;
    }
    state.team_communication.reset();
    state.team_communication.deliver(delivery_tick);
}

fn accept_player_tactical_task(
    player: &mut RunnerPlayer,
    candidate_type: &str,
    candidate_phase: &str,
    candidate_target: (f64, f64),
    candidate_value: f64,
    tick: i32,
    plan_signals: TeamPlanSignals,
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
) -> crate::TaskAcceptance {
    accept_player_tactical_task_with_coordination(
        player,
        candidate_type,
        candidate_phase,
        candidate_target,
        candidate_value,
        tick,
        plan_signals,
        attacking_right,
        config,
        TacticalTaskCoordination::default(),
    )
}

fn accept_player_tactical_task_with_coordination(
    player: &mut RunnerPlayer,
    candidate_type: &str,
    candidate_phase: &str,
    candidate_target: (f64, f64),
    candidate_value: f64,
    tick: i32,
    plan_signals: TeamPlanSignals,
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
    coordination: TacticalTaskCoordination,
) -> crate::TaskAcceptance {
    let observation = PlayerObservation {
        self_index: 0,
        self_pos: player.pos,
        facing_direction: player.facing_direction,
        ball_pos: player.tactical_belief.ball_pos,
        ball_confidence: player.tactical_belief.ball_confidence,
        visible_entities: &[],
    };
    let expected_duration_ticks = match candidate_phase {
        "defend" => 4,
        "support" => 6,
        "execute" | "drive" | "release" | "finish" | "scan" => 3,
        _ => 4,
    };
    let acceptance = accept_task(&TaskAcceptanceInput {
        current: player.tactical_task,
        proposal: GoalProposal {
            goal_type: candidate_type,
            phase: candidate_phase,
            raw_target: candidate_target,
            local_value: candidate_value,
            accepted_tick: tick,
            expected_duration_ticks,
            pressure_interrupt: if candidate_phase == "defend" {
                0.0
            } else {
                (1.0 - player.tactical_belief.ball_confidence) * 0.35
            },
            coordination,
        },
        tactical_anchor: player.tactical_anchor,
        observation: &observation,
        belief: &player.tactical_belief,
        plan_signals,
        attacking_right,
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
    });
    player.tactical_task = acceptance.task;
    player.tactical_task_tick = tick;
    acceptance
}

fn player_effective_movement_target(
    player: &RunnerPlayer,
    tick: i32,
    plan_signals: TeamPlanSignals,
) -> (f64, f64) {
    player_effective_movement_target_with_anchor(player, tick, plan_signals, player.tactical_anchor)
}

fn player_effective_movement_target_with_anchor(
    player: &RunnerPlayer,
    tick: i32,
    plan_signals: TeamPlanSignals,
    tactical_anchor: (f64, f64),
) -> (f64, f64) {
    if player.tactical_task.active(tick) {
        task_motion_target(&TaskMotionInput {
            task: player.tactical_task,
            player_pos: player.pos,
            tactical_anchor,
            tick,
            plan_signals,
        })
    } else {
        crate::team_plan::team_plan_movement_target(
            player.target_pos,
            tactical_anchor,
            plan_signals,
        )
    }
}

fn runner_tactical_task_intent_name(intent: crate::TacticalTaskIntent) -> &'static str {
    match intent {
        crate::TacticalTaskIntent::Receive => "receive",
        crate::TacticalTaskIntent::Support => "support",
        crate::TacticalTaskIntent::Carry => "carry",
        crate::TacticalTaskIntent::Control => "control",
        crate::TacticalTaskIntent::CloseDown => "close_down",
        crate::TacticalTaskIntent::Press => "press",
        crate::TacticalTaskIntent::Pursuit => "pursuit",
        crate::TacticalTaskIntent::Cover => "cover",
        crate::TacticalTaskIntent::Screen => "screen",
        crate::TacticalTaskIntent::Recover => "recover",
    }
}

fn runner_tactical_task_phase_name(phase: crate::TacticalTaskPhase) -> &'static str {
    match phase {
        crate::TacticalTaskPhase::Proposed => "proposed",
        crate::TacticalTaskPhase::Active => "active",
        crate::TacticalTaskPhase::Recovering => "recovering",
        crate::TacticalTaskPhase::Cancelled => "cancelled",
    }
}

fn runner_tactical_task_payload(task: TacticalTask) -> serde_json::Value {
    json!({
        "intent": runner_tactical_task_intent_name(task.intent),
        "phase": runner_tactical_task_phase_name(task.phase),
        "raw_target": [task.raw_target.0, task.raw_target.1],
        "accepted_tick": task.accepted_tick,
        "expires_tick": task.expires_tick,
        "commitment": task.commitment,
        "local_value": task.local_value,
        "policy_utility": task.policy_utility,
        "formation_debt": task.formation_debt,
        "interruption": task.interruption,
        "spatial_claim": {
            "active": task.spatial_claim.active,
            "origin": [task.spatial_claim.origin.0, task.spatial_claim.origin.1],
            "target": [task.spatial_claim.target.0, task.spatial_claim.target.1],
            "occupancy_radius": task.spatial_claim.occupancy_radius,
            "corridor_half_width": task.spatial_claim.corridor_half_width,
            "depth_band": task.spatial_claim.depth_band,
            "width_band": task.spatial_claim.width_band,
        },
        "coordination": {
            "commitment": task.coordination.commitment,
            "carrier_closure": task.coordination.carrier_closure,
            "carrier_engagement": task.coordination.carrier_engagement,
            "cover": task.coordination.cover,
            "lane_screen": task.coordination.lane_screen,
            "wide_balance": task.coordination.wide_balance,
            "outlet_coverage": task.coordination.outlet_coverage,
        },
    })
}

fn record_tactical_task_resolution(
    trace_decisions: &mut Vec<serde_json::Value>,
    config: &RunnerRuntimeConfig,
    tick: i32,
    team_home: bool,
    player_idx: usize,
    player: &RunnerPlayer,
    plan_signals: TeamPlanSignals,
    source: &str,
    source_type: Option<&str>,
    source_phase: Option<&str>,
    previous: TacticalTask,
    acceptance: Option<crate::TaskAcceptance>,
) {
    if config.trace_detail != "full" {
        return;
    }
    let (outcome, candidate_value, retained_value) = match acceptance {
        Some(acceptance) if acceptance.accepted && !previous.active(tick) => (
            "accepted",
            Some(acceptance.candidate_value),
            Some(acceptance.retained_value),
        ),
        Some(acceptance) if acceptance.accepted && previous.intent == acceptance.task.intent => (
            "refreshed",
            Some(acceptance.candidate_value),
            Some(acceptance.retained_value),
        ),
        Some(acceptance) if acceptance.accepted => (
            "replaced",
            Some(acceptance.candidate_value),
            Some(acceptance.retained_value),
        ),
        Some(acceptance) => (
            "retained",
            Some(acceptance.candidate_value),
            Some(acceptance.retained_value),
        ),
        None => ("cancelled", None, None),
    };
    let effective_target = player_effective_movement_target(player, tick, plan_signals);
    trace_decisions.push(json!({
        "tick": tick,
        "team": if team_home { "home" } else { "away" },
        "player_idx": player_idx,
        "player": player.name,
        "phase": "tactical_task",
        "source": {
            "kind": source,
            "type": source_type,
            "phase": source_phase,
        },
        "previous_task": runner_tactical_task_payload(previous),
        "resolution": {
            "outcome": outcome,
            "candidate_value": candidate_value,
            "retained_value": retained_value,
        },
        "task": runner_tactical_task_payload(player.tactical_task),
        "movement": {
            "tactical_anchor": [player.tactical_anchor.0, player.tactical_anchor.1],
            "raw_target": [player.tactical_task.raw_target.0, player.tactical_task.raw_target.1],
            "effective_target": [effective_target.0, effective_target.1],
        },
        "belief": {
            "ball_pos": [player.tactical_belief.ball_pos.0, player.tactical_belief.ball_pos.1],
            "ball_confidence": player.tactical_belief.ball_confidence,
        },
    }));
}

fn sync_player_tactical_task_from_goal(
    player: &mut RunnerPlayer,
    tick: i32,
    plan_signals: TeamPlanSignals,
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
) -> Option<crate::TaskAcceptance> {
    let Some(goal_type) = player.goal_type.clone() else {
        player.tactical_task = TacticalTask::inactive(player.tactical_anchor);
        player.tactical_task_tick = tick;
        return None;
    };
    let phase = player.goal_phase.clone().unwrap_or_else(|| {
        if goal_type.starts_with("defend_") {
            "defend".to_string()
        } else {
            "support".to_string()
        }
    });
    Some(accept_player_tactical_task(
        player,
        goal_type.as_str(),
        phase.as_str(),
        player.goal_target,
        player.goal_value,
        tick,
        plan_signals,
        attacking_right,
        config,
    ))
}

fn sync_team_tactical_tasks_from_goals(
    players: &mut [RunnerPlayer],
    tick: i32,
    plan_signals: TeamPlanSignals,
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
    trace_decisions: &mut Vec<serde_json::Value>,
    team_home: bool,
) {
    for (player_idx, player) in players.iter_mut().enumerate() {
        let previous = player.tactical_task;
        let source_goal_type = player.goal_type.clone();
        let source_goal_phase = player.goal_phase.clone();
        let should_trace =
            source_goal_type.is_some() || previous.phase == crate::TacticalTaskPhase::Active;
        let acceptance = sync_player_tactical_task_from_goal(
            player,
            tick,
            plan_signals,
            attacking_right,
            config,
        );
        if should_trace {
            record_tactical_task_resolution(
                trace_decisions,
                config,
                tick,
                team_home,
                player_idx,
                player,
                plan_signals,
                "goal",
                source_goal_type.as_deref(),
                source_goal_phase.as_deref(),
                previous,
                acceptance,
            );
        }
    }
}

fn apply_player_goal_switch_with_details(
    player: &mut RunnerPlayer,
    candidate_type: &str,
    candidate_phase: &'static str,
    candidate_target: (f64, f64),
    candidate_value: f64,
    iq: f64,
    base: f64,
    pressure_interrupt: f64,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
) -> RunnerGoalSwitchResult {
    let current_storage = player.goal_type.as_deref().map(|goal_type| GoalInput {
        goal_type,
        value: player.goal_value,
        phase: player.goal_phase.as_deref().or_else(|| {
            if goal_type.starts_with("defend_") {
                Some("defend")
            } else {
                None
            }
        }),
    });
    let candidate = GoalInput {
        goal_type: candidate_type,
        value: candidate_value,
        phase: Some(candidate_phase),
    };
    let context = GoalSwitchCostInput {
        base,
        context_stability: 1.0,
        role_discipline: 1.0,
        pressure_interrupt,
        iq,
    };
    let selection = select_runner_goal_with_noise(
        current_storage.as_ref(),
        &candidate,
        &context,
        config.goal_noise_scale,
        rng,
    );
    if selection.selected == "candidate" {
        update_runner_optional_text(&mut player.goal_type, Some(candidate_type));
        update_runner_optional_text(&mut player.goal_phase, Some(candidate_phase));
        player.goal_target = candidate_target;
        player.goal_value = candidate_value.max(0.0);
        player.goal_action_code = 3;
    }
    RunnerGoalSwitchResult {
        switched: selection.switched,
        switch_cost: selection.switch_cost,
        value_advantage: selection.value_advantage,
        reason: selection.reason,
    }
}

fn apply_arrival_goal_switch_with_details(
    player: &mut RunnerPlayer,
    candidate_type: &'static str,
    candidate_target: (f64, f64),
    candidate_value: f64,
    iq: f64,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
) -> RunnerGoalSwitchResult {
    let current_storage = player.goal_type.as_deref().map(|goal_type| GoalInput {
        goal_type,
        value: player.goal_value,
        phase: player.goal_phase.as_deref().or_else(|| {
            if goal_type.starts_with("defend_") {
                Some("defend")
            } else {
                None
            }
        }),
    });
    let candidate = GoalInput {
        goal_type: candidate_type,
        value: candidate_value,
        phase: None,
    };
    let context = GoalSwitchCostInput {
        base: 0.035,
        context_stability: 1.0,
        role_discipline: 1.0,
        pressure_interrupt: 0.0,
        iq,
    };
    let selection = select_runner_goal_with_noise(
        current_storage.as_ref(),
        &candidate,
        &context,
        config.goal_noise_scale,
        rng,
    );
    if selection.selected == "candidate" {
        update_runner_optional_text(&mut player.goal_type, Some(candidate_type));
        update_runner_optional_text(&mut player.goal_phase, None);
        player.goal_target = candidate_target;
        player.goal_value = candidate_value.max(0.0);
        player.goal_action_code = 3;
    }
    RunnerGoalSwitchResult {
        switched: selection.switched,
        switch_cost: selection.switch_cost,
        value_advantage: selection.value_advantage,
        reason: selection.reason,
    }
}

fn off_ball_attack_movement_intent(
    player_pos: (f64, f64),
    anchor: (f64, f64),
    chosen_pos: (f64, f64),
    components: &crate::OffBallAttackChoiceComponents,
    current_goal: Option<crate::OffBallAttackGoalInput<'_>>,
    attacking_right: bool,
) -> &'static str {
    let forward_dir = if attacking_right { 1.0 } else { -1.0 };
    let move_progress = (chosen_pos.0 - player_pos.0) * forward_dir;
    let anchor_run = (anchor.0 - player_pos.0) * forward_dir;
    let support_urgency = components
        .second_line_support
        .max(components.inside_support * 0.72);
    let goal_arrival_urgency = current_goal
        .filter(|goal| {
            matches!(
                goal.goal_type,
                "arc_arrival_for_cutback" | "attack_far_post"
            )
        })
        .map(|goal| {
            let radius = if goal.goal_type == "arc_arrival_for_cutback" {
                14.0
            } else {
                18.0
            };
            (1.0 - distance(chosen_pos, goal.target_pos) / radius).max(0.0)
                * (goal.value * 4.0).clamp(0.0, 1.0)
        })
        .unwrap_or(0.0);
    if support_urgency > 0.10 || goal_arrival_urgency > 0.18 {
        "attack_run"
    } else if move_progress > 4.0 || anchor_run > 6.0 {
        "attack_run"
    } else if distance(chosen_pos, anchor) > 10.0 {
        "support"
    } else {
        "recover_shape"
    }
}

fn off_ball_attack_goal_type(goal_type: &str) -> Option<&'static str> {
    match goal_type {
        "arc_arrival_for_cutback" => Some("arc_arrival_for_cutback"),
        "attack_far_post" => Some("attack_far_post"),
        "support_second_line" => Some("support_second_line"),
        "drop_between_lines" => Some("drop_between_lines"),
        "support_carrier" => Some("support_carrier"),
        "hold_width" => Some("hold_width"),
        "run_behind" => Some("run_behind"),
        "attack_box" => Some("attack_box"),
        "recycle_support" => Some("recycle_support"),
        _ => None,
    }
}

fn is_off_ball_attack_goal_type(goal_type: &str) -> bool {
    off_ball_attack_goal_type(goal_type).is_some()
}

fn attenuate_arrival_goal_for_teammate_occupancy(
    player: &RunnerPlayer,
    goal_type: &'static str,
    target_pos: (f64, f64),
    value: f64,
) -> Option<f64> {
    if !matches!(goal_type, "arc_arrival_for_cutback" | "attack_far_post") {
        return Some(value);
    }
    let radius = if goal_type == "arc_arrival_for_cutback" {
        10.0
    } else {
        12.0
    };
    let mut redundancy = 0.0;
    for teammate in player.tactical_belief.entities() {
        if !teammate.is_teammate || teammate.is_goalkeeper || teammate.confidence < 0.08 {
            continue;
        }
        let dist = distance(teammate.pos, target_pos);
        if dist < radius {
            let occupancy = teammate.confidence.clamp(0.10, 1.0);
            redundancy += (1.0 - dist / radius) * occupancy;
        }
    }
    if redundancy <= 0.0 {
        return Some(value);
    }
    let pressure = if goal_type == "arc_arrival_for_cutback" {
        2.4
    } else {
        3.0
    };
    let adjusted_value = value / (1.0 + redundancy * pressure);
    let floor = if goal_type == "arc_arrival_for_cutback" {
        0.18
    } else {
        0.10
    };
    if adjusted_value < floor {
        None
    } else {
        Some(adjusted_value)
    }
}

fn communication_task_claims_into(
    shared: TeamSharedBelief,
    tick: i32,
    claims: &mut [crate::SpatialClaim; RUNNER_TEAM_SIZE],
    owners: &mut [usize; RUNNER_TEAM_SIZE],
    strengths: &mut [f64; RUNNER_TEAM_SIZE],
) -> usize {
    let mut count = 0;
    for teammate_index in 0..RUNNER_TEAM_SIZE {
        let Some(task) = shared.task(teammate_index, tick) else {
            continue;
        };
        if !matches!(
            task.intent,
            crate::TacticalTaskIntent::Receive | crate::TacticalTaskIntent::Support
        ) || !task.spatial_claim.active
            || count == claims.len()
        {
            continue;
        }
        claims[count] = task.spatial_claim;
        owners[count] = teammate_index;
        strengths[count] = (task.commitment
            * (0.45 + 0.55 * task.coordination.commitment.max(0.35)))
        .clamp(0.0, 1.0);
        count += 1;
    }
    count
}

fn communication_claim_cost(
    candidate: TeamSpatialCandidate,
    player_index: usize,
    claims: &[crate::SpatialClaim],
    owners: &[usize],
    strengths: &[f64],
) -> f64 {
    claims
        .iter()
        .zip(owners.iter())
        .zip(strengths.iter())
        .filter(|((_, owner), strength)| **owner != player_index && **strength > 1e-6)
        .map(|((claim, _), strength)| {
            let occupied_radius = (claim.occupancy_radius * 0.65).max(1.2);
            let target_distance = distance(candidate.target, claim.target);
            let overlap = 1.0
                - crate::physics::smoothstep(
                    occupied_radius * 0.25,
                    occupied_radius,
                    target_distance,
                );
            candidate.local_value.max(0.0) * 0.08 * *strength * overlap.max(0.0)
        })
        .sum()
}

fn apply_communication_claim_costs(
    candidates: &mut [TeamSpatialCandidate],
    player_index: usize,
    claims: &[crate::SpatialClaim],
    owners: &[usize],
    strengths: &[f64],
) {
    for candidate in candidates {
        candidate.local_value = (candidate.local_value
            - communication_claim_cost(*candidate, player_index, claims, owners, strengths))
        .max(0.0);
    }
}

fn apply_off_ball_attack_choices(
    players: &mut [RunnerPlayer],
    state: &mut RunnerMatchState,
    tick: i32,
    team_home: bool,
    attacking_right: bool,
    holder_idx: Option<usize>,
    active_indices: Option<&[bool]>,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
) -> (i32, Option<RunnerGoalSummary>) {
    let mut selected_count = 0;
    let mut best_goal: Option<RunnerGoalSummary> = None;
    let plan_signals = if team_home {
        state.home_plan_signals
    } else {
        state.away_plan_signals
    };
    let team_structure_weight =
        (0.20 + 0.60 * plan_signals.recycle_bias + 0.20 * (1.0 - plan_signals.risk_budget))
            .clamp(0.0, 1.0);
    let shared_tasks = config
        .team_communication_enabled
        .then(|| state.team_communication.snapshot(team_home));
    assert!(
        players.len() <= RUNNER_TEAM_SIZE,
        "off-ball attack expects eleven-player teams"
    );
    let use_fixed_buffers = config.trace_detail == "off";
    let RunnerOffBallAttackArena {
        believed_teammate_positions,
        believed_teammates,
        communication_claims,
        communication_claim_owners,
        communication_claim_strengths,
        communication_claim_count,
        candidates: fixed_candidates,
        noises: fixed_noises,
        scored: fixed_scored,
        selection_scores: fixed_selection_scores,
        anchor_samples,
        support_samples,
        arrival_goals: fixed_arrival_goals,
        arrival_values: fixed_arrival_values,
        arrival_gaussians: fixed_arrival_gaussians,
        spatial_candidates,
        spatial_candidate_counts,
        spatial_preferred_indices,
        spatial_player_indices,
        spatial_player_count,
        spatial_components,
        spatial_goal_types,
        spatial_assignments,
    } = &mut state.off_ball_attack_arena;
    *communication_claim_count = shared_tasks
        .map(|shared| {
            communication_task_claims_into(
                shared,
                tick,
                communication_claims,
                communication_claim_owners,
                communication_claim_strengths,
            )
        })
        .unwrap_or(0);
    let shared_claim_count = *communication_claim_count;
    *spatial_player_count = 0;
    for idx in 0..players.len() {
        if holder_idx == Some(idx) {
            continue;
        }
        if active_indices
            .and_then(|indices| indices.get(idx))
            .map(|active| !*active)
            .unwrap_or(false)
        {
            continue;
        }
        if players[idx].position == "GK" {
            if let Some(player) = players.get_mut(idx) {
                apply_goalkeeper_coverage_target(player, attacking_right, config);
            }
            continue;
        }
        let stale_goal = players[idx]
            .goal_type
            .as_deref()
            .map(|goal_type| !is_off_ball_attack_goal_type(goal_type))
            .unwrap_or(false);
        if stale_goal {
            players[idx].goal_type = None;
            players[idx].goal_phase = None;
            players[idx].goal_value = 0.0;
            players[idx].goal_action_code = 0;
        }
        let player_pos = players[idx].pos;
        let player_anchor = players[idx].tactical_anchor;
        let player_base_pos = players[idx].base_pos;
        let player_speed_ability = players[idx].speed.round() as i32;
        let player_iq = players[idx].iq;
        let player_is_defender = is_defender_position(players[idx].position.as_str());
        let perceived_ball_pos = players[idx].tactical_belief.ball_pos;
        let perceived_has_ball_carrier =
            players[idx]
                .tactical_belief
                .entities()
                .iter()
                .any(|entity| {
                    entity.is_teammate
                        && !entity.is_goalkeeper
                        && entity.confidence >= 0.18
                        && distance(entity.pos, perceived_ball_pos)
                            <= 2.0 + 3.0 * players[idx].tactical_belief.ball_confidence
                });
        let opponent_context =
            belief_off_ball_attack_opponent_context(&players[idx], attacking_right, config);
        let opponent_xy = &opponent_context.positions[..opponent_context.count];
        let opponent_speeds = &opponent_context.speeds[..opponent_context.count];
        let offside = opponent_context.offside_line;
        let teammate_count = belief_off_ball_attack_teammates_into(
            &players[idx],
            believed_teammate_positions,
            believed_teammates,
        );
        let teammate_xy = &believed_teammate_positions[..teammate_count];
        let teammates = &believed_teammates[..teammate_count];
        push_rng_trace_for_player_entries(
            &mut state.trace_entries,
            state.trace_enabled,
            state.rng_trace_enabled,
            tick,
            "before_attack",
            idx,
            players[idx].name.as_str(),
            rng,
        );
        let mut fixed_candidate_count = 0;
        let mut dynamic_candidates = Vec::new();
        let mut goal_trace_json: Option<serde_json::Value> = None;
        let mut active_goal_type = players[idx]
            .goal_type
            .as_deref()
            .and_then(off_ball_attack_goal_type);
        let mut active_goal_target = players[idx].goal_target;
        let mut active_goal_value = players[idx].goal_value;
        for sample in anchor_samples.iter_mut() {
            sample.angle_unit = rng.random();
            sample.radius_unit = rng.random();
        }
        let anchor_input = OffBallRawGenerationInput {
            anchor: player_anchor,
            ball_pos: perceived_ball_pos,
            attacking_right,
            pitch_width: config.pitch_width,
            pitch_length: config.pitch_length,
            is_defender: player_is_defender,
            has_ball_carrier: perceived_has_ball_carrier,
            anchor_samples,
            support_samples: &[],
        };
        if use_fixed_buffers {
            fixed_candidate_count =
                generate_off_ball_attack_anchor_candidates_into(&anchor_input, fixed_candidates);
        } else {
            dynamic_candidates.extend(crate::generate_off_ball_attack_anchor_candidates(
                &anchor_input,
            ));
        }

        if perceived_has_ball_carrier {
            let arc_goal = evaluate_arc_arrival_goal(&ArcArrivalGoalInput {
                player_pos,
                anchor_pos: player_anchor,
                ball_pos: perceived_ball_pos,
                base_pos: player_base_pos,
                attacking_right,
                pitch_length: config.pitch_length,
                pitch_width: config.pitch_width,
            });
            let far_goal = evaluate_attack_far_post_goal(&AttackFarPostGoalInput {
                player_pos,
                anchor_pos: player_anchor,
                ball_pos: perceived_ball_pos,
                attacking_right,
                pitch_length: config.pitch_length,
                pitch_width: config.pitch_width,
                goal_width: config.goal_width,
            });
            let mut fixed_arrival_goal_count = 0;
            let mut dynamic_arrival_goals = Vec::new();
            if arc_goal.has_goal {
                if let Some(value) = attenuate_arrival_goal_for_teammate_occupancy(
                    &players[idx],
                    "arc_arrival_for_cutback",
                    arc_goal.target_pos,
                    arc_goal.value,
                ) {
                    if use_fixed_buffers {
                        fixed_arrival_goals[fixed_arrival_goal_count] =
                            ("arc_arrival_for_cutback", arc_goal.target_pos, value);
                        fixed_arrival_goal_count += 1;
                    } else {
                        dynamic_arrival_goals.push((
                            "arc_arrival_for_cutback",
                            arc_goal.target_pos,
                            value,
                        ));
                    }
                }
            }
            if far_goal.has_goal {
                if let Some(value) = attenuate_arrival_goal_for_teammate_occupancy(
                    &players[idx],
                    "attack_far_post",
                    far_goal.target_pos,
                    far_goal.value,
                ) {
                    if use_fixed_buffers {
                        fixed_arrival_goals[fixed_arrival_goal_count] =
                            ("attack_far_post", far_goal.target_pos, value);
                        fixed_arrival_goal_count += 1;
                    } else {
                        dynamic_arrival_goals.push(("attack_far_post", far_goal.target_pos, value));
                    }
                }
            }
            let arrival_context = GoalSwitchCostInput {
                base: 0.035,
                context_stability: 1.0,
                role_discipline: 1.0,
                pressure_interrupt: 0.0,
                iq: player_iq,
            };
            let dynamic_arrival_values = (!use_fixed_buffers).then(|| {
                dynamic_arrival_goals
                    .iter()
                    .map(|goal| goal.2)
                    .collect::<Vec<_>>()
            });
            if use_fixed_buffers {
                for (goal_index, goal) in fixed_arrival_goals[..fixed_arrival_goal_count]
                    .iter()
                    .enumerate()
                {
                    fixed_arrival_values[goal_index] = goal.2;
                }
                runner_goal_gaussians_into(
                    rng,
                    &arrival_context,
                    config.goal_noise_scale,
                    &mut fixed_arrival_gaussians[..fixed_arrival_goal_count],
                );
            }
            let dynamic_arrival_gaussians = dynamic_arrival_values.as_ref().map(|values| {
                runner_goal_gaussians(rng, values.len(), &arrival_context, config.goal_noise_scale)
            });
            let arrival_choice = if use_fixed_buffers {
                select_goal_candidate_with_gaussians(
                    &fixed_arrival_values[..fixed_arrival_goal_count],
                    &fixed_arrival_gaussians[..fixed_arrival_goal_count],
                    &arrival_context,
                    config.goal_noise_scale,
                )
            } else {
                select_goal_candidate_with_gaussians(
                    dynamic_arrival_values
                        .as_deref()
                        .expect("dynamic arrival values"),
                    dynamic_arrival_gaussians
                        .as_deref()
                        .expect("dynamic arrival gaussians"),
                    &arrival_context,
                    config.goal_noise_scale,
                )
            };
            let selected_arrival_goal = arrival_choice.as_ref().and_then(|choice| {
                if use_fixed_buffers {
                    fixed_arrival_goals
                        .get(choice.index)
                        .copied()
                        .filter(|_| choice.index < fixed_arrival_goal_count)
                } else {
                    dynamic_arrival_goals.get(choice.index).copied()
                }
            });
            if let Some((goal_type, target_pos, value)) = selected_arrival_goal {
                if let Some(target_player) = players.get_mut(idx) {
                    let switch_result = apply_arrival_goal_switch_with_details(
                        target_player,
                        goal_type,
                        target_pos,
                        value,
                        player_iq,
                        config,
                        rng,
                    );
                    active_goal_type = target_player
                        .goal_type
                        .as_deref()
                        .and_then(off_ball_attack_goal_type);
                    active_goal_target = target_player.goal_target;
                    active_goal_value = target_player.goal_value;
                    if matches!(
                        active_goal_type,
                        Some("arc_arrival_for_cutback" | "attack_far_post")
                    ) {
                        if crate::offside::is_offside_position(
                            active_goal_target,
                            attacking_right,
                            offside,
                            config.pitch_length,
                            Some(perceived_ball_pos.0),
                        ) {
                            let buffer = if active_goal_type == Some("attack_far_post") {
                                2.2
                            } else {
                                3.0
                            };
                            active_goal_target.0 = if attacking_right {
                                active_goal_target
                                    .0
                                    .min(offside - buffer)
                                    .min(config.pitch_length - 0.5)
                            } else {
                                active_goal_target.0.max(offside + buffer).max(0.5)
                            };
                            active_goal_target = pitch_clamp(
                                active_goal_target,
                                config.pitch_length,
                                config.pitch_width,
                            );
                            target_player.goal_target = active_goal_target;
                        }
                        let goal_candidate = OffBallAttackCandidateInput {
                            pos: active_goal_target,
                            anchor_pos: active_goal_target,
                        };
                        if use_fixed_buffers {
                            assert!(
                                fixed_candidate_count < MAX_FIXED_OFF_BALL_ATTACK_CANDIDATES,
                                "fixed off-ball candidate buffer is too small"
                            );
                            fixed_candidates[fixed_candidate_count] = goal_candidate;
                            fixed_candidate_count += 1;
                        } else {
                            dynamic_candidates.push(goal_candidate);
                        }
                    }
                    if config.trace_detail == "full" {
                        goal_trace_json = Some(json!({
                            "goal": {
                                "goal_type": active_goal_type.unwrap_or_default(),
                                "target_pos": [active_goal_target.0, active_goal_target.1],
                                "value": active_goal_value
                            },
                            "switched": switch_result.switched,
                            "switch_cost": switch_result.switch_cost,
                            "value_advantage": switch_result.value_advantage,
                            "reason": switch_result.reason,
                            "candidate_choice": {
                                "candidate_noise": arrival_choice.as_ref().map(|choice| choice.candidate_noise).unwrap_or(0.0),
                                "noisy_value": arrival_choice.as_ref().map(|choice| choice.noisy_value).unwrap_or(value)
                            },
                            "candidate": {
                                "goal_type": goal_type,
                                "target_pos": [target_pos.0, target_pos.1],
                                "value": value
                            }
                        }));
                    }
                }
            }

            for sample in support_samples.iter_mut() {
                sample.angle_unit = rng.random();
                sample.radius_unit = rng.random();
            }
            let support_input = OffBallRawGenerationInput {
                anchor: player_anchor,
                ball_pos: perceived_ball_pos,
                attacking_right,
                pitch_width: config.pitch_width,
                pitch_length: config.pitch_length,
                is_defender: player_is_defender,
                has_ball_carrier: true,
                anchor_samples: &[],
                support_samples,
            };
            if use_fixed_buffers {
                fixed_candidate_count += generate_off_ball_attack_support_candidates_into(
                    &support_input,
                    &mut fixed_candidates[fixed_candidate_count..],
                );
            } else {
                dynamic_candidates.extend(crate::generate_off_ball_attack_support_candidates(
                    &support_input,
                ));
            }
        }

        let candidates = if use_fixed_buffers {
            &fixed_candidates[..fixed_candidate_count]
        } else {
            dynamic_candidates.as_slice()
        };
        let current_goal = active_goal_type.map(|goal_type| crate::OffBallAttackGoalInput {
            goal_type,
            target_pos: active_goal_target,
            value: active_goal_value,
        });
        if use_fixed_buffers {
            let noise_scale = crate::goal::iq_decision_noise(player_iq) * config.iq_noise_scale;
            for noise in &mut fixed_noises[..candidates.len() + 1] {
                *noise = rng.gauss(0.0, noise_scale);
            }
        }
        let dynamic_noises = (!use_fixed_buffers)
            .then(|| iq_score_noises(rng, candidates.len() + 1, player_iq, config));
        let noises = dynamic_noises
            .as_deref()
            .unwrap_or(&fixed_noises[..candidates.len() + 1]);
        let mut stay_score = position_value(&PositionValueInput {
            x: player_pos.0,
            y: player_pos.1,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            attacking_right,
            opponent_positions: &opponent_xy,
            teammate_positions: &teammate_xy,
            skip_teammate_index: None,
            runner_formation_pos: Some(player_anchor),
        });
        if crate::offside::is_offside_position(
            player_pos,
            attacking_right,
            offside,
            config.pitch_length,
            Some(perceived_ball_pos.0),
        ) {
            stay_score *= 0.15;
        }
        stay_score *= 0.18;
        let batch_input = OffBallAttackBatchInput {
            player_index: idx,
            player_pos,
            player_speed: player_speed_ability,
            anchor: player_anchor,
            ball_pos: perceived_ball_pos,
            attacking_right,
            offside_line: offside,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            player_max_speed: config.player_max_speed,
            player_min_speed: config.player_min_speed,
            pass_to_space_ball_speed: config.pass_to_space_ball_speed,
            receive_reachability_scale: config.receive_reachability_scale,
            space_creation_radius: config.space_creation_radius,
            team_structure_weight,
            candidates,
            opponent_positions: opponent_xy,
            opponent_speeds,
            teammate_positions: teammate_xy,
            skip_teammate_index: None,
            teammates,
            current_goal,
        };
        let fixed_scored_count = if use_fixed_buffers {
            score_off_ball_attack_candidates_into(&batch_input, fixed_scored)
        } else {
            0
        };
        let dynamic_scored =
            (!use_fixed_buffers).then(|| crate::score_off_ball_attack_candidates(&batch_input));
        let scored = dynamic_scored
            .as_deref()
            .unwrap_or(&fixed_scored[..fixed_scored_count]);
        let offball_debug_alternatives = if config.trace_detail == "full" {
            let mut ranked = Vec::with_capacity(scored.len() + 1);
            ranked.push((
                stay_score * (1.0 + noises.first().copied().unwrap_or(0.0)),
                json!({
                    "phase": "off_ball_attack",
                    "action_type": "move",
                    "target": [player_pos.0, player_pos.1],
                    "value": {
                        "score": stay_score * (1.0 + noises.first().copied().unwrap_or(0.0)),
                        "base_score": stay_score,
                        "components": {"kind": "stay"}
                    }
                }),
            ));
            for (candidate_idx, value) in scored.iter().enumerate() {
                let score =
                    value.score * (1.0 + noises.get(candidate_idx + 1).copied().unwrap_or(0.0));
                ranked.push((
                    score,
                    json!({
                        "phase": "off_ball_attack",
                        "action_type": "move",
                        "target": [value.target.0, value.target.1],
                        "value": {
                            "score": score,
                            "base_score": value.score,
                            "components": {
                                "kind": "space",
                                "pv": value.pv,
                                "reach": value.reach,
                                "movement_reach": value.movement_reach,
                                "immediate_reach": value.immediate_reach,
                                "pass_feasibility": value.pass_feasibility,
                                "space_bonus": value.space_bonus,
                                "role_shape_factor": value.role_shape_factor,
                                "team_structure_factor": value.team_structure_factor,
                                "role_overlap_factor": value.role_overlap_factor,
                                "role_overlap": value.role_overlap,
                                "lane_factor": value.lane_factor,
                                "offside_penalty": value.offside_penalty,
                                "support_angle_value": value.support_angle_value,
                                "inside_support": value.inside_support,
                                "second_line_support": value.second_line_support,
                                "arrival_goal_fit": value.arrival_goal_fit,
                                "arrival_goal_multiplier": value.arrival_goal_multiplier,
                                "arrival_goal_bonus": value.arrival_goal_bonus,
                                "layoff_window": value.layoff_window,
                                "candidate_progress": value.candidate_progress,
                                "candidate_width": value.candidate_width,
                                "support_angle_dist": value.support_angle_dist,
                                "dist_to_ball": value.dist_to_ball
                            }
                        }
                    }),
                ));
            }
            ranked.sort_by(|(left, _), (right, _)| {
                right.partial_cmp(left).unwrap_or(std::cmp::Ordering::Equal)
            });
            Some(
                ranked
                    .into_iter()
                    .map(|(_, payload)| payload)
                    .collect::<Vec<_>>(),
            )
        } else {
            None
        };
        let choice_roll = preview_next_random(rng);
        let choice_input = OffBallAttackChoiceInput {
            player_index: idx,
            player_pos,
            player_speed: player_speed_ability,
            anchor: player_anchor,
            ball_pos: perceived_ball_pos,
            attacking_right,
            offside_line: offside,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            player_max_speed: config.player_max_speed,
            player_min_speed: config.player_min_speed,
            pass_to_space_ball_speed: config.pass_to_space_ball_speed,
            receive_reachability_scale: config.receive_reachability_scale,
            space_creation_radius: config.space_creation_radius,
            team_structure_weight,
            iq: player_iq,
            stay_score,
            candidates,
            opponent_positions: opponent_xy,
            opponent_speeds,
            teammate_positions: teammate_xy,
            skip_teammate_index: None,
            teammates,
            current_goal,
            score_noises: noises,
            roll: choice_roll,
        };
        let choice = if use_fixed_buffers {
            choose_off_ball_attack_target_from_scored(&choice_input, scored, fixed_selection_scores)
        } else {
            choose_off_ball_attack_target(&choice_input)
        };
        if let Some(choice) = choice {
            if choice.used_roll {
                advance_randoms(rng, 1);
            }
            if choice.components.kind == 1
                && choice.selected_candidate_index.is_some()
                && *spatial_player_count < RUNNER_TEAM_SIZE
            {
                let spatial_slot = *spatial_player_count;
                let (candidate_count, preferred_candidate_index) =
                    runner_build_spatial_attack_candidates(
                        &mut spatial_candidates[spatial_slot],
                        &mut spatial_components[spatial_slot],
                        &mut spatial_goal_types[spatial_slot],
                        player_pos,
                        choice.selected_candidate_index,
                        choice.score,
                        stay_score,
                        choice.components,
                        scored,
                        noises,
                        attacking_right,
                        active_goal_type,
                        active_goal_target,
                    );
                if candidate_count > 0 {
                    apply_communication_claim_costs(
                        &mut spatial_candidates[spatial_slot][..candidate_count],
                        idx,
                        &communication_claims[..shared_claim_count],
                        &communication_claim_owners[..shared_claim_count],
                        &communication_claim_strengths[..shared_claim_count],
                    );
                    let preferred_candidate_index = spatial_candidates[spatial_slot]
                        [..candidate_count]
                        .iter()
                        .enumerate()
                        .max_by(|(left_index, left), (right_index, right)| {
                            left.local_value
                                .partial_cmp(&right.local_value)
                                .unwrap_or(std::cmp::Ordering::Equal)
                                .then_with(|| right_index.cmp(left_index))
                        })
                        .map(|(candidate_index, _)| candidate_index)
                        .unwrap_or(preferred_candidate_index);
                    spatial_candidate_counts[spatial_slot] = candidate_count;
                    spatial_preferred_indices[spatial_slot] = preferred_candidate_index;
                    spatial_player_indices[spatial_slot] = idx;
                    *spatial_player_count += 1;
                }
            }
            if let Some(target_player) = players.get_mut(idx) {
                if choice.components.kind == 2 {
                    update_runner_movement_target(
                        target_player,
                        player_anchor,
                        Some("recover_shape"),
                    );
                    clear_player_goal(target_player);
                } else if choice.components.kind == 1 {
                    let goal_type = runner_spatial_attack_goal_type(
                        choice.target,
                        choice.score,
                        &choice.components,
                        active_goal_type,
                        active_goal_target,
                    );
                    let declared_goal =
                        matches!(goal_type, "arc_arrival_for_cutback" | "attack_far_post")
                            .then_some(crate::OffBallAttackGoalInput {
                                goal_type,
                                target_pos: choice.target,
                                value: choice.score.max(0.0),
                            });
                    let movement_intent = off_ball_attack_movement_intent(
                        player_pos,
                        player_anchor,
                        choice.target,
                        &choice.components,
                        declared_goal,
                        attacking_right,
                    );
                    update_runner_movement_target(
                        target_player,
                        choice.target,
                        Some(movement_intent),
                    );
                    commit_off_ball_attack_goal(
                        target_player,
                        goal_type,
                        choice.target,
                        choice.score,
                    );
                } else {
                    update_runner_movement_target(target_player, player_pos, Some("support"));
                    clear_player_goal(target_player);
                }
                if config.trace_detail == "full" {
                    let declaration = target_player
                        .goal_type
                        .as_deref()
                        .and_then(off_ball_attack_goal_type)
                        .map(|goal_type| RunnerGoalSummary {
                            goal_type,
                            target: target_player.goal_target,
                            value: target_player.goal_value,
                        });
                    state.trace_decisions.push(json!({
                        "tick": tick,
                        "team": if team_home { "home" } else { "away" },
                        "player_idx": idx,
                        "player": target_player.name.clone(),
                        "phase": "off_ball_attack",
                        "pos": [player_pos.0, player_pos.1],
                        "chosen": {
                            "phase": "off_ball_attack",
                            "action_type": "move",
                            "target": [choice.target.0, choice.target.1],
                            "value": {
                                "score": choice.max_score,
                                "selected_score": choice.score,
                                "stay_score": stay_score,
                                "candidate_count": choice.candidate_count,
                                "used_roll": choice.used_roll,
                                "roll": choice_roll,
                                "score_noises": noises,
                                "components": {
                                    "kind": choice.components.kind,
                                    "pv": choice.components.pv,
                                    "reach": choice.components.reach,
                                    "movement_reach": choice.components.movement_reach,
                                    "immediate_reach": choice.components.immediate_reach,
                                    "pass_feasibility": choice.components.pass_feasibility,
                                    "space_bonus": choice.components.space_bonus,
                                    "role_shape_factor": choice.components.role_shape_factor,
                                    "team_structure_factor": choice.components.team_structure_factor,
                                    "role_overlap_factor": choice.components.role_overlap_factor,
                                    "role_overlap": choice.components.role_overlap,
                                    "lane_factor": choice.components.lane_factor,
                                    "offside_penalty": choice.components.offside_penalty,
                                    "support_angle_value": choice.components.support_angle_value,
                                    "inside_support": choice.components.inside_support,
                                    "second_line_support": choice.components.second_line_support,
                                    "arrival_goal_fit": choice.components.arrival_goal_fit,
                                    "arrival_goal_multiplier": choice.components.arrival_goal_multiplier,
                                    "arrival_goal_bonus": choice.components.arrival_goal_bonus,
                                    "layoff_window": choice.components.layoff_window,
                                    "candidate_progress": choice.components.candidate_progress,
                                    "candidate_width": choice.components.candidate_width,
                                    "support_angle_dist": choice.components.support_angle_dist,
                                    "dist_to_ball": choice.components.dist_to_ball
                                }
                            }
                        },
                        "declaration": declaration.map(|summary| json!({
                            "goal_type": summary.goal_type,
                            "raw_target": [summary.target.0, summary.target.1],
                            "value": summary.value,
                        })).unwrap_or(serde_json::Value::Null),
                        "goal": goal_trace_json.clone().unwrap_or_else(|| json!({
                            "goal": {
                                "goal_type": declaration.map(|summary| summary.goal_type).unwrap_or_default(),
                                "target_pos": declaration.map(|summary| [summary.target.0, summary.target.1]).unwrap_or([target_player.goal_target.0, target_player.goal_target.1]),
                                "value": declaration.map(|summary| summary.value).unwrap_or(target_player.goal_value)
                            },
                            "switched": false,
                            "switch_cost": 0.0,
                            "value_advantage": 0.0,
                            "reason": "candidate_task_declaration"
                        })),
                        "alternatives": offball_debug_alternatives.clone().unwrap_or_default()
                    }));
                }
                selected_count += 1;
            }
        }
        push_rng_trace_for_player_entries(
            &mut state.trace_entries,
            state.trace_enabled,
            state.rng_trace_enabled,
            tick,
            "after_attack",
            idx,
            players[idx].name.as_str(),
            rng,
        );
    }
    let coordinated_spatial_count = *spatial_player_count;
    if coordinated_spatial_count > 0 {
        let spatial_inputs: [TeamSpatialPlayerInput<'_>; RUNNER_TEAM_SIZE] =
            std::array::from_fn(|slot| {
                if slot < coordinated_spatial_count {
                    TeamSpatialPlayerInput {
                        index: spatial_player_indices[slot],
                        candidates: &spatial_candidates[slot][..spatial_candidate_counts[slot]],
                        preferred_candidate_index: spatial_preferred_indices[slot],
                    }
                } else {
                    TeamSpatialPlayerInput {
                        index: 0,
                        candidates: &spatial_candidates[slot][..0],
                        preferred_candidate_index: 0,
                    }
                }
            });
        let coordination = coordinate_team_spatial_tasks_into(
            &TeamSpatialAssignmentInput {
                players: &spatial_inputs[..coordinated_spatial_count],
            },
            &mut spatial_assignments[..coordinated_spatial_count],
        );
        debug_assert_eq!(
            coordination.conflicts_after, 0,
            "each spatial player has a no-claim fallback, so joint attack coordination must resolve all active claim conflicts"
        );
        for spatial_slot in 0..coordinated_spatial_count {
            let assignment = spatial_assignments[spatial_slot];
            let player_index = spatial_player_indices[spatial_slot];
            let Some(candidate) = spatial_candidates[spatial_slot]
                .get(assignment.candidate_index)
                .copied()
            else {
                continue;
            };
            let components = spatial_components[spatial_slot][assignment.candidate_index];
            let goal_type = spatial_goal_types[spatial_slot][assignment.candidate_index];
            let Some(player) = players.get_mut(player_index) else {
                continue;
            };
            let previous_target = player.target_pos;
            let mut task_accepted = None;
            if components.kind != 0 {
                let declared_goal =
                    matches!(goal_type, "arc_arrival_for_cutback" | "attack_far_post").then_some(
                        crate::OffBallAttackGoalInput {
                            goal_type,
                            target_pos: candidate.target,
                            value: candidate.local_value.max(0.0),
                        },
                    );
                let movement_intent = off_ball_attack_movement_intent(
                    player.pos,
                    player.tactical_anchor,
                    candidate.target,
                    &components,
                    declared_goal,
                    attacking_right,
                );
                update_runner_movement_target(player, candidate.target, Some(movement_intent));
                commit_off_ball_attack_goal(
                    player,
                    goal_type,
                    candidate.target,
                    candidate.local_value,
                );
                task_accepted = Some(accept_player_tactical_task_with_coordination(
                    player,
                    goal_type,
                    "support",
                    candidate.target,
                    candidate.local_value,
                    tick,
                    plan_signals,
                    attacking_right,
                    config,
                    TacticalTaskCoordination {
                        commitment: 1.0,
                        ..TacticalTaskCoordination::default()
                    },
                ));
            } else {
                update_runner_movement_target(player, player.pos, Some("support"));
                clear_player_goal(player);
            }
            if components.kind != 0 {
                let summary = RunnerGoalSummary {
                    goal_type,
                    target: candidate.target,
                    value: candidate.local_value.max(0.0),
                };
                if best_goal
                    .as_ref()
                    .map(|current| summary.value > current.value)
                    .unwrap_or(true)
                {
                    best_goal = Some(summary);
                }
            }
            if config.trace_detail == "full" {
                state.trace_decisions.push(json!({
                    "tick": tick,
                    "team": if team_home { "home" } else { "away" },
                    "player_idx": player_index,
                    "player": player.name.clone(),
                    "phase": "off_ball_attack_spatial_coordination",
                    "resolution": {
                        "reason": "spatial_claim_conflict",
                        "target_before": [previous_target.0, previous_target.1],
                        "target_after": [candidate.target.0, candidate.target.1],
                        "local_value": candidate.local_value,
                        "candidate_index": assignment.candidate_index,
                        "preferred_candidate_index": spatial_preferred_indices[spatial_slot],
                        "conflicts_before": coordination.conflicts_before,
                        "conflicts_after": coordination.conflicts_after,
                        "displaced_count": coordination.displaced_count,
                    },
                    "declaration": {
                        "goal_type": player.goal_type,
                        "raw_target": [player.goal_target.0, player.goal_target.1],
                        "value": player.goal_value,
                        "task_accepted": task_accepted.map(|acceptance| acceptance.accepted),
                        "task_candidate_value": task_accepted.map(|acceptance| acceptance.candidate_value),
                        "task_retained_value": task_accepted.map(|acceptance| acceptance.retained_value),
                    },
                    "claim": {
                        "origin": [candidate.claim.origin.0, candidate.claim.origin.1],
                        "target": [candidate.claim.target.0, candidate.claim.target.1],
                        "occupancy_radius": candidate.claim.occupancy_radius,
                        "corridor_half_width": candidate.claim.corridor_half_width,
                        "depth_band": candidate.claim.depth_band,
                        "width_band": candidate.claim.width_band,
                    },
                }));
            }
        }
    }
    (selected_count, best_goal)
}

fn apply_off_ball_defense_choices_fixed(
    defenders: &mut [RunnerPlayer],
    _attackers: &[RunnerPlayer],
    _ball_pos: (f64, f64),
    attacking_right: bool,
    _carrier_pos: Option<(f64, f64)>,
    _carrier_consecutive_carries: i32,
    _carrier_possession_ticks: i32,
    _carrier_control_readiness: f64,
    plan_signals: TeamPlanSignals,
    active_indices: Option<&[bool]>,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
    arena: &mut RunnerFixedDefenseArena,
    include_phase1_inputs: bool,
) -> (i32, Option<RunnerGoalSummary>, RunnerDefenderPhase1Inputs) {
    let mut coordinated_count = 0;
    for idx in 0..defenders.len() {
        if active_indices
            .and_then(|indices| indices.get(idx))
            .map(|active| !*active)
            .unwrap_or(false)
        {
            continue;
        }
        if defenders[idx].position == "GK" {
            if let Some(player) = defenders.get_mut(idx) {
                apply_goalkeeper_coverage_target(player, attacking_right, config);
            }
            continue;
        }
        assert!(
            coordinated_count < RUNNER_TEAM_SIZE,
            "fixed defense coordinated players exceed team size"
        );

        let defender = &defenders[idx];
        let (
            perceived_ball_pos,
            perceived_carrier_pos,
            perceived_possession_ticks,
            perceived_control_readiness,
            observed_attacker_count,
            observed_teammate_count,
        ) = belief_defense_inputs_into(defender, &mut arena.attacker_xy, &mut arena.team_defenders);
        for sample in &mut arena.random_samples {
            sample.angle_unit = rng.random();
            sample.radius_unit = rng.random();
        }
        let empty_score_noises: [f64; 0] = [];
        let empty_rolls: [f64; 0] = [];
        let empty_fallback_indices: [usize; 0] = [];
        let base_input = DefenseChoiceInput {
            defender_pos: defender.pos,
            anchor: defender.tactical_anchor,
            base_ref: defender.base_pos,
            ball_pos: perceived_ball_pos,
            ball_carrier_pos: perceived_carrier_pos,
            ball_carrier_consecutive_carries: 0,
            ball_carrier_possession_ticks: perceived_possession_ticks,
            carrier_control_readiness: perceived_control_readiness,
            attacking_right,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            press_radius: config.press_radius,
            tackle_range: config.tackle_range,
            carrier_speed: config.carrier_speed,
            press_intensity: plan_signals.press_intensity,
            compactness: plan_signals.compactness,
            movement: runner_defense_movement_input(defender, plan_signals, config),
            iq: defender.iq,
            attackers: &arena.attacker_xy[..observed_attacker_count],
            teammates: &arena.team_defenders[..observed_teammate_count],
            random_samples: &arena.random_samples,
            score_noises: &empty_score_noises,
            roll_by_count: &empty_rolls,
            fallback_index_by_count: &empty_fallback_indices,
        };
        let Some(prepared_choice) = prepare_fixed_defense_choice(&base_input) else {
            continue;
        };
        let candidate_count = prepared_choice.candidate_count;
        if candidate_count == 0 {
            continue;
        }
        assert!(
            candidate_count <= MAX_FIXED_TEAM_DEFENSE_CANDIDATES,
            "fixed defense candidate count exceeds buffer"
        );
        let noise_scale = crate::goal::iq_decision_noise(defender.iq) * config.iq_noise_scale;
        for noise in &mut arena.score_noises[..candidate_count] {
            *noise = rng.gauss(0.0, noise_scale);
        }

        let max_noisy_score = (0..candidate_count)
            .map(|candidate_index| {
                prepared_choice.candidate_scores[candidate_index]
                    * (1.0 + arena.score_noises[candidate_index])
            })
            .fold(f64::NEG_INFINITY, f64::max);
        let mut roll_by_count = [0.0; MAX_FIXED_TEAM_DEFENSE_CANDIDATES + 1];
        let mut fallback_index_by_count = [0; MAX_FIXED_TEAM_DEFENSE_CANDIDATES + 1];
        if let Some((used_roll, used_random_choice)) =
            fixed_defense_random_branch_from_noisy_max(candidate_count, max_noisy_score)
        {
            if used_random_choice {
                fallback_index_by_count[candidate_count] = rng.randbelow(candidate_count);
            } else if used_roll {
                roll_by_count[candidate_count] = rng.random();
            }
        }
        let Some(selection) = select_fixed_defense_action(
            &prepared_choice,
            defender.iq,
            &arena.score_noises[..candidate_count],
            &roll_by_count,
            &fallback_index_by_count,
        ) else {
            continue;
        };
        arena.prepared_choices[coordinated_count] = Some(prepared_choice);
        arena.coordinated_indices[coordinated_count] = idx;
        arena.selected_candidate_indices[coordinated_count] = selection.chosen_index;
        arena.selected_scores[coordinated_count] = selection.score;
        coordinated_count += 1;
    }

    let mut selected_count = 0;
    let mut best_goal: Option<RunnerGoalSummary> = None;
    for choice_slot in 0..coordinated_count {
        let prepared_choice =
            arena.prepared_choices[choice_slot].expect("coordinated fixed defense choice");
        let candidate_index = arena.selected_candidate_indices[choice_slot];
        if candidate_index >= prepared_choice.candidate_count {
            continue;
        }
        let target = prepared_choice.candidate_targets[candidate_index];
        let selected_action_type = prepared_choice.candidate_action_types[candidate_index];
        let selected_score = arena.selected_scores[choice_slot];
        let pressure = prepared_choice.press_access;
        let threat = prepared_choice
            .shot_danger
            .max(prepared_choice.carrier_control_threat);
        let candidate = build_defensive_goal(&DefensiveGoalBuildInput {
            action_type: selected_action_type,
            target_pos: target,
            value: selected_score,
            pressure,
            threat,
        });
        let Some(target_defender) = defenders.get_mut(arena.coordinated_indices[choice_slot])
        else {
            continue;
        };
        let current_goal_type = target_defender.goal_type.as_deref();
        let current_goal_is_defensive = current_goal_type
            .map(|goal_type| goal_type.starts_with("defend_"))
            .unwrap_or(false);
        let current_goal_matches_candidate =
            current_goal_is_defensive && current_goal_type == Some(candidate.goal_type);
        if current_goal_matches_candidate {
            target_defender.goal_target = candidate.target_pos;
            target_defender.goal_value = candidate.value;
        } else {
            let defender_iq = target_defender.iq;
            let _ = apply_player_goal_switch_with_details(
                target_defender,
                candidate.goal_type,
                "defend",
                candidate.target_pos,
                candidate.value,
                defender_iq,
                0.022,
                candidate.threat * 0.55,
                config,
                rng,
            );
        }
        let requested_intent =
            crate::off_ball_defense::defense_action_movement_intent(selected_action_type);
        if matches!(
            selected_action_type,
            "close_down" | "tackle" | "approach" | "pursuit"
        ) {
            update_runner_text(&mut target_defender.state, "pressing");
        } else if target_defender.state == "pressing"
            && !matches!(
                selected_action_type,
                "close_down" | "tackle" | "mark_runner" | "block_lane"
            )
        {
            update_runner_text(&mut target_defender.state, "off_ball");
        }
        target_defender.target_pos = target;
        update_runner_text(&mut target_defender.movement_intent, requested_intent);
        update_runner_text(&mut target_defender.last_def_action, selected_action_type);
        let summary = RunnerGoalSummary {
            goal_type: candidate.goal_type,
            target,
            value: candidate.value,
        };
        if best_goal
            .as_ref()
            .map(|goal| summary.value > goal.value)
            .unwrap_or(true)
        {
            best_goal = Some(summary);
        }
        selected_count += 1;
    }
    let interaction_inputs = include_phase1_inputs
        .then(|| defender_phase1_inputs(defenders, plan_signals, config))
        .unwrap_or_else(RunnerDefenderPhase1Inputs::empty);
    (selected_count, best_goal, interaction_inputs)
}

fn defense_task_kind(action_type: &str) -> DefenseTaskKind {
    match action_type {
        "close_down" => DefenseTaskKind::CloseDown,
        "tackle" | "approach" => DefenseTaskKind::Press,
        "pursuit" => DefenseTaskKind::Pursuit,
        "mark_runner" => DefenseTaskKind::Mark,
        "block_lane" => DefenseTaskKind::BlockLane,
        _ => DefenseTaskKind::RecoverShape,
    }
}

fn register_defense_unit_visible_attacker(
    arena: &mut RunnerFixedDefenseArena,
    index: usize,
    pos: (f64, f64),
    confidence: f64,
) {
    if confidence < 0.08 {
        return;
    }
    let existing = arena.unit_attacker_ids[..arena.unit_attacker_count]
        .iter()
        .position(|existing_index| *existing_index == index);
    if let Some(existing) = existing {
        if confidence > arena.unit_attacker_confidence[existing] {
            arena.unit_attacker_xy[existing] = pos;
            arena.unit_attacker_confidence[existing] = confidence;
        }
        return;
    }
    if arena.unit_attacker_count == RUNNER_TEAM_SIZE {
        return;
    }
    let slot = arena.unit_attacker_count;
    arena.unit_attacker_ids[slot] = index;
    arena.unit_attacker_xy[slot] = pos;
    arena.unit_attacker_confidence[slot] = confidence;
    arena.unit_attacker_count += 1;
}

fn defense_task_coordination(
    claim: crate::DefenseResourceClaim,
    local_value: f64,
) -> TacticalTaskCoordination {
    let claim_strength = claim
        .carrier_closure
        .max(claim.carrier_engagement)
        .max(claim.cover)
        .max(claim.lane_screen)
        .max(claim.depth_protection.into_iter().fold(0.0_f64, f64::max))
        .max(claim.wide_balance[0])
        .max(claim.wide_balance[1])
        .max(claim.outlet_coverage.into_iter().fold(0.0_f64, f64::max));
    let value_confidence = local_value.max(0.0) / (1.0 + local_value.max(0.0));
    TacticalTaskCoordination {
        commitment: (0.34 + 0.46 * claim_strength + 0.20 * value_confidence).clamp(0.0, 1.0),
        carrier_closure: claim.carrier_closure,
        carrier_engagement: claim.carrier_engagement,
        cover: claim.cover,
        lane_screen: claim.lane_screen,
        depth_protection: claim.depth_protection,
        wide_balance: claim.wide_balance,
        outlet_coverage: claim.outlet_coverage,
    }
}

fn apply_coordinated_off_ball_defense_choices(
    defenders: &mut [RunnerPlayer],
    attacking_right: bool,
    plan_signals: TeamPlanSignals,
    active_indices: Option<&[bool]>,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
    arena: &mut RunnerFixedDefenseArena,
    trace_decisions: &mut Vec<serde_json::Value>,
    tick: i32,
    defender_team_home: bool,
    include_phase1_inputs: bool,
) -> (i32, Option<RunnerGoalSummary>, RunnerDefenderPhase1Inputs) {
    arena.unit_attacker_count = 0;
    let mut coordinated_count = 0;
    let mut ball_weight = 0.0;
    let mut weighted_ball_pos = (0.0, 0.0);
    let mut carrier_visible = false;
    let mut immediate_threat = 0.0_f64;

    for idx in 0..defenders.len() {
        if active_indices
            .and_then(|indices| indices.get(idx))
            .map(|active| !*active)
            .unwrap_or(false)
        {
            continue;
        }
        if defenders[idx].position == "GK" {
            if let Some(player) = defenders.get_mut(idx) {
                apply_goalkeeper_coverage_target(player, attacking_right, config);
            }
            continue;
        }
        assert!(
            coordinated_count < RUNNER_TEAM_SIZE,
            "coordinated defense players exceed team size"
        );

        let choice_slot = coordinated_count;
        let defender = &defenders[idx];
        let belief = defender.tactical_belief;
        let belief_weight = belief.ball_confidence.clamp(0.0, 1.0);
        ball_weight += belief_weight;
        weighted_ball_pos.0 += belief.ball_pos.0 * belief_weight;
        weighted_ball_pos.1 += belief.ball_pos.1 * belief_weight;
        for entity in belief.entities() {
            if !entity.is_teammate && !entity.is_goalkeeper {
                register_defense_unit_visible_attacker(
                    arena,
                    entity.index,
                    entity.pos,
                    entity.confidence,
                );
            }
        }

        let (
            perceived_ball_pos,
            perceived_carrier_pos,
            perceived_possession_ticks,
            perceived_control_readiness,
            observed_attacker_count,
            observed_teammate_count,
        ) = belief_defense_inputs_into(defender, &mut arena.attacker_xy, &mut arena.team_defenders);
        carrier_visible |= perceived_carrier_pos.is_some();
        for sample in &mut arena.team_random_samples[choice_slot] {
            sample.angle_unit = rng.random();
            sample.radius_unit = rng.random();
        }
        let empty_score_noises: [f64; 0] = [];
        let empty_rolls: [f64; 0] = [];
        let empty_fallback_indices: [usize; 0] = [];
        let input = DefenseChoiceInput {
            defender_pos: defender.pos,
            anchor: defender.tactical_anchor,
            base_ref: defender.base_pos,
            ball_pos: perceived_ball_pos,
            ball_carrier_pos: perceived_carrier_pos,
            ball_carrier_consecutive_carries: 0,
            ball_carrier_possession_ticks: perceived_possession_ticks,
            carrier_control_readiness: perceived_control_readiness,
            attacking_right,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            press_radius: config.press_radius,
            tackle_range: config.tackle_range,
            carrier_speed: config.carrier_speed,
            press_intensity: plan_signals.press_intensity,
            compactness: plan_signals.compactness,
            movement: runner_defense_movement_input(defender, plan_signals, config),
            iq: defender.iq,
            attackers: &arena.attacker_xy[..observed_attacker_count],
            teammates: &arena.team_defenders[..observed_teammate_count],
            random_samples: &arena.team_random_samples[choice_slot],
            score_noises: &empty_score_noises,
            roll_by_count: &empty_rolls,
            fallback_index_by_count: &empty_fallback_indices,
        };
        let Some(prepared) = prepare_fixed_defense_choice(&input) else {
            continue;
        };
        let candidate_count = prepared.candidate_count;
        if candidate_count == 0 {
            continue;
        }
        assert!(
            candidate_count <= MAX_FIXED_TEAM_DEFENSE_CANDIDATES,
            "fixed defense candidate count exceeds buffer"
        );
        let noise_scale = crate::goal::iq_decision_noise(defender.iq) * config.iq_noise_scale;
        for noise in &mut arena.team_score_noises[choice_slot][..candidate_count] {
            *noise = rng.gauss(0.0, noise_scale);
        }
        let max_noisy_score = (0..candidate_count)
            .map(|candidate_index| {
                prepared.candidate_scores[candidate_index]
                    * (1.0 + arena.team_score_noises[choice_slot][candidate_index])
            })
            .fold(f64::NEG_INFINITY, f64::max);
        let mut roll_by_count = [0.0; MAX_FIXED_TEAM_DEFENSE_CANDIDATES + 1];
        let mut fallback_index_by_count = [0; MAX_FIXED_TEAM_DEFENSE_CANDIDATES + 1];
        if let Some((used_roll, used_random_choice)) =
            fixed_defense_random_branch_from_noisy_max(candidate_count, max_noisy_score)
        {
            if used_random_choice {
                fallback_index_by_count[candidate_count] = rng.randbelow(candidate_count);
            } else if used_roll {
                roll_by_count[candidate_count] = rng.random();
            }
        }
        let local_selection = select_fixed_defense_action(
            &prepared,
            defender.iq,
            &arena.team_score_noises[choice_slot][..candidate_count],
            &roll_by_count,
            &fallback_index_by_count,
        )
        .expect("prepared defense candidates must be selectable");
        arena.local_candidate_indices[choice_slot] = local_selection.chosen_index;
        arena.local_selection_rolls[choice_slot] = roll_by_count[candidate_count];
        arena.local_fallback_indices[choice_slot] = fallback_index_by_count[candidate_count];
        arena.local_selection_used_roll[choice_slot] = local_selection.used_roll;
        arena.local_selection_used_random_choice[choice_slot] = local_selection.used_random_choice;
        let task = defender.tactical_task;
        arena.task_continuities[choice_slot] = crate::DefenseTaskContinuity {
            active: task.active(tick) && task.coordination.active(),
            target: task.raw_target,
            commitment: task.commitment * task.coordination.commitment,
            resource_claim: crate::DefenseResourceClaim {
                carrier_closure: task.coordination.carrier_closure,
                carrier_engagement: task.coordination.carrier_engagement,
                cover: task.coordination.cover,
                lane_screen: task.coordination.lane_screen,
                depth_protection: task.coordination.depth_protection,
                wide_balance: task.coordination.wide_balance,
                outlet_coverage: task.coordination.outlet_coverage,
            },
        };

        let own_goal_x = if attacking_right {
            0.0
        } else {
            config.pitch_length
        };
        let threat = prepared
            .shot_danger
            .max(prepared.carrier_control_threat)
            .clamp(0.0, 1.0);
        immediate_threat = immediate_threat.max(threat);
        for candidate_index in 0..candidate_count {
            let action_type = prepared.candidate_action_types[candidate_index];
            let task_kind = defense_task_kind(action_type);
            let projected_pos = prepared.candidate_projected_positions[candidate_index];
            let target = prepared.candidate_targets[candidate_index];
            let starting_distance = distance(defender.pos, target);
            let projected_distance = distance(projected_pos, target);
            let convergence = crate::physics::smoothstep(
                0.02,
                (starting_distance * 0.22).max(0.45),
                (starting_distance - projected_distance).max(0.0),
            );
            let carrier_closure = if matches!(
                task_kind,
                DefenseTaskKind::CloseDown | DefenseTaskKind::Press | DefenseTaskKind::Pursuit
            ) {
                let immediate_closure = 1.0
                    - crate::physics::smoothstep(
                        config.press_radius * 0.45,
                        config.press_radius * 1.20,
                        projected_distance,
                    );
                let pursuit_reachability =
                    if matches!(task_kind, DefenseTaskKind::Press | DefenseTaskKind::Pursuit) {
                        crate::off_ball_defense::defensive_approach_reachability(
                            defender.pos,
                            perceived_ball_pos,
                            defender.tactical_anchor,
                            config.press_radius,
                            runner_defense_movement_input(defender, plan_signals, config),
                            4,
                        )
                    } else {
                        0.0
                    };
                immediate_closure.max(0.72 * pursuit_reachability) * (0.38 + 0.62 * convergence)
            } else {
                0.0
            };
            let pressure_coverage = if task_kind == DefenseTaskKind::Press {
                let contact_reach = (0.75 + 0.36 * config.tackle_range.max(0.0))
                    * if action_type == "tackle" { 1.08 } else { 0.94 };
                let carrier_access = 1.0
                    - crate::physics::smoothstep(
                        contact_reach * 0.34,
                        contact_reach,
                        projected_distance,
                    );
                let threat_denial = if threat > 1e-6 {
                    (1.0 - prepared.candidate_residual_threats[candidate_index] / threat)
                        .clamp(0.0, 1.0)
                } else {
                    carrier_access
                };
                carrier_access * (0.30 + 0.70 * threat_denial)
            } else {
                0.0
            };
            let resource_claim = defense_resource_claim(
                task_kind,
                projected_pos,
                perceived_ball_pos,
                own_goal_x,
                config.pitch_width,
                carrier_closure,
                pressure_coverage,
            );
            arena.team_candidates[choice_slot][candidate_index] = TeamDefenseCandidate {
                target,
                projected_pos,
                local_value: (prepared.candidate_scores[candidate_index]
                    * (1.0 + arena.team_score_noises[choice_slot][candidate_index]))
                    .max(0.0),
                residual_threat: prepared.candidate_residual_threats[candidate_index],
                pressure_coverage,
                resource_claim,
                task_kind,
            };
        }
        arena.prepared_choices[choice_slot] = Some(prepared);
        arena.coordinated_indices[choice_slot] = idx;
        coordinated_count += 1;
    }

    if coordinated_count == 0 {
        let interaction_inputs = include_phase1_inputs
            .then(|| defender_phase1_inputs(defenders, plan_signals, config))
            .unwrap_or_else(RunnerDefenderPhase1Inputs::empty);
        return (0, None, interaction_inputs);
    }

    let unit_ball_pos = if ball_weight > 1e-6 {
        (
            weighted_ball_pos.0 / ball_weight,
            weighted_ball_pos.1 / ball_weight,
        )
    } else {
        defenders
            .iter()
            .find(|player| player.position != "GK")
            .map(|player| player.tactical_belief.ball_pos)
            .unwrap_or((config.pitch_length * 0.5, config.pitch_width * 0.5))
    };
    let own_goal_x = if attacking_right {
        0.0
    } else {
        config.pitch_length
    };
    let resource_demand = defense_resource_demand_from_visible_threats(
        unit_ball_pos,
        &arena.unit_attacker_xy[..arena.unit_attacker_count],
        own_goal_x,
        config.pitch_length,
        config.pitch_width,
        immediate_threat,
        plan_signals.press_intensity,
        carrier_visible,
    );
    for choice_slot in 0..coordinated_count {
        let prepared = arena.prepared_choices[choice_slot]
            .expect("active coordinated defender has prepared candidates");
        for candidate_index in 0..prepared.candidate_count {
            let candidate = &mut arena.team_candidates[choice_slot][candidate_index];
            candidate.resource_claim = defense_resource_claim_with_outlets(
                candidate.task_kind,
                candidate.projected_pos,
                unit_ball_pos,
                own_goal_x,
                config.pitch_width,
                candidate.resource_claim.carrier_closure,
                candidate.pressure_coverage,
                &arena.unit_attacker_xy[..arena.unit_attacker_count],
            );
        }
    }
    let player_inputs: [TeamDefensePlayerInput<'_>; RUNNER_TEAM_SIZE] =
        std::array::from_fn(|choice_slot| {
            if choice_slot < coordinated_count {
                let prepared = arena.prepared_choices[choice_slot]
                    .expect("active coordinated defender has prepared candidates");
                let defender_index = arena.coordinated_indices[choice_slot];
                TeamDefensePlayerInput {
                    index: defender_index,
                    anchor: defenders[defender_index].tactical_anchor,
                    candidates: &arena.team_candidates[choice_slot][..prepared.candidate_count],
                }
            } else {
                TeamDefensePlayerInput {
                    index: 0,
                    anchor: (0.0, 0.0),
                    candidates: &arena.team_candidates[choice_slot][..0],
                }
            }
        });
    let coordination_summary = coordinate_team_defense_into(
        &crate::TeamDefenseAssignmentInput {
            players: &player_inputs[..coordinated_count],
            compactness: plan_signals.compactness,
            immediate_threat,
            press_intensity: plan_signals.press_intensity,
            resource_demand,
            local_candidate_indices: Some(&arena.local_candidate_indices[..coordinated_count]),
            task_continuities: Some(&arena.task_continuities[..coordinated_count]),
        },
        &mut arena.team_assignments[..coordinated_count],
    );

    let mut selected_count = 0;
    let mut best_goal: Option<RunnerGoalSummary> = None;
    for choice_slot in 0..coordinated_count {
        let prepared =
            arena.prepared_choices[choice_slot].expect("coordinated fixed defense choice");
        let assignment = arena.team_assignments[choice_slot];
        let candidate_index = assignment.candidate_index;
        if candidate_index >= prepared.candidate_count {
            continue;
        }
        let selected = arena.team_candidates[choice_slot][candidate_index];
        let selected_action_type = prepared.candidate_action_types[candidate_index];
        let pressure = selected.pressure_coverage;
        let threat = prepared.shot_danger.max(prepared.carrier_control_threat);
        let goal = build_defensive_goal(&DefensiveGoalBuildInput {
            action_type: selected_action_type,
            target_pos: selected.target,
            value: selected.local_value,
            pressure,
            threat,
        });
        let defender_index = arena.coordinated_indices[choice_slot];
        let Some(target_defender) = defenders.get_mut(defender_index) else {
            continue;
        };
        let previous_goal_type = target_defender.goal_type.clone();
        let previous_goal_value = target_defender.goal_value;
        update_runner_optional_text(&mut target_defender.goal_type, Some(goal.goal_type));
        update_runner_optional_text(&mut target_defender.goal_phase, Some("defend"));
        target_defender.goal_target = goal.target_pos;
        target_defender.goal_value = goal.value.max(0.0);
        target_defender.goal_action_code = 3;
        let task_acceptance = accept_player_tactical_task_with_coordination(
            target_defender,
            goal.goal_type,
            "defend",
            goal.target_pos,
            goal.value,
            tick,
            plan_signals,
            attacking_right,
            config,
            defense_task_coordination(selected.resource_claim, selected.local_value),
        );
        let requested_intent =
            crate::off_ball_defense::defense_action_movement_intent(selected_action_type);
        if matches!(
            selected_action_type,
            "close_down" | "tackle" | "approach" | "pursuit"
        ) {
            update_runner_text(&mut target_defender.state, "pressing");
        } else if target_defender.state == "pressing"
            && !matches!(
                selected_action_type,
                "close_down" | "tackle" | "mark_runner" | "block_lane"
            )
        {
            update_runner_text(&mut target_defender.state, "off_ball");
        }
        target_defender.target_pos = selected.target;
        update_runner_text(&mut target_defender.movement_intent, requested_intent);
        update_runner_text(&mut target_defender.last_def_action, selected_action_type);
        let summary = RunnerGoalSummary {
            goal_type: goal.goal_type,
            target: selected.target,
            value: goal.value,
        };
        if matches!(config.trace_detail.as_str(), "top_candidates" | "full") {
            trace_decisions.push(json!({
                "tick": tick,
                "team": if defender_team_home { "home" } else { "away" },
                "player_idx": defender_index,
                "player": target_defender.name,
                "phase": "off_ball_defense",
                "pos": [target_defender.pos.0, target_defender.pos.1],
                "rng": {
                    "random_samples": arena.team_random_samples[choice_slot].iter().map(|sample| json!([sample.angle_unit, sample.radius_unit])).collect::<Vec<_>>(),
                    "score_noises": arena.team_score_noises[choice_slot][..prepared.candidate_count],
                    "roll": arena.local_selection_rolls[choice_slot],
                    "fallback_index": arena.local_fallback_indices[choice_slot],
                },
                "chosen": {
                    "phase": "off_ball_defense",
                    "action_type": selected_action_type,
                    "target": [selected.target.0, selected.target.1],
                    "raw_target": [selected.target.0, selected.target.1],
                    "value": {
                        "score": selected.local_value,
                        "candidate_count": prepared.candidate_count,
                        "local_attackers_count": prepared.local_attackers_count,
                        "dangerous_receivers_count": prepared.dangerous_receivers_count,
                        "candidate_targets": prepared.candidate_targets[..prepared.candidate_count].iter().map(|target| json!([target.0, target.1])).collect::<Vec<_>>(),
                        "candidate_scores": prepared.candidate_scores[..prepared.candidate_count],
                        "candidate_projected_positions": prepared.candidate_projected_positions[..prepared.candidate_count].iter().map(|target| json!([target.0, target.1])).collect::<Vec<_>>(),
                        "candidate_action_types": prepared.candidate_action_types[..prepared.candidate_count],
                        "candidate_residual_threats": prepared.candidate_residual_threats[..prepared.candidate_count],
                        "local_selection": {
                            "candidate_index": arena.local_candidate_indices[choice_slot],
                            "used_roll": arena.local_selection_used_roll[choice_slot],
                            "used_random_choice": arena.local_selection_used_random_choice[choice_slot],
                        },
                    },
                },
                "team_assignment": {
                    "candidate_index": candidate_index,
                    "local_candidate_index": arena.local_candidate_indices[choice_slot],
                    "objective": coordination_summary.objective,
                    "formation_scale": coordination_summary.formation_scale,
                    "local_intent_cost": assignment.local_intent_cost,
                    "task_retarget_cost": assignment.task_retarget_cost,
                    "resource_claim": {
                        "carrier_closure": selected.resource_claim.carrier_closure,
                        "carrier_engagement": selected.resource_claim.carrier_engagement,
                        "cover": selected.resource_claim.cover,
                        "lane_screen": selected.resource_claim.lane_screen,
                        "depth_protection": selected.resource_claim.depth_protection,
                        "wide_balance": selected.resource_claim.wide_balance,
                        "outlet_coverage": selected.resource_claim.outlet_coverage,
                    },
                    "resource_demand": {
                        "carrier_closure": resource_demand.carrier_closure,
                        "carrier_engagement": resource_demand.carrier_engagement,
                        "cover": resource_demand.cover,
                        "lane_screen": resource_demand.lane_screen,
                        "depth_protection": resource_demand.depth_protection,
                        "wide_balance": resource_demand.wide_balance,
                        "outlet_coverage": resource_demand.outlet_coverage,
                    },
                    "unit_visible_attackers": arena.unit_attacker_count,
                    "carrier_visible": carrier_visible,
                },
                "goal": {
                    "goal": {
                        "goal_type": summary.goal_type,
                        "target_pos": [summary.target.0, summary.target.1],
                        "value": summary.value,
                    },
                    "stored_goal": {
                        "goal_type": target_defender.goal_type,
                        "target_pos": [target_defender.goal_target.0, target_defender.goal_target.1],
                        "value": target_defender.goal_value,
                    },
                    "switched": previous_goal_type.as_deref() != Some(goal.goal_type),
                    "switch_cost": 0.0,
                    "value_advantage": goal.value - previous_goal_value,
                    "reason": "team_defense_assignment",
                },
                "task": {
                    "accepted": task_acceptance.accepted,
                    "candidate_value": task_acceptance.candidate_value,
                    "retained_value": task_acceptance.retained_value,
                },
            }));
        }
        if best_goal
            .as_ref()
            .map(|best| summary.value > best.value)
            .unwrap_or(true)
        {
            best_goal = Some(summary);
        }
        selected_count += 1;
    }
    let interaction_inputs = include_phase1_inputs
        .then(|| defender_phase1_inputs(defenders, plan_signals, config))
        .unwrap_or_else(RunnerDefenderPhase1Inputs::empty);
    (selected_count, best_goal, interaction_inputs)
}

fn apply_off_ball_defense_choices(
    defenders: &mut [RunnerPlayer],
    _attackers: &[RunnerPlayer],
    _ball_pos: (f64, f64),
    attacking_right: bool,
    _carrier_pos: Option<(f64, f64)>,
    _carrier_consecutive_carries: i32,
    _carrier_possession_ticks: i32,
    _carrier_control_readiness: f64,
    plan_signals: TeamPlanSignals,
    active_indices: Option<&[bool]>,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
    fixed_defense_arena: Option<&mut RunnerFixedDefenseArena>,
    trace_decisions: &mut Vec<serde_json::Value>,
    tick: i32,
    defender_team_home: bool,
    include_phase1_inputs: bool,
) -> (i32, Option<RunnerGoalSummary>, RunnerDefenderPhase1Inputs) {
    let mut fallback_arena;
    let arena = match fixed_defense_arena {
        Some(arena) => arena,
        None => {
            fallback_arena = RunnerFixedDefenseArena::new();
            &mut fallback_arena
        }
    };
    apply_coordinated_off_ball_defense_choices(
        defenders,
        attacking_right,
        plan_signals,
        active_indices,
        config,
        rng,
        arena,
        trace_decisions,
        tick,
        defender_team_home,
        include_phase1_inputs,
    )
}

#[allow(dead_code)]
fn apply_off_ball_defense_choices_legacy(
    defenders: &mut [RunnerPlayer],
    attackers: &[RunnerPlayer],
    ball_pos: (f64, f64),
    attacking_right: bool,
    carrier_pos: Option<(f64, f64)>,
    carrier_consecutive_carries: i32,
    carrier_possession_ticks: i32,
    carrier_control_readiness: f64,
    plan_signals: TeamPlanSignals,
    active_indices: Option<&[bool]>,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
    fixed_defense_arena: Option<&mut RunnerFixedDefenseArena>,
    trace_decisions: &mut Vec<serde_json::Value>,
    tick: i32,
    defender_team_home: bool,
    include_phase1_inputs: bool,
) -> (i32, Option<RunnerGoalSummary>, RunnerDefenderPhase1Inputs) {
    if config.trace_detail == "off" {
        let mut fallback_arena;
        let arena = match fixed_defense_arena {
            Some(arena) => arena,
            None => {
                fallback_arena = RunnerFixedDefenseArena::new();
                &mut fallback_arena
            }
        };
        return apply_off_ball_defense_choices_fixed(
            defenders,
            attackers,
            ball_pos,
            attacking_right,
            carrier_pos,
            carrier_consecutive_carries,
            carrier_possession_ticks,
            carrier_control_readiness,
            plan_signals,
            active_indices,
            config,
            rng,
            arena,
            include_phase1_inputs,
        );
    }
    let mut coordinated_choices = Vec::new();

    for idx in 0..defenders.len() {
        if active_indices
            .and_then(|indices| indices.get(idx))
            .map(|active| !*active)
            .unwrap_or(false)
        {
            continue;
        }
        if defenders[idx].position == "GK" {
            if let Some(player) = defenders.get_mut(idx) {
                apply_goalkeeper_coverage_target(player, attacking_right, config);
            }
            continue;
        }
        let defender = defenders[idx].clone();
        let mut belief_attackers = [(0.0, 0.0); RUNNER_TEAM_SIZE];
        let mut belief_teammates = [RUNNER_EMPTY_FIXED_DEFENSE_TEAMMATE; RUNNER_TEAM_SIZE];
        let (
            perceived_ball_pos,
            perceived_carrier_pos,
            perceived_possession_ticks,
            perceived_control_readiness,
            observed_attacker_count,
            observed_teammate_count,
        ) = belief_defense_inputs_into(&defender, &mut belief_attackers, &mut belief_teammates);
        let random_samples = random_defense_samples(rng, RUNNER_DEFENSE_RANDOM_SAMPLE_COUNT);
        let empty_score_noises: Vec<f64> = Vec::new();
        let empty_rolls: Vec<f64> = Vec::new();
        let empty_fallback_indices: Vec<usize> = Vec::new();
        let base_input = DefenseChoiceInput {
            defender_pos: defender.pos,
            anchor: defender.tactical_anchor,
            base_ref: defender.base_pos,
            ball_pos: perceived_ball_pos,
            ball_carrier_pos: perceived_carrier_pos,
            ball_carrier_consecutive_carries: 0,
            ball_carrier_possession_ticks: perceived_possession_ticks,
            carrier_control_readiness: perceived_control_readiness,
            attacking_right,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            press_radius: config.press_radius,
            tackle_range: config.tackle_range,
            carrier_speed: config.carrier_speed,
            press_intensity: plan_signals.press_intensity,
            compactness: plan_signals.compactness,
            movement: runner_defense_movement_input(&defender, plan_signals, config),
            iq: defender.iq,
            attackers: &belief_attackers[..observed_attacker_count],
            teammates: &belief_teammates[..observed_teammate_count],
            random_samples: &random_samples,
            score_noises: &empty_score_noises,
            roll_by_count: &empty_rolls,
            fallback_index_by_count: &empty_fallback_indices,
        };
        let Some(prepared_choice) = prepare_defense_choice(&base_input) else {
            continue;
        };
        let candidate_count = prepared_choice.candidate_count();
        if candidate_count == 0 {
            continue;
        }
        let score_noises = iq_score_noises(rng, candidate_count, defender.iq, config);
        let random_branch =
            prepared_defense_choice_random_branch(&prepared_choice, defender.iq, &score_noises);
        let mut roll_by_count = vec![0.0; candidate_count + 1];
        let mut fallback_index_by_count = vec![0; candidate_count + 1];
        if let Some((used_roll, used_random_choice)) = random_branch {
            if used_random_choice {
                fallback_index_by_count[candidate_count] = rng.randbelow(candidate_count);
            } else if used_roll {
                roll_by_count[candidate_count] = rng.random();
            }
        }
        if let Some(choice) = select_prepared_defense_action(
            &prepared_choice,
            defender.iq,
            &score_noises,
            &roll_by_count,
            &fallback_index_by_count,
        ) {
            coordinated_choices.push(CoordinatedDefenseChoice {
                index: idx,
                defender,
                random_samples,
                score_noises,
                roll: roll_by_count[candidate_count],
                fallback_index: fallback_index_by_count[candidate_count],
                choice,
            });
        }
    }

    let mut selected_count = 0;
    let mut best_goal: Option<RunnerGoalSummary> = None;
    for coordinated in &coordinated_choices {
        let target = coordinated.choice.target;
        let selected_action_type = coordinated.choice.action_type;
        let selected_score = coordinated.choice.score;
        let pressure = coordinated.choice.press_access;
        let threat = coordinated
            .choice
            .shot_danger
            .max(coordinated.choice.carrier_control_threat);
        let candidate = build_defensive_goal(&DefensiveGoalBuildInput {
            action_type: selected_action_type,
            target_pos: target,
            value: selected_score,
            pressure,
            threat,
        });
        let Some(target_defender) = defenders.get_mut(coordinated.index) else {
            continue;
        };
        let current_goal_type = target_defender.goal_type.as_deref();
        let current_goal_is_defensive = current_goal_type
            .map(|goal_type| goal_type.starts_with("defend_"))
            .unwrap_or(false);
        let current_goal_matches_candidate =
            current_goal_is_defensive && current_goal_type == Some(candidate.goal_type);
        let switch_result = if current_goal_matches_candidate {
            let value_advantage = candidate.value - target_defender.goal_value;
            target_defender.goal_target = candidate.target_pos;
            target_defender.goal_value = candidate.value;
            RunnerGoalSwitchResult {
                switched: false,
                switch_cost: 0.0,
                value_advantage,
                reason: "current_defensive_goal_updated",
            }
        } else {
            apply_player_goal_switch_with_details(
                target_defender,
                candidate.goal_type,
                "defend",
                candidate.target_pos,
                candidate.value,
                coordinated.defender.iq,
                0.022,
                candidate.threat * 0.55,
                config,
                rng,
            )
        };
        let requested_intent =
            crate::off_ball_defense::defense_action_movement_intent(selected_action_type);
        if matches!(
            selected_action_type,
            "close_down" | "tackle" | "approach" | "pursuit"
        ) {
            update_runner_text(&mut target_defender.state, "pressing");
        } else if target_defender.state == "pressing"
            && !matches!(
                selected_action_type,
                "close_down" | "tackle" | "mark_runner" | "block_lane"
            )
        {
            update_runner_text(&mut target_defender.state, "off_ball");
        }
        target_defender.target_pos = target;
        update_runner_text(&mut target_defender.movement_intent, requested_intent);
        update_runner_text(&mut target_defender.last_def_action, selected_action_type);
        let summary = RunnerGoalSummary {
            goal_type: candidate.goal_type,
            target,
            value: candidate.value,
        };
        if matches!(config.trace_detail.as_str(), "top_candidates" | "full") {
            trace_decisions.push(json!({
                "tick": tick,
                "team": if defender_team_home { "home" } else { "away" },
                "player_idx": coordinated.index,
                "player": coordinated.defender.name,
                "phase": "off_ball_defense",
                "pos": [coordinated.defender.pos.0, coordinated.defender.pos.1],
                "rng": {
                    "random_samples": coordinated.random_samples.iter().map(|sample| json!([sample.angle_unit, sample.radius_unit])).collect::<Vec<_>>(),
                    "score_noises": coordinated.score_noises,
                    "roll": coordinated.roll,
                    "fallback_index": coordinated.fallback_index,
                },
                "chosen": {
                    "phase": "off_ball_defense",
                    "action_type": selected_action_type,
                    "target": [target.0, target.1],
                    "raw_target": [target.0, target.1],
                    "value": {
                        "score": selected_score,
                        "candidate_count": coordinated.choice.candidate_count,
                        "local_attackers_count": coordinated.choice.local_attackers_count,
                        "dangerous_receivers_count": coordinated.choice.dangerous_receivers_count,
                        "candidate_targets": coordinated.choice.candidate_targets.iter().map(|target| json!([target.0, target.1])).collect::<Vec<_>>(),
                        "candidate_scores": coordinated.choice.candidate_scores,
                        "candidate_projected_positions": coordinated.choice.candidate_projected_positions.iter().map(|target| json!([target.0, target.1])).collect::<Vec<_>>(),
                        "candidate_action_types": coordinated.choice.candidate_action_types,
                        "candidate_residual_threats": coordinated.choice.candidate_residual_threats,
                        "local_selection": {
                            "candidate_index": coordinated.choice.candidate_targets.iter().position(|candidate_target| *candidate_target == target),
                            "used_roll": coordinated.choice.used_roll,
                            "used_random_choice": coordinated.choice.used_random_choice,
                        }
                    }
                },
                "goal": {
                    "goal": {
                        "goal_type": summary.goal_type,
                        "target_pos": [summary.target.0, summary.target.1],
                        "value": summary.value,
                    },
                    "stored_goal": {
                        "goal_type": target_defender.goal_type,
                        "target_pos": [target_defender.goal_target.0, target_defender.goal_target.1],
                        "value": target_defender.goal_value
                    },
                    "switched": switch_result.switched,
                    "switch_cost": switch_result.switch_cost,
                    "value_advantage": switch_result.value_advantage,
                    "reason": switch_result.reason
                }
            }));
        }
        if best_goal
            .as_ref()
            .map(|goal| summary.value > goal.value)
            .unwrap_or(true)
        {
            best_goal = Some(summary);
        }
        selected_count += 1;
    }
    let interaction_inputs = include_phase1_inputs
        .then(|| defender_phase1_inputs(defenders, plan_signals, config))
        .unwrap_or_else(RunnerDefenderPhase1Inputs::empty);
    (selected_count, best_goal, interaction_inputs)
}

#[allow(dead_code)]
fn apply_off_ball_defense_choices_individually(
    defenders: &mut [RunnerPlayer],
    _attackers: &[RunnerPlayer],
    _ball_pos: (f64, f64),
    attacking_right: bool,
    _carrier_pos: Option<(f64, f64)>,
    _carrier_consecutive_carries: i32,
    _carrier_possession_ticks: i32,
    _carrier_control_readiness: f64,
    plan_signals: TeamPlanSignals,
    active_indices: Option<&[bool]>,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
    trace_decisions: &mut Vec<serde_json::Value>,
    tick: i32,
    defender_team_home: bool,
) -> (i32, Option<RunnerGoalSummary>, RunnerDefenderPhase1Inputs) {
    let mut selected_count = 0;
    let mut best_goal: Option<RunnerGoalSummary> = None;
    for idx in 0..defenders.len() {
        if active_indices
            .and_then(|indices| indices.get(idx))
            .map(|active| !*active)
            .unwrap_or(false)
        {
            continue;
        }
        if defenders[idx].position == "GK" {
            if let Some(player) = defenders.get_mut(idx) {
                apply_goalkeeper_coverage_target(player, attacking_right, config);
            }
            continue;
        }
        let defender = defenders[idx].clone();
        let mut belief_attackers = [(0.0, 0.0); RUNNER_TEAM_SIZE];
        let mut belief_teammates = [RUNNER_EMPTY_FIXED_DEFENSE_TEAMMATE; RUNNER_TEAM_SIZE];
        let (
            perceived_ball_pos,
            perceived_carrier_pos,
            perceived_possession_ticks,
            perceived_control_readiness,
            observed_attacker_count,
            observed_teammate_count,
        ) = belief_defense_inputs_into(&defender, &mut belief_attackers, &mut belief_teammates);
        let samples = random_defense_samples(rng, 3);
        let empty_score_noises: Vec<f64> = Vec::new();
        let empty_rolls: Vec<f64> = Vec::new();
        let empty_fallback_indices: Vec<usize> = Vec::new();
        let candidate_count = choose_defense_action(&DefenseChoiceInput {
            defender_pos: defender.pos,
            anchor: defender.tactical_anchor,
            base_ref: defender.base_pos,
            ball_pos: perceived_ball_pos,
            ball_carrier_pos: perceived_carrier_pos,
            ball_carrier_consecutive_carries: 0,
            ball_carrier_possession_ticks: perceived_possession_ticks,
            carrier_control_readiness: perceived_control_readiness,
            attacking_right,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            press_radius: config.press_radius,
            tackle_range: config.tackle_range,
            carrier_speed: config.carrier_speed,
            press_intensity: plan_signals.press_intensity,
            compactness: plan_signals.compactness,
            movement: runner_defense_movement_input(&defender, plan_signals, config),
            iq: defender.iq,
            attackers: &belief_attackers[..observed_attacker_count],
            teammates: &belief_teammates[..observed_teammate_count],
            random_samples: &samples,
            score_noises: &empty_score_noises,
            roll_by_count: &empty_rolls,
            fallback_index_by_count: &empty_fallback_indices,
        })
        .map(|choice| choice.candidate_count)
        .unwrap_or(0);
        if candidate_count == 0 {
            continue;
        }
        let score_noises = iq_score_noises(rng, candidate_count, defender.iq, config);
        let branch_probe = choose_defense_action(&DefenseChoiceInput {
            defender_pos: defender.pos,
            anchor: defender.tactical_anchor,
            base_ref: defender.base_pos,
            ball_pos: perceived_ball_pos,
            ball_carrier_pos: perceived_carrier_pos,
            ball_carrier_consecutive_carries: 0,
            ball_carrier_possession_ticks: perceived_possession_ticks,
            carrier_control_readiness: perceived_control_readiness,
            attacking_right,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            press_radius: config.press_radius,
            tackle_range: config.tackle_range,
            carrier_speed: config.carrier_speed,
            press_intensity: plan_signals.press_intensity,
            compactness: plan_signals.compactness,
            movement: runner_defense_movement_input(&defender, plan_signals, config),
            iq: defender.iq,
            attackers: &belief_attackers[..observed_attacker_count],
            teammates: &belief_teammates[..observed_teammate_count],
            random_samples: &samples,
            score_noises: &score_noises,
            roll_by_count: &empty_rolls,
            fallback_index_by_count: &empty_fallback_indices,
        });
        let mut roll_by_count = vec![0.0; candidate_count + 1];
        let mut fallback_index_by_count = vec![0; candidate_count + 1];
        if let Some(probe) = branch_probe.as_ref() {
            if probe.used_random_choice {
                fallback_index_by_count[candidate_count] = rng.randbelow(candidate_count);
            } else if probe.used_roll {
                roll_by_count[candidate_count] = rng.random();
            }
        }
        if let Some(choice) = choose_defense_action(&DefenseChoiceInput {
            defender_pos: defender.pos,
            anchor: defender.tactical_anchor,
            base_ref: defender.base_pos,
            ball_pos: perceived_ball_pos,
            ball_carrier_pos: perceived_carrier_pos,
            ball_carrier_consecutive_carries: 0,
            ball_carrier_possession_ticks: perceived_possession_ticks,
            carrier_control_readiness: perceived_control_readiness,
            attacking_right,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            press_radius: config.press_radius,
            tackle_range: config.tackle_range,
            carrier_speed: config.carrier_speed,
            press_intensity: plan_signals.press_intensity,
            compactness: plan_signals.compactness,
            movement: runner_defense_movement_input(&defender, plan_signals, config),
            iq: defender.iq,
            attackers: &belief_attackers[..observed_attacker_count],
            teammates: &belief_teammates[..observed_teammate_count],
            random_samples: &samples,
            score_noises: &score_noises,
            roll_by_count: &roll_by_count,
            fallback_index_by_count: &fallback_index_by_count,
        }) {
            if let Some(target_defender) = defenders.get_mut(idx) {
                let pressure = choice.press_access;
                let threat = choice.shot_danger.max(choice.carrier_control_threat);
                let candidate = build_defensive_goal(&DefensiveGoalBuildInput {
                    action_type: choice.action_type,
                    target_pos: choice.target,
                    value: choice.score,
                    pressure,
                    threat,
                });
                let current_goal_type = target_defender.goal_type.as_deref();
                let current_goal_is_defensive = current_goal_type
                    .map(|goal_type| goal_type.starts_with("defend_"))
                    .unwrap_or(false);
                let current_goal_matches_candidate =
                    current_goal_is_defensive && current_goal_type == Some(candidate.goal_type);
                let switch_result = if current_goal_matches_candidate {
                    let value_advantage = candidate.value - target_defender.goal_value;
                    target_defender.goal_target = candidate.target_pos;
                    target_defender.goal_value = candidate.value;
                    RunnerGoalSwitchResult {
                        switched: false,
                        switch_cost: 0.0,
                        value_advantage,
                        reason: "current_defensive_goal_updated",
                    }
                } else {
                    apply_player_goal_switch_with_details(
                        target_defender,
                        candidate.goal_type,
                        "defend",
                        candidate.target_pos,
                        candidate.value,
                        defender.iq,
                        0.022,
                        candidate.threat * 0.55,
                        config,
                        rng,
                    )
                };
                let selected_action_type = candidate.action_type;
                let requested_intent =
                    crate::off_ball_defense::defense_action_movement_intent(selected_action_type);
                if matches!(
                    selected_action_type,
                    "close_down" | "tackle" | "approach" | "pursuit"
                ) {
                    update_runner_text(&mut target_defender.state, "pressing");
                } else if target_defender.state == "pressing"
                    && !matches!(
                        selected_action_type,
                        "close_down" | "tackle" | "mark_runner" | "block_lane"
                    )
                {
                    update_runner_text(&mut target_defender.state, "off_ball");
                }
                target_defender.target_pos = candidate.target_pos;
                update_runner_text(&mut target_defender.movement_intent, requested_intent);
                update_runner_text(&mut target_defender.last_def_action, candidate.action_type);
                let summary = RunnerGoalSummary {
                    goal_type: candidate.goal_type,
                    target: candidate.target_pos,
                    value: candidate.value,
                };
                if matches!(config.trace_detail.as_str(), "top_candidates" | "full") {
                    trace_decisions.push(json!({
                        "tick": tick,
                        "team": if defender_team_home { "home" } else { "away" },
                        "player_idx": idx,
                        "player": defender.name,
                        "phase": "off_ball_defense",
                        "pos": [defender.pos.0, defender.pos.1],
                        "rng": {
                            "random_samples": samples.iter().map(|sample| json!([sample.angle_unit, sample.radius_unit])).collect::<Vec<_>>(),
                            "score_noises": score_noises,
                            "roll": roll_by_count.get(choice.candidate_count).copied().unwrap_or(0.0),
                            "fallback_index": fallback_index_by_count.get(choice.candidate_count).copied().unwrap_or(0),
                        },
                        "chosen": {
                            "phase": "off_ball_defense",
                            "action_type": selected_action_type,
                            "target": [target_defender.target_pos.0, target_defender.target_pos.1],
                            "raw_target": [choice.target.0, choice.target.1],
                            "value": {
                                "score": choice.score,
                                "candidate_count": choice.candidate_count,
                                "local_attackers_count": choice.local_attackers_count,
                                "dangerous_receivers_count": choice.dangerous_receivers_count,
                                "raw_targets": choice.raw_targets.iter().map(|target| json!([target.0, target.1])).collect::<Vec<_>>(),
                                "candidate_targets": choice.candidate_targets.iter().map(|target| json!([target.0, target.1])).collect::<Vec<_>>(),
                                "candidate_scores": choice.candidate_scores,
                                  "candidate_movement_targets": choice.candidate_movement_targets.iter().map(|target| json!([target.0, target.1])).collect::<Vec<_>>(),
                                  "candidate_projected_positions": choice.candidate_projected_positions.iter().map(|target| json!([target.0, target.1])).collect::<Vec<_>>(),
                                  "candidate_action_types": choice.candidate_action_types,
                                  "candidate_residual_threats": choice.candidate_residual_threats,
                                "used_roll": choice.used_roll,
                                "used_random_choice": choice.used_random_choice,
                                "debug_attackers": belief_attackers[..observed_attacker_count].iter().map(|target| json!([target.0, target.1])).collect::<Vec<_>>(),
                                "debug_teammates": belief_teammates[..observed_teammate_count].iter().map(|target| json!([target.pos.0, target.pos.1, target.target_pos.0, target.target_pos.1])).collect::<Vec<_>>(),
                                "components": {
                                    "base_score": choice.base_score,
                                    "press_value": choice.press_value,
                                    "press_access": choice.press_access,
                                    "shot_danger": choice.shot_danger,
                                    "carrier_control_threat": choice.carrier_control_threat,
                                    "carrier_threat": choice.carrier_threat,
                                    "shot_lane_closure": choice.shot_lane_closure,
                                    "best_mark_value": choice.best_mark_value
                                }
                            }
                        },
                        "goal": {
                            "goal": {
                                "goal_type": summary.goal_type,
                                "target_pos": [summary.target.0, summary.target.1],
                                "value": summary.value,
                                "confidence": summary.value,
                                "created_tick": tick,
                                "last_updated_tick": tick,
                                "context": {
                                    "phase": "defend",
                                    "completion": "deny_space_or_recover_shape",
                                    "abort": "possession_or_threat_changed",
                                    "handoff": "defensive_space_value",
                                    "action": selected_action_type,
                                    "pressure": pressure,
                                    "threat": threat
                                }
                            },
                            "stored_goal": {
                                "goal_type": target_defender.goal_type.clone(),
                                "target_pos": [target_defender.goal_target.0, target_defender.goal_target.1],
                                "value": target_defender.goal_value
                            },
                            "switched": switch_result.switched,
                            "switch_cost": switch_result.switch_cost,
                            "value_advantage": switch_result.value_advantage,
                            "switch_noise": 0.0,
                            "noisy_value_advantage": switch_result.value_advantage,
                            "reason": switch_result.reason
                        }
                    }));
                }
                if best_goal
                    .as_ref()
                    .map(|goal| summary.value > goal.value)
                    .unwrap_or(true)
                {
                    best_goal = Some(summary);
                }
                selected_count += 1;
            }
        }
    }
    let interaction_inputs = defender_phase1_inputs(defenders, plan_signals, config);
    (selected_count, best_goal, interaction_inputs)
}

fn update_held_tick_targets(
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    state: &mut RunnerMatchState,
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
    tick: i32,
    rng: &mut RunnerRng,
) -> (i32, i32) {
    let home_phase = phase_name(state.home_phase_code);
    let away_phase = phase_name(state.away_phase_code);
    let (home_intent, away_intent) = match state.ball.holder_team_home {
        Some(true) => ("support", "defend_shape"),
        Some(false) => ("defend_shape", "support"),
        None => ("contest", "contest"),
    };
    apply_team_shape_targets(
        home,
        away,
        state.ball.position,
        home_attacking_right,
        home_phase,
        state.home_plan_signals,
        home_intent,
        if state.ball.holder_team_home == Some(true) {
            state.ball.holder_idx
        } else {
            None
        },
        config,
        &mut state.team_shape_arena,
    );
    apply_team_shape_targets(
        away,
        home,
        state.ball.position,
        !home_attacking_right,
        away_phase,
        state.away_plan_signals,
        away_intent,
        if state.ball.holder_team_home == Some(false) {
            state.ball.holder_idx
        } else {
            None
        },
        config,
        &mut state.team_shape_arena,
    );
    refresh_team_tactical_beliefs(
        home,
        away,
        state.ball.position,
        home_attacking_right,
        config,
    );
    refresh_team_tactical_beliefs(
        away,
        home,
        state.ball.position,
        !home_attacking_right,
        config,
    );
    let mut attack_choices = 0;
    let mut attack_goal: Option<RunnerGoalSummary> = None;
    if state.ball.holder_team_home == Some(true) {
        let attack = apply_off_ball_attack_choices(
            home,
            state,
            tick,
            true,
            home_attacking_right,
            state.ball.holder_idx,
            None,
            config,
            rng,
        );
        attack_choices += attack.0;
        attack_goal = attack.1;
        sync_team_tactical_tasks_from_goals(
            home,
            tick,
            state.home_plan_signals,
            home_attacking_right,
            config,
            &mut state.trace_decisions,
            true,
        );
    } else if state.ball.holder_team_home == Some(false) {
        let attack = apply_off_ball_attack_choices(
            away,
            state,
            tick,
            false,
            !home_attacking_right,
            state.ball.holder_idx,
            None,
            config,
            rng,
        );
        attack_choices += attack.0;
        attack_goal = attack.1;
        sync_team_tactical_tasks_from_goals(
            away,
            tick,
            state.away_plan_signals,
            !home_attacking_right,
            config,
            &mut state.trace_decisions,
            false,
        );
    }
    if let Some(goal) = attack_goal {
        trace_entry!(
            state,
            json!({
                "type": "event",
                "event": "off_ball_goal",
                "tick": tick,
                "side": "attack",
                "goal_type": goal.goal_type,
                "target": [round_one(goal.target.0), round_one(goal.target.1)],
                "value": round_two(goal.value)
            })
        );
    }
    (attack_choices, 0)
}

fn update_held_tick_defense_targets(
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    state: &mut RunnerMatchState,
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
    tick: i32,
    rng: &mut RunnerRng,
) -> (i32, RunnerDefenderPhase1Inputs) {
    refresh_team_tactical_beliefs(
        home,
        away,
        state.ball.position,
        home_attacking_right,
        config,
    );
    refresh_team_tactical_beliefs(
        away,
        home,
        state.ball.position,
        !home_attacking_right,
        config,
    );
    let carrier_pos = state.ball.holder_team_home.and_then(|holder_home| {
        state.ball.holder_idx.and_then(|idx| {
            if holder_home {
                home.get(idx).map(|player| player.pos)
            } else {
                away.get(idx).map(|player| player.pos)
            }
        })
    });
    let carrier_consecutive_carries = state
        .ball
        .holder_team_home
        .and_then(|holder_home| {
            state.ball.holder_idx.and_then(|idx| {
                if holder_home {
                    home.get(idx).map(|player| player.consecutive_carries)
                } else {
                    away.get(idx).map(|player| player.consecutive_carries)
                }
            })
        })
        .unwrap_or(0);
    let carrier_possession_ticks = state
        .ball
        .holder_team_home
        .and_then(|holder_home| {
            state.ball.holder_idx.and_then(|idx| {
                if holder_home {
                    home.get(idx).map(|player| player.possession_ticks)
                } else {
                    away.get(idx).map(|player| player.possession_ticks)
                }
            })
        })
        .unwrap_or(0);
    let carrier_control_readiness = crate::continuation_control_readiness(state.ball.control);
    let (defense_choices, defense_goal, defender_inputs) =
        if state.ball.holder_team_home == Some(true) {
            let result = apply_off_ball_defense_choices(
                away,
                home,
                state.ball.position,
                !home_attacking_right,
                carrier_pos,
                carrier_consecutive_carries,
                carrier_possession_ticks,
                carrier_control_readiness,
                state.away_plan_signals,
                None,
                config,
                rng,
                Some(&mut state.fixed_defense_arena),
                &mut state.trace_decisions,
                tick,
                false,
                true,
            );
            sync_team_tactical_tasks_from_goals(
                away,
                tick,
                state.away_plan_signals,
                !home_attacking_right,
                config,
                &mut state.trace_decisions,
                false,
            );
            result
        } else if state.ball.holder_team_home == Some(false) {
            let result = apply_off_ball_defense_choices(
                home,
                away,
                state.ball.position,
                home_attacking_right,
                carrier_pos,
                carrier_consecutive_carries,
                carrier_possession_ticks,
                carrier_control_readiness,
                state.home_plan_signals,
                None,
                config,
                rng,
                Some(&mut state.fixed_defense_arena),
                &mut state.trace_decisions,
                tick,
                true,
                true,
            );
            sync_team_tactical_tasks_from_goals(
                home,
                tick,
                state.home_plan_signals,
                home_attacking_right,
                config,
                &mut state.trace_decisions,
                true,
            );
            result
        } else {
            (0, None, RunnerDefenderPhase1Inputs::empty())
        };
    if let Some(goal) = defense_goal {
        trace_entry!(
            state,
            json!({
                "type": "event",
                "event": "off_ball_goal",
                "tick": tick,
                "side": "defense",
                "goal_type": goal.goal_type,
                "target": [round_one(goal.target.0), round_one(goal.target.1)],
                "value": round_two(goal.value)
            })
        );
    }
    (defense_choices, defender_inputs)
}

fn apply_held_tick_movement(
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    original_holder_home: bool,
    original_holder_idx: usize,
    tick: i32,
    home_plan_signals: TeamPlanSignals,
    away_plan_signals: TeamPlanSignals,
    defender_phase1_inputs: &RunnerDefenderPhase1Inputs,
    config: &RunnerRuntimeConfig,
) {
    for (team_home, players, plan_signals) in [
        (true, home, home_plan_signals),
        (false, away, away_plan_signals),
    ] {
        for (idx, player) in players.iter_mut().enumerate() {
            let is_holder = original_holder_home == team_home && original_holder_idx == idx;
            if is_holder {
                continue;
            }
            if player.state == "stunned" {
                continue;
            }
            if team_home != original_holder_home {
                apply_runner_defender_movement(
                    player,
                    idx,
                    plan_signals,
                    defender_phase1_inputs,
                    config,
                );
            } else {
                let movement_target = player_effective_movement_target(player, tick, plan_signals);
                let movement = player_move_tick(&PlayerMoveTickInput {
                    pos: player.pos,
                    target_pos: movement_target,
                    velocity: player.velocity,
                    speed_ability: player.speed.round() as i32,
                    movement_intent: player.movement_intent.as_str(),
                    state: player.state.as_str(),
                    player_max_speed: config.player_max_speed,
                    player_min_speed: config.player_min_speed,
                    pitch_length: config.pitch_length,
                    pitch_width: config.pitch_width,
                });
                player.pos = movement.pos;
                player.velocity = movement.velocity;
                if let Some(facing) = movement.facing_direction {
                    player.facing_direction = facing;
                }
                player.distance_covered += movement.distance_covered;
            }
        }
    }
}

fn apply_runner_defender_movement(
    defender: &mut RunnerPlayer,
    defender_index: usize,
    plan_signals: TeamPlanSignals,
    phase1_inputs: &RunnerDefenderPhase1Inputs,
    config: &RunnerRuntimeConfig,
) {
    let action = if defender.last_def_action.is_empty() {
        "hold_position"
    } else {
        defender.last_def_action.as_str()
    };
    let cached = phase1_inputs
        .inputs
        .get(defender_index)
        .zip(phase1_inputs.snapshots.get(defender_index))
        .filter(|(input, snapshot)| {
            input.index == defender_index
                && snapshot.pos == defender.pos
                && snapshot.target_pos == defender.target_pos
                && snapshot.tactical_anchor == defender.tactical_anchor
                && snapshot.velocity == defender.velocity
                && snapshot.speed_ability == defender.speed.round() as i32
                && snapshot.state_code == runner_player_state_code(defender.state.as_str())
                && snapshot.action == runner_static_defense_action(action)
        });
    if let Some((input, snapshot)) = cached {
        defender.pos = input.new_pos;
        defender.velocity = snapshot.next_velocity;
        if let Some(facing) = snapshot.facing_direction {
            defender.facing_direction = facing;
        }
        defender.distance_covered += snapshot.distance_covered;
        return;
    }

    let movement = crate::off_ball_defense::project_defense_action_motion(
        defender.pos,
        defender.target_pos,
        defender.tactical_anchor,
        action,
        runner_defense_movement_input(defender, plan_signals, config),
    );
    defender.pos = movement.pos;
    defender.velocity = movement.velocity;
    if let Some(facing) = movement.facing_direction {
        defender.facing_direction = facing;
    }
    defender.distance_covered += movement.distance_covered;
}

fn move_runner_player(
    player: &mut RunnerPlayer,
    tick: i32,
    plan_signals: TeamPlanSignals,
    config: &RunnerRuntimeConfig,
) {
    let movement_target = player_effective_movement_target(player, tick, plan_signals);
    let movement = player_move_tick(&PlayerMoveTickInput {
        pos: player.pos,
        target_pos: movement_target,
        velocity: player.velocity,
        speed_ability: player.speed.round() as i32,
        movement_intent: player.movement_intent.as_str(),
        state: player.state.as_str(),
        player_max_speed: config.player_max_speed,
        player_min_speed: config.player_min_speed,
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
    });
    player.pos = movement.pos;
    player.velocity = movement.velocity;
    if let Some(facing) = movement.facing_direction {
        player.facing_direction = facing;
    }
    player.distance_covered += movement.distance_covered;
}

fn move_contested_team(
    players: &mut [RunnerPlayer],
    opponents: &[RunnerPlayer],
    ball_pos: (f64, f64),
    attacking_right: bool,
    tick: i32,
    plan_signals: TeamPlanSignals,
    config: &RunnerRuntimeConfig,
    shape_arena: &mut RunnerTeamShapeArena,
) {
    apply_team_shape_targets(
        players,
        opponents,
        ball_pos,
        attacking_right,
        "contesting",
        plan_signals,
        "recover_shape",
        None,
        config,
        shape_arena,
    );
    refresh_team_tactical_beliefs(players, opponents, ball_pos, attacking_right, config);
    let mut target_inputs = [ContestedTargetPlayerInput {
        index: 0,
        pos: (0.0, 0.0),
        tactical_anchor: (0.0, 0.0),
        is_goalkeeper: false,
        is_stunned: false,
        speed: 0,
        iq: 0.0,
    }; RUNNER_TEAM_SIZE];
    let target_input_count = contested_target_players_into(players, &mut target_inputs);
    let mut target_outputs = [crate::ContestedTargetOutput {
        index: 0,
        target: (0.0, 0.0),
        intent_code: 0,
    }; RUNNER_TEAM_SIZE];
    let target_output_count = select_contested_targets_into(
        &ContestedTargetsInput {
            ball_pos,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            player_max_speed: config.player_max_speed,
            player_min_speed: config.player_min_speed,
            contested_race_radius: config.contested_race_radius,
            players: &target_inputs[..target_input_count],
        },
        &mut target_outputs,
    );
    for output in &target_outputs[..target_output_count] {
        if let Some(player) = players.get_mut(output.index) {
            if player.state == "stunned" {
                continue;
            }
            if player.position == "GK" {
                apply_goalkeeper_coverage_target(player, attacking_right, config);
            } else {
                player.target_pos = output.target;
                let requested_intent = if output.intent_code == 1 {
                    "contest"
                } else {
                    "recover_shape"
                };
                update_runner_text(&mut player.movement_intent, requested_intent);
            }
        }
    }
    for player in players.iter_mut() {
        if player.state == "stunned" {
            continue;
        }
        move_runner_player(player, tick, plan_signals, config);
    }
}

fn defender_phase1_inputs(
    defenders: &[RunnerPlayer],
    plan_signals: TeamPlanSignals,
    config: &RunnerRuntimeConfig,
) -> RunnerDefenderPhase1Inputs {
    assert!(
        defenders.len() <= RUNNER_TEAM_SIZE,
        "defender phase inputs expect eleven-player teams"
    );
    let mut inputs = [RUNNER_EMPTY_DEFENDER_ACTION; RUNNER_TEAM_SIZE];
    let mut snapshots = [RUNNER_EMPTY_DEFENDER_MOTION_SNAPSHOT; RUNNER_TEAM_SIZE];
    for (idx, defender) in defenders.iter().enumerate() {
        let action = if defender.state == "stunned" || defender.last_def_action.is_empty() {
            "hold_position"
        } else {
            defender.last_def_action.as_str()
        };
        let movement = crate::off_ball_defense::project_defense_action_motion(
            defender.pos,
            defender.target_pos,
            defender.tactical_anchor,
            action,
            runner_defense_movement_input(defender, plan_signals, config),
        );
        inputs[idx] = DefenderActionInput {
            index: idx,
            pos: defender.pos,
            new_pos: movement.pos,
            action: runner_static_defense_action(action),
            speed: defender.speed,
            defence: defender.defence,
            tackling: defender.tackling,
            is_goalkeeper: defender.position == "GK",
        };
        snapshots[idx] = RunnerDefenderMotionSnapshot {
            pos: defender.pos,
            target_pos: defender.target_pos,
            tactical_anchor: defender.tactical_anchor,
            velocity: defender.velocity,
            speed_ability: defender.speed.round() as i32,
            state_code: runner_player_state_code(defender.state.as_str()),
            action: runner_static_defense_action(action),
            next_velocity: movement.velocity,
            distance_covered: movement.distance_covered,
            facing_direction: movement.facing_direction,
        };
    }
    RunnerDefenderPhase1Inputs {
        inputs,
        snapshots,
        count: defenders.len(),
    }
}

fn shot_contest_defenders_into(
    inputs: &[DefenderActionInput],
    tackle_range: f64,
    output: &mut [ShotContestDefender; RUNNER_TEAM_SIZE],
) -> usize {
    assert!(
        inputs.len() <= RUNNER_TEAM_SIZE,
        "shot contest defenders expect eleven-player teams"
    );
    for (index, defender) in inputs.iter().enumerate() {
        let (engagement_weight, engagement_reach) =
            shot_contest_engagement(defender.action, tackle_range);
        output[index] = ShotContestDefender {
            index: defender.index,
            pos: defender.pos,
            projected_pos: defender.new_pos,
            speed: defender.speed,
            defence: defender.defence,
            intent: shot_contest_intent(defender.action),
            engagement_weight,
            engagement_reach,
            is_goalkeeper: defender.is_goalkeeper,
        };
    }
    inputs.len()
}

fn track_runner_pressures(
    tick: i32,
    defenders: &mut [RunnerPlayer],
    holder_pos: (f64, f64),
    holder_action: &str,
    defender_actions: &[DefenderActionInput],
    duel_detected: bool,
    interception_detected: bool,
    config: &RunnerRuntimeConfig,
) {
    let mut pressures = [crate::DefensivePressureOutput {
        defender_index: 0,
        successful: false,
    }; RUNNER_TEAM_SIZE];
    let pressure_count = track_defensive_pressures_into(
        &DefensivePressureInput {
            holder_pos,
            holder_action,
            defenders: defender_actions,
            press_radius: config.press_radius,
            duel_detected,
            interception_detected,
        },
        &mut pressures,
    );
    for pressure in &pressures[..pressure_count] {
        if let Some(defender) = defenders.get_mut(pressure.defender_index) {
            if tick - defender.last_pressure_tick < 3 {
                continue;
            }
            defender.last_pressure_tick = tick;
            defender.pressures += 1;
            if pressure.successful {
                defender.successful_pressures += 1;
            }
        }
    }
}

fn runner_player_name(players: &[RunnerPlayer], idx: usize) -> &str {
    players
        .get(idx)
        .map(|player| player.name.as_str())
        .unwrap_or("")
}

fn resolve_runner_duel(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    holder_idx: usize,
    holder_home: bool,
    defender: DefenderActionInput,
    context: RunnerDuelContext,
    contact: crate::DetectionResult,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    home_attacking_right: bool,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
) -> RunnerDuelResult {
    let defender_idx = defender.index;
    push_rng_trace(state, tick, "before_duel_resolve", rng);
    let (holder_pos, holder_dribbling) = if holder_home {
        home.get(holder_idx)
            .map(|player| (player.pos, player.dribbling))
            .unwrap_or((state.ball.position, 50.0))
    } else {
        away.get(holder_idx)
            .map(|player| (player.pos, player.dribbling))
            .unwrap_or((state.ball.position, 50.0))
    };
    let defender_tackling = defender.tackling;
    let defender_defence = defender.defence;
    let defender_action = defender.action;
    let attacker_uniform = rng.uniform(-12.0, 12.0);
    let defender_uniform = rng.uniform(-12.0, 12.0);
    let records_dribble = context == RunnerDuelContext::Carry;
    let event_tag = match context {
        RunnerDuelContext::Carry => "take_on",
        RunnerDuelContext::Hold | RunnerDuelContext::Reorient => "ball_protection",
        RunnerDuelContext::Pass => "pass_release",
    };
    let holder_action = match context {
        RunnerDuelContext::Carry => "carry",
        RunnerDuelContext::Hold => "hold",
        RunnerDuelContext::Reorient => "reorient",
        RunnerDuelContext::Pass => "pass",
    };
    let outcome_transition = crate::DuelOutcomeTransition::new(
        holder_dribbling,
        defender,
        holder_action,
        contact.contact_quality,
    );
    let margin = crate::duel_margin(&crate::DuelResolveInput {
        attacker_dribbling: holder_dribbling,
        defender_tackling,
        defender_defence,
        holder_action,
        defender_action,
        contact_quality: contact.contact_quality,
        attacker_uniform,
        defender_uniform,
    });
    let outcome = outcome_transition.sample(attacker_uniform, defender_uniform);
    let records_tackle_attempt = crate::records_tackle_attempt(defender_action);
    let (loose_x_roll, loose_y_roll) = if outcome == crate::DuelOutcome::LooseBall {
        (rng.random(), rng.random())
    } else {
        (0.5, 0.5)
    };
    push_rng_trace(state, tick, "after_duel_rolls", rng);
    let duel = duel_phase_plan(&DuelPhasePlanInput {
        holder_pos,
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
        attacker_dribbling: holder_dribbling,
        defender_tackling,
        defender_defence,
        holder_action,
        defender_action,
        contact_quality: contact.contact_quality,
        attacker_uniform,
        defender_uniform,
        loose_x_roll,
        loose_y_roll,
    });
    let successful_outcome = match context {
        RunnerDuelContext::Carry => "won",
        RunnerDuelContext::Hold | RunnerDuelContext::Reorient => "retained",
        RunnerDuelContext::Pass => "released",
    };
    let tackle_tags = |outcome| {
        if context == RunnerDuelContext::Pass {
            EventTags::from_slice(&["possession_won", "pass_release", outcome])
        } else {
            EventTags::one("possession_won")
        }
    };
    match outcome {
        crate::DuelOutcome::AttackerWins => {
            let attacker_identity = if holder_home {
                player_identity(home, holder_idx)
            } else {
                player_identity(away, holder_idx)
            };
            let defender_identity = if holder_home {
                player_identity(away, defender_idx)
            } else {
                player_identity(home, defender_idx)
            };
            if holder_home {
                if let Some(defender) = away.get_mut(defender_idx) {
                    if records_tackle_attempt {
                        defender.tackles_attempted += 1;
                    }
                    apply_stun_to_player(defender, config);
                }
                if let Some(holder) = home.get_mut(holder_idx) {
                    if records_dribble {
                        holder.dribbles_attempted += 1;
                        holder.dribbles_completed += 1;
                    }
                }
            } else {
                if let Some(defender) = home.get_mut(defender_idx) {
                    if records_tackle_attempt {
                        defender.tackles_attempted += 1;
                    }
                    apply_stun_to_player(defender, config);
                }
                if let Some(holder) = away.get_mut(holder_idx) {
                    if records_dribble {
                        holder.dribbles_attempted += 1;
                        holder.dribbles_completed += 1;
                    }
                }
            }
            state.ball.position = holder_pos;
            trace_entry!(
                state,
                json!({
                    "tick": tick,
                    "type": "event",
                    "event": "duel",
                    "outcome": "attacker_wins",
                    "winner": if holder_home {
                        runner_player_name(home, holder_idx)
                    } else {
                        runner_player_name(away, holder_idx)
                    },
                    "loser": if holder_home {
                        runner_player_name(away, defender_idx)
                    } else {
                        runner_player_name(home, defender_idx)
                    },
                    "rng": {
                        "attacker_uniform": attacker_uniform,
                        "defender_uniform": defender_uniform
                    },
                    "contact": {
                        "distance": contact.distance,
                        "probability": contact.contact_probability,
                        "quality": contact.contact_quality,
                        "defender_action": defender_action,
                        "margin": margin,
                        "attacker_dribbling": holder_dribbling,
                        "defender_tackling": defender_tackling,
                        "defender_defence": defender_defence
                    }
                })
            );
            record_match_event(
                state,
                config,
                MatchEventInput {
                    tick,
                    half,
                    possession_id: state.possession_id,
                    event_type: "duel",
                    team_home: holder_home,
                    player: attacker_identity,
                    target_player: defender_identity,
                    assist_player: serde_json::Value::Null,
                    outcome: successful_outcome,
                    xg: 0.0,
                    origin: Some(holder_pos),
                    target: Some(holder_pos),
                    tags: EventTags::one(event_tag),
                    score_before: None,
                },
            );
            RunnerDuelResult::ContinuePossession
        }
        crate::DuelOutcome::DefenderWins => {
            let attacker_identity = if holder_home {
                player_identity(home, holder_idx)
            } else {
                player_identity(away, holder_idx)
            };
            let defender_identity = if holder_home {
                player_identity(away, defender_idx)
            } else {
                player_identity(home, defender_idx)
            };
            let possession_id = state.possession_id;
            if holder_home {
                if let Some(defender) = away.get_mut(defender_idx) {
                    if records_tackle_attempt {
                        defender.tackles_attempted += 1;
                        defender.tackles_won += 1;
                    }
                }
                if let Some(holder) = home.get_mut(holder_idx) {
                    if records_dribble {
                        holder.dribbles_attempted += 1;
                    }
                    holder.dispossessed += 1;
                    holder.turnovers += 1;
                    holder.consecutive_carries = 0;
                }
                let defender_pos = away
                    .get(defender_idx)
                    .map(|player| player.pos)
                    .unwrap_or(holder_pos);
                give_ball_to_player(
                    state,
                    home,
                    away,
                    defender_idx,
                    false,
                    defender_pos,
                    None,
                    home_attacking_right,
                    config,
                );
            } else {
                if let Some(defender) = home.get_mut(defender_idx) {
                    if records_tackle_attempt {
                        defender.tackles_attempted += 1;
                        defender.tackles_won += 1;
                    }
                }
                if let Some(holder) = away.get_mut(holder_idx) {
                    if records_dribble {
                        holder.dribbles_attempted += 1;
                    }
                    holder.dispossessed += 1;
                    holder.turnovers += 1;
                    holder.consecutive_carries = 0;
                }
                let defender_pos = home
                    .get(defender_idx)
                    .map(|player| player.pos)
                    .unwrap_or(holder_pos);
                give_ball_to_player(
                    state,
                    home,
                    away,
                    defender_idx,
                    true,
                    defender_pos,
                    None,
                    home_attacking_right,
                    config,
                );
            }
            trace_entry!(
                state,
                json!({
                    "tick": tick,
                    "type": "event",
                    "event": if records_tackle_attempt { "tackle" } else { "duel" },
                    "outcome": "defender_wins",
                    "tackler": if holder_home {
                        runner_player_name(away, defender_idx)
                    } else {
                        runner_player_name(home, defender_idx)
                    },
                    "dispossessed": if holder_home {
                        runner_player_name(home, holder_idx)
                    } else {
                        runner_player_name(away, holder_idx)
                    },
                    "rng": {
                        "attacker_uniform": attacker_uniform,
                        "defender_uniform": defender_uniform
                    },
                    "contact": {
                        "distance": contact.distance,
                        "probability": contact.contact_probability,
                        "quality": contact.contact_quality,
                        "defender_action": defender_action,
                        "margin": margin,
                        "attacker_dribbling": holder_dribbling,
                        "defender_tackling": defender_tackling,
                        "defender_defence": defender_defence
                    }
                })
            );
            record_match_event(
                state,
                config,
                MatchEventInput {
                    tick,
                    half,
                    possession_id,
                    event_type: if records_tackle_attempt {
                        "tackle"
                    } else {
                        "duel"
                    },
                    team_home: !holder_home,
                    player: defender_identity,
                    target_player: attacker_identity,
                    assist_player: serde_json::Value::Null,
                    outcome: "won",
                    xg: 0.0,
                    origin: Some(holder_pos),
                    target: Some(holder_pos),
                    tags: if records_tackle_attempt {
                        tackle_tags("blocked")
                    } else if context == RunnerDuelContext::Pass {
                        EventTags::from_slice(&[
                            "possession_won",
                            "pass_release",
                            "pressure_turnover",
                        ])
                    } else {
                        EventTags::from_slice(&["possession_won", "pressure_turnover"])
                    },
                    score_before: None,
                },
            );
            RunnerDuelResult::PossessionChanged
        }
        crate::DuelOutcome::LooseBall => {
            let attacker_identity = if holder_home {
                player_identity(home, holder_idx)
            } else {
                player_identity(away, holder_idx)
            };
            let defender_identity = if holder_home {
                player_identity(away, defender_idx)
            } else {
                player_identity(home, defender_idx)
            };
            if holder_home {
                if let Some(defender) = away.get_mut(defender_idx) {
                    if records_tackle_attempt {
                        defender.tackles_attempted += 1;
                    }
                }
                if let Some(holder) = home.get_mut(holder_idx) {
                    if records_dribble {
                        holder.dribbles_attempted += 1;
                    }
                    holder.consecutive_carries = 0;
                    update_runner_text(&mut holder.state, "off_ball");
                }
            } else {
                if let Some(defender) = home.get_mut(defender_idx) {
                    if records_tackle_attempt {
                        defender.tackles_attempted += 1;
                    }
                }
                if let Some(holder) = away.get_mut(holder_idx) {
                    if records_dribble {
                        holder.dribbles_attempted += 1;
                    }
                    holder.consecutive_carries = 0;
                    update_runner_text(&mut holder.state, "off_ball");
                }
            }
            let challenge = RunnerContestChallenge {
                challenger_idx: defender_idx,
                challenger_team_home: !holder_home,
                holder_idx,
                holder_team_home: holder_home,
                records_tackle_attempt,
                possession_id: state.possession_id,
                origin: holder_pos,
                context,
            };
            set_contested_from_challenge_and_clear_goals(
                state,
                home,
                away,
                duel.loose_pos,
                (0.0, 0.0),
                challenge,
            );
            trace_entry!(
                state,
                json!({
                    "tick": tick,
                    "type": "event",
                    "event": "duel",
                    "outcome": "loose_ball",
                    "holder": if holder_home {
                        runner_player_name(home, holder_idx)
                    } else {
                        runner_player_name(away, holder_idx)
                    },
                    "defender": if holder_home {
                        runner_player_name(away, defender_idx)
                    } else {
                        runner_player_name(home, defender_idx)
                    },
                    "rng": {
                        "attacker_uniform": attacker_uniform,
                        "defender_uniform": defender_uniform
                    },
                    "contact": {
                        "distance": contact.distance,
                        "probability": contact.contact_probability,
                        "quality": contact.contact_quality,
                        "defender_action": defender_action,
                        "margin": margin,
                        "attacker_dribbling": holder_dribbling,
                        "defender_tackling": defender_tackling,
                        "defender_defence": defender_defence
                    }
                })
            );
            record_match_event(
                state,
                config,
                MatchEventInput {
                    tick,
                    half,
                    possession_id: state.possession_id,
                    event_type: "duel",
                    team_home: holder_home,
                    player: attacker_identity,
                    target_player: defender_identity,
                    assist_player: serde_json::Value::Null,
                    outcome: "loose",
                    xg: 0.0,
                    origin: Some(holder_pos),
                    target: Some(duel.loose_pos),
                    tags: EventTags::one("second_ball"),
                    score_before: None,
                },
            );
            RunnerDuelResult::BallContested
        }
    }
}

fn apply_restart_shape(
    reason: &str,
    restart_team_home: bool,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
    force: bool,
) -> (bool, (f64, f64)) {
    let restart_attacking_right = if restart_team_home {
        home_attacking_right
    } else {
        !home_attacking_right
    };
    let mut players = Vec::new();
    if restart_team_home {
        players.extend(restart_shape_players(
            home,
            0,
            true,
            home_attacking_right,
            restart_attacking_right,
        ));
        players.extend(restart_shape_players(
            away,
            1,
            false,
            !home_attacking_right,
            restart_attacking_right,
        ));
    } else {
        players.extend(restart_shape_players(
            away,
            1,
            true,
            !home_attacking_right,
            restart_attacking_right,
        ));
        players.extend(restart_shape_players(
            home,
            0,
            false,
            home_attacking_right,
            restart_attacking_right,
        ));
    }
    let shape = restart_shape_plan(&RestartShapePlanInput {
        reason,
        force,
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
        players: &players,
    });
    if !shape.has_shape {
        return (false, (0.0, 0.0));
    }
    for output in &shape.players {
        let team = if output.team_code == 0 {
            &mut *home
        } else {
            &mut *away
        };
        if let Some(player) = team.get_mut(output.index) {
            update_runner_text(&mut player.state, "off_ball");
            if force {
                player.target_pos = output.target;
                if player.movement_intent != "recover_shape" {
                    player.movement_intent.clear();
                    player.movement_intent.push_str("recover_shape");
                }
            } else {
                update_runner_movement_target(player, output.target, Some("recover_shape"));
            }
            if output.snap {
                player.pos = output.target;
                player.velocity = (0.0, 0.0);
            } else {
                let movement = player_move_tick(&PlayerMoveTickInput {
                    pos: player.pos,
                    target_pos: player.target_pos,
                    velocity: player.velocity,
                    speed_ability: player.speed.round() as i32,
                    movement_intent: player.movement_intent.as_str(),
                    state: player.state.as_str(),
                    player_max_speed: config.player_max_speed,
                    player_min_speed: config.player_min_speed,
                    pitch_length: config.pitch_length,
                    pitch_width: config.pitch_width,
                });
                player.pos = movement.pos;
                player.velocity = movement.velocity;
                if let Some(facing) = movement.facing_direction {
                    player.facing_direction = facing;
                }
                player.distance_covered += movement.distance_covered;
            }
        }
    }
    (true, shape.ball_pos)
}

fn restart_dead_ball(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
    rng: &mut RunnerRng,
) {
    let reason = state
        .dead_reason
        .clone()
        .unwrap_or_else(|| "kickoff".to_string());
    let restart_team_home = state.restart_team_home.unwrap_or(true);
    let restart_attacking_right = if restart_team_home {
        home_attacking_right
    } else {
        !home_attacking_right
    };
    let (has_shape, shape_ball_pos) = apply_restart_shape(
        reason.as_str(),
        restart_team_home,
        home,
        away,
        config,
        home_attacking_right,
        true,
    );
    if has_shape {
        state.ball.position = shape_ball_pos;
    }
    let restart_inputs = if restart_team_home {
        restart_players(home)
    } else {
        restart_players(away)
    };
    let corner_y_roll = if reason == "corner" {
        rng.random()
    } else {
        0.0
    };
    let restart = restart_play_plan(&RestartPlayPlanInput {
        reason: reason.as_str(),
        ball_pos: state.ball.position,
        restart_attacking_right,
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
        corner_y_roll,
        players: &restart_inputs,
    });
    if let Some(receiver_idx) = restart.receiver_index {
        let receiver_identity = if restart_team_home {
            player_identity(home, receiver_idx)
        } else {
            player_identity(away, receiver_idx)
        };
        let team = if restart_team_home {
            &mut *home
        } else {
            &mut *away
        };
        if let Some(receiver) = team.get_mut(receiver_idx) {
            if restart.set_receiver_pos {
                receiver.pos = restart.ball_pos;
                receiver.target_pos = restart.ball_pos;
            }
            give_ball_to_player(
                state,
                home,
                away,
                receiver_idx,
                restart_team_home,
                restart.ball_pos,
                None,
                home_attacking_right,
                config,
            );
            queue_restart_cut_frame(state, tick, half, home, away, config);
            state.dead_reason = None;
            state.restart_team_home = None;
            state.restart_ticks_remaining = 0;
            state.last_passer_team_home = None;
            state.last_passer_idx = -1;
            trace_entry!(
                state,
                json!({
                    "tick": tick,
                    "type": "event",
                    "event": "restart",
                    "reason": reason,
                    "team": if restart_team_home { "home" } else { "away" },
                    "receiver_idx": receiver_idx
                })
            );
            record_match_event(
                state,
                config,
                MatchEventInput {
                    tick,
                    half,
                    possession_id: state.possession_id,
                    event_type: "restart",
                    team_home: restart_team_home,
                    player: receiver_identity,
                    target_player: serde_json::Value::Null,
                    assist_player: serde_json::Value::Null,
                    outcome: reason.as_str(),
                    xg: 0.0,
                    origin: Some(restart.ball_pos),
                    target: Some(restart.ball_pos),
                    tags: EventTags::one("set_piece"),
                    score_before: None,
                },
            );
        }
    }
}

fn is_out_of_bounds(pos: (f64, f64), config: &RunnerRuntimeConfig) -> bool {
    pos.0 < 0.0 || pos.0 > config.pitch_length || pos.1 < 0.0 || pos.1 > config.pitch_width
}

fn flight_type_code(kind: RunnerFlightKind) -> u8 {
    match kind {
        RunnerFlightKind::Pass => 0,
        RunnerFlightKind::Clearance => 2,
        RunnerFlightKind::Shot => 3,
    }
}

fn handle_out_of_bounds_flight(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    flight: RunnerFlight,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
) {
    let boundary_crossing = crate::segment_pitch_boundary_crossing(
        flight.origin,
        flight.target,
        config.pitch_length,
        config.pitch_width,
    )
    .expect("an out-of-bounds flight must cross a pitch boundary");
    let (total_xg, logged_xg_sum) = if flight.kind == RunnerFlightKind::Shot {
        let shooter = if flight.passer_team_home {
            home.get(flight.passer_idx)
        } else {
            away.get(flight.passer_idx)
        };
        shooter
            .map(|player| (player.xg, shot_log_sum(player)))
            .unwrap_or((0.0, 0.0))
    } else {
        (0.0, 0.0)
    };
    let plan = out_of_bounds_plan(&OutOfBoundsPlanInput {
        boundary: boundary_crossing.kind,
        boundary_point: boundary_crossing.point,
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
        possession_team_home: flight.passer_team_home,
        flight_type_code: flight_type_code(flight.kind),
        origin: flight.origin,
        attacking_right: attacking_right_for(flight.passer_team_home, home_attacking_right),
        total_xg,
        logged_xg_sum,
        goal_kick_restart_ticks: config.goal_kick_restart_ticks,
        throw_in_restart_ticks: config.throw_in_restart_ticks,
    });
    if plan.has_shot_log {
        if flight.passer_team_home {
            if let Some(shooter) = home.get_mut(flight.passer_idx) {
                shooter.shot_log.push(shot_log_json(&plan.shot_log));
            }
        } else if let Some(shooter) = away.get_mut(flight.passer_idx) {
            shooter.shot_log.push(shot_log_json(&plan.shot_log));
        }
        let shooter_identity = if flight.passer_team_home {
            player_identity(home, flight.passer_idx)
        } else {
            player_identity(away, flight.passer_idx)
        };
        let keeper_identity = if flight.passer_team_home {
            player_identity(away, 0)
        } else {
            player_identity(home, 0)
        };
        record_match_event(
            state,
            config,
            MatchEventInput {
                tick,
                half,
                possession_id: flight.possession_id,
                event_type: "shot",
                team_home: flight.passer_team_home,
                player: shooter_identity,
                target_player: keeper_identity,
                assist_player: serde_json::Value::Null,
                outcome: "off_target",
                xg: flight.xg,
                origin: Some(flight.origin),
                target: Some(flight.target),
                tags: shot_event_tags(&flight, plan.shot_log.in_box, "off_target"),
                score_before: None,
            },
        );
    } else {
        let passer_identity = if flight.passer_team_home {
            player_identity(home, flight.passer_idx)
        } else {
            player_identity(away, flight.passer_idx)
        };
        let event_type = if flight.kind == RunnerFlightKind::Clearance {
            "clearance"
        } else {
            "pass"
        };
        let mut tags = if flight.kind == RunnerFlightKind::Pass {
            pass_event_tags(&flight, flight.target, config, home_attacking_right)
        } else {
            EventTags::from_slice(&["long", "space"])
        };
        tags.push(if plan.reason == "goal_kick" {
            "goal_kick"
        } else {
            "throw_in"
        });
        record_match_event(
            state,
            config,
            MatchEventInput {
                tick,
                half,
                possession_id: flight.possession_id,
                event_type,
                team_home: flight.passer_team_home,
                player: passer_identity,
                target_player: serde_json::Value::Null,
                assist_player: serde_json::Value::Null,
                outcome: "out_of_play",
                xg: 0.0,
                origin: Some(flight.origin),
                target: Some(flight.target),
                tags,
                score_before: None,
            },
        );
    }
    set_dead_ball_and_clear_goals(
        state,
        home,
        away,
        plan.reason.as_str(),
        plan.restart_team_home,
        plan.restart_ticks,
        boundary_crossing.point,
    );
    let terminal_ball_pos = state.ball.position;
    queue_replay_flight_terminal_frame(
        state,
        tick,
        half,
        home,
        away,
        config,
        &flight,
        terminal_ball_pos,
        boundary_crossing.point,
        RunnerReplayFlightEnd::OutOfPlay,
        None,
        None,
        None,
        None,
    );
    trace_entry!(
        state,
        json!({
            "tick": tick,
            "type": "event",
            "event": "out_of_bounds",
            "source": "flight",
            "boundary": match boundary_crossing.kind {
                crate::PitchBoundaryKind::GoalLine => "goal_line",
                crate::PitchBoundaryKind::TouchLine => "touch_line",
            },
            "crossing": [
                round_one(boundary_crossing.point.0),
                round_one(boundary_crossing.point.1)
            ],
            "reason": plan.reason,
            "restart_team": if plan.restart_team_home { "home" } else { "away" },
            "restart_ticks": plan.restart_ticks
        })
    );
}

fn flight_interceptor_index(flight: &RunnerFlight) -> Option<usize> {
    let Some(arrival) = flight.arrival_plan.as_ref() else {
        return None;
    };
    (arrival.outcome_code == 1 && arrival.contact_tick < flight.ticks_total)
        .then_some(arrival.opponent_index)
        .flatten()
}

fn flight_interception_due(flight: &RunnerFlight) -> bool {
    flight.arrival_plan.as_ref().is_some_and(|arrival| {
        arrival.outcome_code == 1
            && arrival.contact_tick < flight.ticks_total
            && flight.ticks_elapsed >= arrival.contact_tick
    })
}

#[allow(clippy::too_many_arguments)]
fn settle_pass_interception_at_contact(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    flight: RunnerFlight,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
) {
    let Some(arrival) = flight.arrival_plan.as_ref() else {
        return;
    };
    let Some(opponent_idx) = arrival.opponent_index else {
        return;
    };
    let contact_pos = arrival.contact_pos;
    let passer_identity = if flight.passer_team_home {
        player_identity(home, flight.passer_idx)
    } else {
        player_identity(away, flight.passer_idx)
    };
    let passer_team = if flight.passer_team_home {
        &mut *home
    } else {
        &mut *away
    };
    if let Some(passer) = passer_team.get_mut(flight.passer_idx) {
        passer.turnovers += 1;
    }
    let winner_name = {
        let defending_team = if flight.passer_team_home {
            &mut *away
        } else {
            &mut *home
        };
        if let Some(winner) = defending_team.get_mut(opponent_idx) {
            winner.interceptions += 1;
            winner.name.clone()
        } else {
            String::new()
        }
    };
    let interceptor_identity = if flight.passer_team_home {
        player_identity(away, opponent_idx)
    } else {
        player_identity(home, opponent_idx)
    };
    give_ball_to_player(
        state,
        home,
        away,
        opponent_idx,
        !flight.passer_team_home,
        contact_pos,
        None,
        home_attacking_right,
        config,
    );
    let winner_pos = state.ball.position;
    let holder_idx = state.ball.holder_idx;
    let holder_team = state
        .ball
        .holder_team_home
        .map(|team_home| if team_home { "home" } else { "away" });
    queue_replay_flight_terminal_frame(
        state,
        tick,
        half,
        home,
        away,
        config,
        &flight,
        winner_pos,
        winner_pos,
        RunnerReplayFlightEnd::Intercepted,
        None,
        None,
        holder_idx,
        holder_team,
    );
    trace_entry!(
        state,
        json!({
            "tick": tick,
            "type": "event",
            "event": "interception",
            "team": if flight.passer_team_home { "away" } else { "home" },
            "player": winner_name,
            "contact": [round_one(contact_pos.0), round_one(contact_pos.1)],
            "pos": [round_one(winner_pos.0), round_one(winner_pos.1)],
            "retention_probability": flight.retention_probability,
            "technical_probability": flight.technical_probability,
            "technical_roll": flight.technical_roll,
            "delivery_miss": flight.delivery_miss,
            "receiver_control": arrival.receiver_control,
            "opponent_control": arrival.opponent_control,
            "loose_control": arrival.loose_control
        })
    );
    let mut tags = pass_execution_tags(&flight, winner_pos, config, home_attacking_right);
    tags.push("arrival_interception");
    tags.push("pass_cut_out");
    record_match_event(
        state,
        config,
        MatchEventInput {
            tick,
            half,
            possession_id: flight.possession_id,
            event_type: "interception",
            team_home: !flight.passer_team_home,
            player: interceptor_identity,
            target_player: passer_identity,
            assist_player: serde_json::Value::Null,
            outcome: "won",
            xg: 0.0,
            origin: Some(flight.origin),
            target: Some(winner_pos),
            tags,
            score_before: None,
        },
    );
}

fn move_flight_players(
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    flight: RunnerFlight,
    state: &mut RunnerMatchState,
    tick: i32,
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
    rng: &mut RunnerRng,
) {
    let target_pos = flight.target;
    let race_radius = config.contested_race_radius;
    let interceptor_idx = flight_interceptor_index(&flight);
    let interception_target = flight
        .arrival_plan
        .as_ref()
        .map(|arrival| arrival.contact_pos)
        .unwrap_or(target_pos);
    if flight.passer_team_home {
        apply_team_shape_targets(
            home,
            away,
            target_pos,
            home_attacking_right,
            phase_name(state.home_phase_code),
            state.home_plan_signals,
            "recover_shape",
            None,
            config,
            &mut state.team_shape_arena,
        );
        apply_team_shape_targets(
            away,
            home,
            target_pos,
            !home_attacking_right,
            phase_name(state.away_phase_code),
            state.away_plan_signals,
            "defend_shape",
            None,
            config,
            &mut state.team_shape_arena,
        );
        refresh_team_tactical_beliefs(
            home,
            away,
            state.ball.position,
            home_attacking_right,
            config,
        );
        refresh_team_tactical_beliefs(
            away,
            home,
            state.ball.position,
            !home_attacking_right,
            config,
        );
        let defense_active =
            runner_flight_defense_active_indices(away, target_pos, race_radius, interceptor_idx);
        if defense_active[..away.len()].iter().any(|active| *active) {
            let (_, _, _) = apply_off_ball_defense_choices(
                away,
                home,
                target_pos,
                !home_attacking_right,
                None,
                0,
                0,
                0.0,
                state.away_plan_signals,
                Some(&defense_active[..away.len()]),
                config,
                rng,
                Some(&mut state.fixed_defense_arena),
                &mut state.trace_decisions,
                tick,
                false,
                false,
            );
        }
        for idx in 0..home.len() {
            if home[idx].state == "stunned" {
                continue;
            }
            if flight.intended_receiver_idx == Some(idx) {
                move_runner_player_to_local_task(&mut home[idx], target_pos, "attack_run", config);
                continue;
            }
            if home[idx].position == "GK" {
                apply_goalkeeper_coverage_target(&mut home[idx], home_attacking_right, config);
                move_runner_player(&mut home[idx], tick, state.home_plan_signals, config);
                continue;
            }
            let dist_to_target = distance(home[idx].pos, target_pos);
            if idx != flight.passer_idx && dist_to_target < race_radius * 1.35 {
                let active = runner_single_active_indices(idx, home.len());
                let _ = apply_off_ball_attack_choices(
                    home,
                    state,
                    tick,
                    true,
                    home_attacking_right,
                    None,
                    Some(&active[..home.len()]),
                    config,
                    rng,
                );
            } else {
                let support_target = pitch_clamp(
                    (
                        home[idx].tactical_anchor.0 * 0.86 + target_pos.0 * 0.14,
                        home[idx].tactical_anchor.1 * 0.88 + target_pos.1 * 0.12,
                    ),
                    config.pitch_length,
                    config.pitch_width,
                );
                update_runner_movement_target(
                    &mut home[idx],
                    support_target,
                    Some("recover_shape"),
                );
            }
            move_runner_player(&mut home[idx], tick, state.home_plan_signals, config);
        }
        for idx in 0..away.len() {
            if away[idx].state == "stunned" {
                continue;
            }
            if interceptor_idx == Some(idx) {
                move_runner_player_to_local_task(
                    &mut away[idx],
                    interception_target,
                    "contest",
                    config,
                );
                continue;
            }
            if away[idx].position == "GK" {
                apply_goalkeeper_coverage_target(&mut away[idx], !home_attacking_right, config);
                move_runner_player(&mut away[idx], tick, state.away_plan_signals, config);
                continue;
            }
            if !defense_active[idx] {
                let support_target = pitch_clamp(
                    (
                        away[idx].tactical_anchor.0 * 0.88 + target_pos.0 * 0.12,
                        away[idx].tactical_anchor.1 * 0.90 + target_pos.1 * 0.10,
                    ),
                    config.pitch_length,
                    config.pitch_width,
                );
                update_runner_movement_target(&mut away[idx], support_target, Some("defend_shape"));
            }
            move_runner_player(&mut away[idx], tick, state.away_plan_signals, config);
        }
    } else {
        apply_team_shape_targets(
            away,
            home,
            target_pos,
            !home_attacking_right,
            phase_name(state.away_phase_code),
            state.away_plan_signals,
            "recover_shape",
            None,
            config,
            &mut state.team_shape_arena,
        );
        apply_team_shape_targets(
            home,
            away,
            target_pos,
            home_attacking_right,
            phase_name(state.home_phase_code),
            state.home_plan_signals,
            "defend_shape",
            None,
            config,
            &mut state.team_shape_arena,
        );
        refresh_team_tactical_beliefs(
            home,
            away,
            state.ball.position,
            home_attacking_right,
            config,
        );
        refresh_team_tactical_beliefs(
            away,
            home,
            state.ball.position,
            !home_attacking_right,
            config,
        );
        let defense_active =
            runner_flight_defense_active_indices(home, target_pos, race_radius, interceptor_idx);
        if defense_active[..home.len()].iter().any(|active| *active) {
            let (_, _, _) = apply_off_ball_defense_choices(
                home,
                away,
                target_pos,
                home_attacking_right,
                None,
                0,
                0,
                0.0,
                state.home_plan_signals,
                Some(&defense_active[..home.len()]),
                config,
                rng,
                Some(&mut state.fixed_defense_arena),
                &mut state.trace_decisions,
                tick,
                true,
                false,
            );
        }
        for idx in 0..away.len() {
            if away[idx].state == "stunned" {
                continue;
            }
            if flight.intended_receiver_idx == Some(idx) {
                move_runner_player_to_local_task(&mut away[idx], target_pos, "attack_run", config);
                continue;
            }
            if away[idx].position == "GK" {
                apply_goalkeeper_coverage_target(&mut away[idx], !home_attacking_right, config);
                move_runner_player(&mut away[idx], tick, state.away_plan_signals, config);
                continue;
            }
            let dist_to_target = distance(away[idx].pos, target_pos);
            if idx != flight.passer_idx && dist_to_target < race_radius * 1.35 {
                let active = runner_single_active_indices(idx, away.len());
                let _ = apply_off_ball_attack_choices(
                    away,
                    state,
                    tick,
                    false,
                    !home_attacking_right,
                    None,
                    Some(&active[..away.len()]),
                    config,
                    rng,
                );
            } else {
                let support_target = pitch_clamp(
                    (
                        away[idx].tactical_anchor.0 * 0.86 + target_pos.0 * 0.14,
                        away[idx].tactical_anchor.1 * 0.88 + target_pos.1 * 0.12,
                    ),
                    config.pitch_length,
                    config.pitch_width,
                );
                update_runner_movement_target(
                    &mut away[idx],
                    support_target,
                    Some("recover_shape"),
                );
            }
            move_runner_player(&mut away[idx], tick, state.away_plan_signals, config);
        }
        for idx in 0..home.len() {
            if home[idx].state == "stunned" {
                continue;
            }
            if interceptor_idx == Some(idx) {
                move_runner_player_to_local_task(
                    &mut home[idx],
                    interception_target,
                    "contest",
                    config,
                );
                continue;
            }
            if home[idx].position == "GK" {
                apply_goalkeeper_coverage_target(&mut home[idx], home_attacking_right, config);
                move_runner_player(&mut home[idx], tick, state.home_plan_signals, config);
                continue;
            }
            if !defense_active[idx] {
                let support_target = pitch_clamp(
                    (
                        home[idx].tactical_anchor.0 * 0.88 + target_pos.0 * 0.12,
                        home[idx].tactical_anchor.1 * 0.90 + target_pos.1 * 0.10,
                    ),
                    config.pitch_length,
                    config.pitch_width,
                );
                update_runner_movement_target(&mut home[idx], support_target, Some("defend_shape"));
            }
            move_runner_player(&mut home[idx], tick, state.home_plan_signals, config);
        }
    }
}

fn apply_kickoff(
    restart_side_home: bool,
    home_attacking_right: bool,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    config: &RunnerRuntimeConfig,
    state: Option<&mut RunnerMatchState>,
) -> (usize, &'static str, (f64, f64)) {
    let pitch_length = config.pitch_length;
    let pitch_width = config.pitch_width;
    let center = (pitch_length / 2.0, pitch_width / 2.0);
    let mut inputs = Vec::with_capacity(home.len() + away.len());
    for (idx, player) in home.iter().enumerate() {
        inputs.push(KickoffPlayerInput {
            index: idx,
            team_is_restart: restart_side_home,
            attacking_right: home_attacking_right,
            base_pos: player.base_pos,
            current_pos: player.pos,
            is_goalkeeper: player.position == "GK",
            position: player.position.as_str(),
        });
    }
    for (idx, player) in away.iter().enumerate() {
        inputs.push(KickoffPlayerInput {
            index: idx + 1000,
            team_is_restart: !restart_side_home,
            attacking_right: !home_attacking_right,
            base_pos: player.base_pos,
            current_pos: player.pos,
            is_goalkeeper: player.position == "GK",
            position: player.position.as_str(),
        });
    }
    let shape = kickoff_shape_targets(&KickoffShapeInput {
        pitch_length,
        pitch_width,
        players: &inputs,
    });
    for (idx, target) in shape.targets {
        if idx >= 1000 {
            if let Some(player) = away.get_mut(idx - 1000) {
                player.pos = target;
                player.target_pos = target;
                player.tactical_anchor = target;
            }
        } else if let Some(player) = home.get_mut(idx) {
            player.pos = target;
            player.target_pos = target;
            player.tactical_anchor = target;
        }
    }
    let kicker_external = shape
        .kicker_index
        .unwrap_or(if restart_side_home { 10 } else { 1010 });
    let (idx, team_home, team_name) = if kicker_external >= 1000 {
        (kicker_external - 1000, false, "away")
    } else {
        (kicker_external, true, "home")
    };
    if team_home {
        if let Some(player) = home.get_mut(idx) {
            player.pos = center;
            player.target_pos = center;
            player.tactical_anchor = center;
        }
    } else if let Some(player) = away.get_mut(idx) {
        player.pos = center;
        player.target_pos = center;
        player.tactical_anchor = center;
    }
    if let Some(state) = state {
        give_ball_to_player(
            state,
            home,
            away,
            idx,
            team_home,
            center,
            None,
            home_attacking_right,
            config,
        );
    } else if team_home {
        if let Some(player) = home.get_mut(idx) {
            update_runner_text(&mut player.state, "on_ball");
            player.hold_ticks = 0;
            player.possession_ticks = 0;
            player.consecutive_carries = 0;
            player.last_receive_origin = player.pos;
            clear_player_goal(player);
        }
    } else if let Some(player) = away.get_mut(idx) {
        update_runner_text(&mut player.state, "on_ball");
        player.hold_ticks = 0;
        player.possession_ticks = 0;
        player.consecutive_carries = 0;
        player.last_receive_origin = player.pos;
        clear_player_goal(player);
    }
    (idx, team_name, center)
}

fn record_half_frames(
    frames: &mut Vec<RunnerReplayEntry>,
    state: &mut RunnerMatchState,
    start_tick: i32,
    end_tick: i32,
    half: i32,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
    rng: &mut RunnerRng,
) {
    let interval = config.frame_interval.max(1);
    let mut held_tick_arena = RunnerHeldTickArena::new();
    for tick in start_tick..end_tick {
        tick_match(
            state,
            tick,
            half,
            home,
            away,
            config,
            home_attacking_right,
            &mut held_tick_arena,
            rng,
        );
        let has_event_frame = !state.pending_replay_frames.is_empty();
        let pending_frames = std::mem::take(&mut state.pending_replay_frames);
        reconcile_replay_flight_terminal_frames(frames, &pending_frames);
        frames.extend(pending_frames.into_iter().map(RunnerReplayEntry::Frame));
        let sample_shot_flight = state
            .ball
            .flight
            .as_ref()
            .is_some_and(|flight| flight.kind == RunnerFlightKind::Shot);
        if ((tick - start_tick) % interval == 0 || sample_shot_flight) && !has_event_frame {
            let ball_flight = replay_ball_flight(state.ball.flight.as_ref(), config);
            frames.push(RunnerReplayEntry::Frame(frame(
                tick,
                config.tick_duration,
                half,
                home,
                away,
                state.ball.position,
                state.ball.holder_idx,
                state
                    .ball
                    .holder_team_home
                    .map(|home| if home { "home" } else { "away" }),
                (state.home_score, state.away_score),
                None,
                ball_flight,
                None,
                None,
            )));
        }
        if tick % 10 == 0 {
            sample_player_positions(home);
            sample_player_positions(away);
        }
    }
}

fn possession_pct(home_ticks: i32, total_ticks: i32) -> f64 {
    if total_ticks <= 0 {
        50.0
    } else {
        round_one(home_ticks as f64 / total_ticks as f64 * 100.0)
    }
}

fn match_clock_payload(clock: MatchClock) -> serde_json::Value {
    let snapshot = clock.snapshot();
    json!({
        "match_seconds": round_one(snapshot.match_seconds),
        "active_play_seconds": round_one(snapshot.active_play_seconds),
        "dead_ball_seconds": round_one(snapshot.dead_ball_seconds),
        "active_play_ratio": round_two(snapshot.active_play_ratio),
        "match_ticks": snapshot.match_ticks,
        "active_play_ticks": snapshot.active_play_ticks,
        "dead_ball_ticks": snapshot.dead_ball_ticks,
    })
}

fn choose_held_action(
    holder_idx: usize,
    holder: &RunnerPlayer,
    goal_state: &mut RunnerHeldGoalState,
    holder_home: bool,
    teammates: &[RunnerPlayer],
    opponents: &[RunnerPlayer],
    defender_responses: &[DefenderActionInput],
    contest_defenders: &[ShotContestDefender],
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
    forced_action_override: Option<&str>,
    state: &mut RunnerMatchState,
    tick: i32,
    rng: &mut RunnerRng,
) -> RunnerHeldAction {
    let attacking_right = attacking_right_for(holder_home, home_attacking_right);
    if let Some(action) = forced_action_override.or(config.runner_forced_action.as_deref()) {
        match action {
            "carry" => {
                return RunnerHeldAction::Carry {
                    target: carry_target(holder, attacking_right, config),
                }
            }
            "pass" => {
                if let Some(receiver_idx) =
                    choose_pass_receiver(holder_idx, holder, teammates, attacking_right)
                {
                    return RunnerHeldAction::Pass {
                        receiver_idx,
                        target: config
                            .runner_forced_pass_target
                            .unwrap_or(teammates[receiver_idx].pos),
                        is_long: false,
                        lane_risk: 0.0,
                        retention_probability: 1.0,
                        technical_probability: 1.0,
                    };
                }
            }
            "clear" => {
                return RunnerHeldAction::Clear {
                    target: config
                        .runner_forced_clear_target
                        .unwrap_or_else(|| clear_target(holder, attacking_right, config)),
                }
            }
            "hold" => {
                return RunnerHeldAction::Hold {
                    opportunity_target: None,
                }
            }
            "shot" => {
                return build_shot_candidate(
                    holder_idx,
                    holder,
                    holder_home,
                    state.ball.control,
                    teammates,
                    opponents,
                    contest_defenders,
                    runner_state_value(
                        holder_idx,
                        holder,
                        holder_home,
                        state.ball.control,
                        teammates,
                        opponents,
                        contest_defenders,
                        attacking_right,
                        tick,
                        &state.shot_quality_cache,
                        config,
                    ),
                    attacking_right,
                    tick,
                    &state.shot_quality_cache,
                    config,
                )
                .action;
            }
            _ => {}
        }
    }
    let selected = choose_default_held_action(
        holder_idx,
        holder,
        goal_state,
        teammates,
        opponents,
        defender_responses,
        contest_defenders,
        holder_home,
        config,
        home_attacking_right,
        state,
        tick,
        rng,
    );
    selected
}

fn execute_runner_control_action(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    holder_idx: usize,
    holder_home: bool,
    action_is_continuation: bool,
    action_name: &'static str,
    transition: Option<crate::execution_transition::ControlActionTransition>,
    opportunity_target: Option<(f64, f64)>,
    reorient_target: Option<(f64, f64)>,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    opponents: &[ExecutionOpponent],
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
    rng: &mut RunnerRng,
) {
    let origin = if holder_home {
        home.get(holder_idx)
    } else {
        away.get(holder_idx)
    }
    .map(|holder| holder.pos)
    .unwrap_or(state.ball.position);
    let (hold, control_heading, hold_ticks) = {
        let holder = if holder_home {
            home.get_mut(holder_idx)
        } else {
            away.get_mut(holder_idx)
        };
        let Some(holder) = holder else { return };
        holder.hold_ticks += 1;
        if action_name == "hold" && !action_is_continuation {
            holder.holds += 1;
        }
        holder.consecutive_carries = 0;
        let hold_error_roll = rng.random();
        let loose_rolls = preview_randoms::<2>(rng);
        let hold = hold_phase_plan(&HoldPhasePlanInput {
            transition,
            holder_pos: holder.pos,
            velocity: holder.velocity,
            speed_ability: holder.speed.round() as i32,
            dribbling: holder.dribbling,
            attacking_right,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            player_max_speed: config.player_max_speed,
            player_min_speed: config.player_min_speed,
            carry_error_divisor: config.carry_error_divisor,
            opponents,
            opportunity_target,
            error_roll: hold_error_roll,
            loose_x_roll: loose_rolls[0],
            loose_y_roll: loose_rolls[1],
        });
        holder.distance_covered += hold.distance_covered;
        holder.pos = hold.new_pos;
        holder.velocity = hold.velocity;
        let control_heading = hold.facing_direction.unwrap_or(holder.facing_direction);
        holder.facing_direction = control_heading;
        if hold.is_error {
            holder.turnovers += 1;
            update_runner_text(&mut holder.state, "off_ball");
        }
        (hold, control_heading, holder.hold_ticks)
    };
    if hold.is_error {
        advance_randoms(rng, 2);
        set_contested_and_clear_goals(state, home, away, hold.loose_pos, (0.0, 0.0));
        record_technical_control_error(
            state,
            config,
            tick,
            half,
            state.possession_id,
            action_name,
            holder_home,
            if holder_home {
                player_identity(home, holder_idx)
            } else {
                player_identity(away, holder_idx)
            },
            origin,
            hold.loose_pos,
        );
        trace_entry!(
            state,
            json!({
                "tick": tick,
                "type": "event",
                "event": "error",
                "error_type": if action_name == "reorient" { "control_reorient" } else { "shield" },
                "player": if holder_home {
                    runner_player_name(home, holder_idx)
                } else {
                    runner_player_name(away, holder_idx)
                }
            })
        );
        return;
    }
    state.ball.position = hold.new_pos;
    trace_entry!(
        state,
        json!({
            "tick": tick,
            "type": "action",
            "team": if holder_home { "home" } else { "away" },
            "player": if holder_home {
                runner_player_name(home, holder_idx)
            } else {
                runner_player_name(away, holder_idx)
            },
            "action": action_name,
            "phase": if action_is_continuation { "continue" } else { "start" },
            "hold_ticks": hold_ticks,
            "pos": [round_one(hold.new_pos.0), round_one(hold.new_pos.1)],
            "opportunity_target": opportunity_target.map(|target| json!([target.0, target.1])).unwrap_or(serde_json::Value::Null),
            "facing_target": reorient_target.map(|target| json!([target.0, target.1])).unwrap_or(serde_json::Value::Null),
            "pressure": hold.trace_pressure,
            "nearest_def": hold.trace_nearest_dist.map(|value| json!(value)).unwrap_or(serde_json::Value::Null)
        })
    );
    let (controlling_players, defending_players) = if holder_home {
        (&*home, &*away)
    } else {
        (&*away, &*home)
    };
    state.ball.control = runner_live_control_transition(
        state.ball.control,
        holder_idx,
        hold.new_pos,
        controlling_players,
        defending_players,
        attacking_right,
        control_heading,
        1.0,
        hold.pressure.clamp(0.0, 1.0),
        1,
        hold.distance_covered,
        reorient_target.map(|target| angle_between_points(hold.new_pos, target)),
        config.pitch_length,
        config.pitch_width,
    );
    if let Some(holder) = if holder_home {
        home.get_mut(holder_idx)
    } else {
        away.get_mut(holder_idx)
    } {
        holder.facing_direction = state.ball.control.facing_direction;
    }
}

fn tick_match(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
    held_tick_arena: &mut RunnerHeldTickArena,
    rng: &mut RunnerRng,
) {
    tick_match_phase(
        state,
        tick,
        half,
        home,
        away,
        config,
        home_attacking_right,
        held_tick_arena,
        rng,
        false,
    );
}

fn tick_match_phase(
    state: &mut RunnerMatchState,
    tick: i32,
    half: i32,
    home: &mut [RunnerPlayer],
    away: &mut [RunnerPlayer],
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
    held_tick_arena: &mut RunnerHeldTickArena,
    rng: &mut RunnerRng,
    receipt_follow_up: bool,
) {
    let state_before = state.ball.state;
    if !receipt_follow_up && config.team_communication_enabled {
        state.team_communication.deliver(tick);
    }
    let clock_phase = if state_before == RunnerBallState::Dead {
        MatchClockPhase::DeadBall
    } else {
        MatchClockPhase::ActivePlay
    };
    if !receipt_follow_up {
        state.match_clock.advance(clock_phase, config.tick_duration);
        push_rng_trace(state, tick, "tick_start", rng);
    }
    if !receipt_follow_up
        && matches!(
            state.ball.state,
            RunnerBallState::Held | RunnerBallState::Contested
        )
    {
        update_team_phases(state, config);
        update_team_plans(state, home, away, home_attacking_right, config);
    }
    let mut held_attack_choices = 0;
    let mut held_defense_choices = 0;
    match state.ball.state {
        RunnerBallState::Held => 'held_phase: {
            if let (Some(holder_idx), Some(holder_home)) =
                (state.ball.holder_idx, state.ball.holder_team_home)
            {
                if !receipt_follow_up {
                    if holder_home {
                        if let Some(holder) = home.get_mut(holder_idx) {
                            holder.possession_ticks += 1;
                        }
                    } else if let Some(holder) = away.get_mut(holder_idx) {
                        holder.possession_ticks += 1;
                    }
                }
                let defender_phase1_inputs = if receipt_follow_up {
                    let defenders = if holder_home { &*away } else { &*home };
                    let plan_signals = if holder_home {
                        state.away_plan_signals
                    } else {
                        state.home_plan_signals
                    };
                    defender_phase1_inputs(defenders, plan_signals, config)
                } else {
                    push_rng_trace(state, tick, "before_attack_targets", rng);
                    let (attack_choices, _) = update_held_tick_targets(
                        home,
                        away,
                        state,
                        config,
                        home_attacking_right,
                        tick,
                        rng,
                    );
                    push_rng_trace(state, tick, "after_attack_targets", rng);
                    held_attack_choices = attack_choices;
                    push_rng_trace(state, tick, "before_defense_targets", rng);
                    let (defense_choices, inputs) = update_held_tick_defense_targets(
                        home,
                        away,
                        state,
                        config,
                        home_attacking_right,
                        tick,
                        rng,
                    );
                    push_rng_trace(state, tick, "after_defense_targets", rng);
                    held_defense_choices = defense_choices;
                    inputs
                };
                let contest_defender_count = shot_contest_defenders_into(
                    &defender_phase1_inputs,
                    config.tackle_range,
                    &mut held_tick_arena.contest_defenders,
                );
                let contest_defenders =
                    &held_tick_arena.contest_defenders[..contest_defender_count];
                let holder = if holder_home {
                    home.get(holder_idx)
                } else {
                    away.get(holder_idx)
                };
                if let Some(holder) = holder {
                    let (teammates, opponents_snapshot) = if holder_home {
                        (&*home, &*away)
                    } else {
                        (&*away, &*home)
                    };
                    let opponent_count = execution_opponents_into(
                        opponents_snapshot,
                        &mut held_tick_arena.execution_opponents,
                    );
                    let opponents = &held_tick_arena.execution_opponents[..opponent_count];
                    let attacking_right = attacking_right_for(holder_home, home_attacking_right);
                    let holder_pos = holder.pos;
                    let commitment_interrupted = interrupt_action_commitment_for_visible_release(
                        state,
                        holder_idx,
                        holder,
                        holder_home,
                        teammates,
                        opponents_snapshot,
                        defender_phase1_inputs.as_slice(),
                        contest_defenders,
                        home_attacking_right,
                        tick,
                        config,
                    );
                    let continuing_action = if commitment_interrupted {
                        None
                    } else {
                        continuing_held_action(state, holder_pos)
                    };
                    let action_is_continuation = continuing_action.is_some();
                    let held_action = if let Some(action) = continuing_action {
                        action
                    } else {
                        let previous_tactical_task = holder.tactical_task;
                        let forced_action_override = config
                            .runner_forced_actions
                            .get(state.held_action_cursor)
                            .map(|value| value.as_str())
                            .filter(|value| !value.is_empty() && *value != "-");
                        let action_is_forced = forced_action_override.is_some()
                            || config.runner_forced_action.is_some();
                        state.held_action_cursor += 1;
                        push_rng_trace(state, tick, "before_holder_choice", rng);
                        let mut decision_goal_state = RunnerHeldGoalState::from_player(holder);
                        let action = choose_held_action(
                            holder_idx,
                            holder,
                            &mut decision_goal_state,
                            holder_home,
                            teammates,
                            opponents_snapshot,
                            defender_phase1_inputs.as_slice(),
                            contest_defenders,
                            config,
                            home_attacking_right,
                            forced_action_override,
                            state,
                            tick,
                            rng,
                        );
                        push_rng_trace(state, tick, "after_holder_choice", rng);
                        if !action_is_forced {
                            let plan_signals = if holder_home {
                                state.home_plan_signals
                            } else {
                                state.away_plan_signals
                            };
                            let opportunity = match action {
                                RunnerHeldAction::Hold { .. } => (plan_signals.recycle_bias
                                    * (0.55 + 0.45 * plan_signals.switch_bias))
                                    .clamp(0.0, 1.0),
                                _ => 0.0,
                            };
                            start_action_commitment(
                                state,
                                action,
                                runner_selected_commitment_candidate(
                                    &state.held_action_buffer,
                                    action,
                                ),
                                holder_pos,
                                plan_signals,
                                state.held_decision_arena.scratch.local_pressure,
                                opportunity,
                                config,
                            );
                        }
                        if holder_home {
                            if let Some(live_holder) = home.get_mut(holder_idx) {
                                decision_goal_state.apply_to_player(live_holder);
                                let acceptance = sync_holder_tactical_task_from_action(
                                    live_holder,
                                    action,
                                    tick,
                                    state.home_plan_signals,
                                    attacking_right,
                                    config,
                                );
                                if acceptance.is_some() {
                                    record_tactical_task_resolution(
                                        &mut state.trace_decisions,
                                        config,
                                        tick,
                                        true,
                                        holder_idx,
                                        live_holder,
                                        state.home_plan_signals,
                                        "on_ball_action",
                                        Some(runner_action_name(action)),
                                        None,
                                        previous_tactical_task,
                                        acceptance,
                                    );
                                }
                            }
                        } else if let Some(live_holder) = away.get_mut(holder_idx) {
                            decision_goal_state.apply_to_player(live_holder);
                            let acceptance = sync_holder_tactical_task_from_action(
                                live_holder,
                                action,
                                tick,
                                state.away_plan_signals,
                                attacking_right,
                                config,
                            );
                            if acceptance.is_some() {
                                record_tactical_task_resolution(
                                    &mut state.trace_decisions,
                                    config,
                                    tick,
                                    false,
                                    holder_idx,
                                    live_holder,
                                    state.away_plan_signals,
                                    "on_ball_action",
                                    Some(runner_action_name(action)),
                                    None,
                                    previous_tactical_task,
                                    acceptance,
                                );
                            }
                        }
                        action
                    };
                    let frozen_pass_transition = state
                        .held_action_buffer
                        .iter()
                        .find(|candidate| {
                            runner_same_committed_action(candidate.action, held_action)
                        })
                        .and_then(|candidate| candidate.pass_transition);
                    let frozen_control_transition = (!action_is_continuation)
                        .then(|| {
                            state
                                .action_commitment
                                .as_ref()
                                .filter(|commitment| {
                                    runner_same_committed_action(commitment.action, held_action)
                                })
                                .and_then(|commitment| commitment.candidate.control_transition)
                        })
                        .flatten();
                    let frozen_shot_model = state
                        .held_action_buffer
                        .iter()
                        .find(|candidate| {
                            runner_same_committed_action(candidate.action, held_action)
                        })
                        .and_then(|candidate| candidate.shot_model);
                    let frozen_clearance_transition = state
                        .held_action_buffer
                        .iter()
                        .find(|candidate| {
                            runner_same_committed_action(candidate.action, held_action)
                        })
                        .and_then(|candidate| candidate.clearance_transition);
                    if receipt_follow_up
                        && matches!(
                            held_action,
                            RunnerHeldAction::Carry { .. }
                                | RunnerHeldAction::Hold { .. }
                                | RunnerHeldAction::Reorient { .. }
                        )
                    {
                        break 'held_phase;
                    }
                    let holder_action_type = runner_action_name(held_action);
                    let mut duel_contact: Option<crate::DetectionResult> = None;
                    let mut duel_context: Option<RunnerDuelContext> = None;
                    let mut interception_defender_idx: Option<usize> = None;
                    match held_action {
                        RunnerHeldAction::Carry { target } => {
                            let holder_dribbling = if holder_home {
                                home.get(holder_idx)
                            } else {
                                away.get(holder_idx)
                            }
                            .map(|holder| holder.dribbling)
                            .unwrap_or(50.0);
                            let transition = crate::carry_contact_transition(
                                holder_pos,
                                target,
                                config.carrier_speed,
                                holder_dribbling,
                                &defender_phase1_inputs,
                                config.tackle_range,
                            );
                            if transition.contact_occurs(rng.random()) {
                                duel_contact = Some(transition.contact);
                                duel_context = Some(RunnerDuelContext::Carry);
                            }
                        }
                        RunnerHeldAction::Hold { .. } | RunnerHeldAction::Reorient { .. } => {
                            let (holder_action, carry_target, carrier_step_distance) =
                                match held_action {
                                    RunnerHeldAction::Hold { opportunity_target } => (
                                        "hold",
                                        opportunity_target.unwrap_or(holder_pos),
                                        config.carrier_speed * 0.34,
                                    ),
                                    RunnerHeldAction::Reorient { target } => {
                                        ("reorient", target, config.carrier_speed * 0.24)
                                    }
                                    _ => unreachable!(),
                                };
                            let holder_dribbling = if holder_home {
                                home.get(holder_idx)
                            } else {
                                away.get(holder_idx)
                            }
                            .map(|holder| holder.dribbling)
                            .unwrap_or(50.0);
                            let transition = frozen_control_transition
                                .map(|transition| transition.contact)
                                .unwrap_or_else(|| {
                                    crate::control_contact_transition(
                                        holder_pos,
                                        holder_action,
                                        carry_target,
                                        carrier_step_distance,
                                        holder_dribbling,
                                        &defender_phase1_inputs,
                                        config.tackle_range,
                                    )
                                });
                            if transition.contact_occurs(rng.random()) {
                                duel_contact = Some(transition.contact);
                                duel_context = Some(match held_action {
                                    RunnerHeldAction::Hold { .. } => RunnerDuelContext::Hold,
                                    RunnerHeldAction::Reorient { .. } => {
                                        RunnerDuelContext::Reorient
                                    }
                                    _ => unreachable!(),
                                });
                            }
                        }
                        RunnerHeldAction::Pass { target, .. } => {
                            let release = frozen_pass_transition.map_or_else(
                                || {
                                    let holder_dribbling = if holder_home {
                                        home.get(holder_idx)
                                    } else {
                                        away.get(holder_idx)
                                    }
                                    .map(|holder| holder.dribbling)
                                    .unwrap_or(50.0);
                                    crate::pass_release_contact_transition(
                                        holder_pos,
                                        target,
                                        config.carrier_speed * 0.18,
                                        holder_dribbling,
                                        defender_phase1_inputs.as_slice(),
                                        config.tackle_range,
                                    )
                                },
                                |transition| transition.release,
                            );
                            let duel = release.contact;
                            if duel
                                .defender_index
                                .is_some_and(|_| rng.random() < duel.contact_probability)
                            {
                                duel_contact = Some(duel);
                                duel_context = Some(RunnerDuelContext::Pass);
                            }
                            let interception = detect_interception(&InterceptionDetectionInput {
                                pass_origin: holder_pos,
                                pass_target: target,
                                defenders: &defender_phase1_inputs,
                                interception_reach: config.interception_reach,
                            });
                            interception_defender_idx = interception.defender_index;
                        }
                        RunnerHeldAction::Clear { .. } | RunnerHeldAction::Shoot { .. } => {}
                    }
                    if holder_home {
                        track_runner_pressures(
                            tick,
                            away,
                            holder_pos,
                            holder_action_type,
                            &defender_phase1_inputs,
                            duel_contact.is_some(),
                            interception_defender_idx.is_some(),
                            config,
                        );
                    } else {
                        track_runner_pressures(
                            tick,
                            home,
                            holder_pos,
                            holder_action_type,
                            &defender_phase1_inputs,
                            duel_contact.is_some(),
                            interception_defender_idx.is_some(),
                            config,
                        );
                    }
                    'held_action_dispatch: {
                        match held_action {
                            RunnerHeldAction::Hold { opportunity_target } => 'control_action: {
                                if let (Some(contact), Some(context)) = (duel_contact, duel_context)
                                {
                                    let defender_idx =
                                        contact.defender_index.expect("duel contact has defender");
                                    let Some(defender) = defender_phase1_inputs
                                        .iter()
                                        .find(|defender| defender.index == defender_idx)
                                        .copied()
                                    else {
                                        break 'control_action;
                                    };
                                    let duel_result = resolve_runner_duel(
                                        state,
                                        tick,
                                        half,
                                        holder_idx,
                                        holder_home,
                                        defender,
                                        context,
                                        contact,
                                        home,
                                        away,
                                        home_attacking_right,
                                        config,
                                        rng,
                                    );
                                    if duel_result != RunnerDuelResult::ContinuePossession {
                                        break 'control_action;
                                    }
                                }
                                execute_runner_control_action(
                                    state,
                                    tick,
                                    half,
                                    holder_idx,
                                    holder_home,
                                    action_is_continuation,
                                    "hold",
                                    frozen_control_transition,
                                    opportunity_target,
                                    None,
                                    home,
                                    away,
                                    &opponents,
                                    attacking_right,
                                    config,
                                    rng,
                                );
                            }
                            RunnerHeldAction::Reorient { target } => 'reorient_action: {
                                if let (Some(contact), Some(context)) = (duel_contact, duel_context)
                                {
                                    let defender_idx =
                                        contact.defender_index.expect("duel contact has defender");
                                    let Some(defender) = defender_phase1_inputs
                                        .iter()
                                        .find(|defender| defender.index == defender_idx)
                                        .copied()
                                    else {
                                        break 'reorient_action;
                                    };
                                    let duel_result = resolve_runner_duel(
                                        state,
                                        tick,
                                        half,
                                        holder_idx,
                                        holder_home,
                                        defender,
                                        context,
                                        contact,
                                        home,
                                        away,
                                        home_attacking_right,
                                        config,
                                        rng,
                                    );
                                    if duel_result != RunnerDuelResult::ContinuePossession {
                                        break 'reorient_action;
                                    }
                                }
                                execute_runner_control_action(
                                    state,
                                    tick,
                                    half,
                                    holder_idx,
                                    holder_home,
                                    action_is_continuation,
                                    "reorient",
                                    frozen_control_transition,
                                    None,
                                    Some(target),
                                    home,
                                    away,
                                    &opponents,
                                    attacking_right,
                                    config,
                                    rng,
                                );
                            }
                            RunnerHeldAction::Carry { target } => 'carry_action: {
                                let frozen_transition = (!action_is_continuation)
                                    .then(|| {
                                        state
                                            .action_commitment
                                            .as_ref()
                                            .filter(|commitment| {
                                                runner_same_committed_action(
                                                    commitment.action,
                                                    held_action,
                                                )
                                            })
                                            .and_then(|commitment| {
                                                commitment.candidate.carry_transition
                                            })
                                    })
                                    .flatten();
                                if let Some(contact) = duel_contact {
                                    let defender_idx =
                                        contact.defender_index.expect("duel contact has defender");
                                    let Some(defender) = defender_phase1_inputs
                                        .iter()
                                        .find(|defender| defender.index == defender_idx)
                                        .copied()
                                    else {
                                        break 'carry_action;
                                    };
                                    let duel_result = resolve_runner_duel(
                                        state,
                                        tick,
                                        half,
                                        holder_idx,
                                        holder_home,
                                        defender,
                                        RunnerDuelContext::Carry,
                                        contact,
                                        home,
                                        away,
                                        home_attacking_right,
                                        config,
                                        rng,
                                    );
                                    if duel_result != RunnerDuelResult::ContinuePossession {
                                        break 'carry_action;
                                    }
                                }
                                let holder = if holder_home {
                                    home.get_mut(holder_idx)
                                } else {
                                    away.get_mut(holder_idx)
                                };
                                let Some(holder) = holder else { return };
                                let holder_identity = event_player(Some(holder));
                                if !action_is_continuation {
                                    holder.carries_attempted += 1;
                                }
                                holder.hold_ticks = 0;
                                let old_pos = holder.pos;
                                let carry_error_roll = rng.random();
                                let carry_containment_roll = rng.random();
                                let carry = carry_phase_plan(&CarryPhasePlanInput {
                                    transition: frozen_transition,
                                    holder_pos: holder.pos,
                                    target,
                                    velocity: holder.velocity,
                                    speed_ability: holder.speed.round() as i32,
                                    dribbling: holder.dribbling,
                                    consecutive_carries: holder.consecutive_carries,
                                    control_readiness: crate::directional_control_readiness(
                                        state.ball.control,
                                        angle_between_points(holder.pos, target),
                                    ),
                                    attacking_right,
                                    pitch_length: config.pitch_length,
                                    pitch_width: config.pitch_width,
                                    player_max_speed: config.player_max_speed,
                                    player_min_speed: config.player_min_speed,
                                    carrier_speed: config.carrier_speed,
                                    carry_error_divisor: config.carry_error_divisor,
                                    opponents: &opponents,
                                    defender_responses: &defender_phase1_inputs,
                                    error_roll: carry_error_roll,
                                    containment_roll: carry_containment_roll,
                                    loose_x_roll: 0.5,
                                    loose_y_roll: 0.5,
                                });
                                if carry.is_error {
                                    holder.pos = carry.new_pos;
                                    holder.velocity = carry.velocity;
                                    if let Some(facing) = carry.facing_direction {
                                        holder.facing_direction = facing;
                                    }
                                    holder.distance_covered += carry.distance_covered;
                                    holder.turnovers += 1;
                                    holder.consecutive_carries = 0;
                                    update_runner_text(&mut holder.state, "off_ball");
                                    let player_name = holder.name.clone();
                                    let loose_pos =
                                        crate::execution_transition::RectangularLooseBallTransition {
                                            center: carry.new_pos,
                                            radius_x: 3.0,
                                            radius_y: 2.0,
                                            pitch_length: config.pitch_length,
                                            pitch_width: config.pitch_width,
                                        }
                                        .sample(rng.random(), rng.random());
                                    let _ = holder;
                                    set_contested_and_clear_goals(
                                        state,
                                        home,
                                        away,
                                        loose_pos,
                                        (0.0, 0.0),
                                    );
                                    record_technical_control_error(
                                        state,
                                        config,
                                        tick,
                                        half,
                                        state.possession_id,
                                        "carry",
                                        holder_home,
                                        holder_identity,
                                        old_pos,
                                        loose_pos,
                                    );
                                    trace_entry!(
                                        state,
                                        json!({
                                            "tick": tick,
                                            "type": "event",
                                            "event": "error",
                                            "error_type": "carry",
                                            "player": player_name
                                        })
                                    );
                                    break 'held_action_dispatch;
                                }
                                if let Some(boundary_crossing) = carry.boundary_crossing {
                                    holder.pos = boundary_crossing.point;
                                    holder.velocity = (0.0, 0.0);
                                    holder.hold_ticks = 0;
                                    holder.consecutive_carries = 0;
                                    update_runner_text(&mut holder.state, "off_ball");
                                    let player_name = holder.name.clone();
                                    let boundary = boundary_crossing.kind;
                                    let crossing = boundary_crossing.point;
                                    let plan = out_of_bounds_plan(&OutOfBoundsPlanInput {
                                        boundary,
                                        boundary_point: crossing,
                                        pitch_length: config.pitch_length,
                                        pitch_width: config.pitch_width,
                                        possession_team_home: holder_home,
                                        flight_type_code: 0,
                                        origin: old_pos,
                                        attacking_right,
                                        total_xg: 0.0,
                                        logged_xg_sum: 0.0,
                                        goal_kick_restart_ticks: config.goal_kick_restart_ticks,
                                        throw_in_restart_ticks: config.throw_in_restart_ticks,
                                    });
                                    let holder_identity = event_player(Some(holder));
                                    let _ = holder;
                                    set_dead_ball_and_clear_goals(
                                        state,
                                        home,
                                        away,
                                        plan.reason.as_str(),
                                        plan.restart_team_home,
                                        plan.restart_ticks,
                                        crossing,
                                    );
                                    trace_entry!(
                                        state,
                                        json!({
                                            "tick": tick,
                                            "type": "event",
                                            "event": "out_of_bounds",
                                            "source": "carry",
                                            "player": player_name,
                                            "boundary": match boundary {
                                                crate::PitchBoundaryKind::GoalLine => "goal_line",
                                                crate::PitchBoundaryKind::TouchLine => "touch_line",
                                            },
                                            "crossing": [round_one(crossing.0), round_one(crossing.1)],
                                            "reason": plan.reason,
                                            "restart_team": if plan.restart_team_home { "home" } else { "away" },
                                            "restart_ticks": plan.restart_ticks
                                        })
                                    );
                                    record_match_event(
                                        state,
                                        config,
                                        MatchEventInput {
                                            tick,
                                            half,
                                            possession_id: state.possession_id,
                                            event_type: "carry",
                                            team_home: holder_home,
                                            player: holder_identity,
                                            target_player: serde_json::Value::Null,
                                            assist_player: serde_json::Value::Null,
                                            outcome: "out_of_play",
                                            xg: 0.0,
                                            origin: Some(old_pos),
                                            target: Some(crossing),
                                            tags: EventTags::one(plan.reason.as_str()),
                                            score_before: None,
                                        },
                                    );
                                    break 'held_action_dispatch;
                                }
                                holder.pos = carry.new_pos;
                                holder.velocity = carry.velocity;
                                if let Some(facing) = carry.facing_direction {
                                    holder.facing_direction = facing;
                                }
                                holder.distance_covered += carry.distance_covered;
                                if !action_is_continuation {
                                    holder.carries_completed += 1;
                                    holder.consecutive_carries += 1;
                                }
                                let carry_stats = track_carry_stats(&CarryStatInput {
                                    old_pos,
                                    new_pos: carry.new_pos,
                                    attacking_right,
                                    pitch_length: config.pitch_length,
                                    pitch_width: config.pitch_width,
                                });
                                if !action_is_continuation {
                                    holder.progressive_carries += carry_stats.progressive_carries;
                                    holder.carries_into_final_third +=
                                        carry_stats.carries_into_final_third;
                                    holder.carries_into_box += carry_stats.carries_into_box;
                                }
                                state.ball.position = carry.new_pos;
                                let control_heading = holder.facing_direction;
                                let mut carry_tags = EventTags::empty();
                                if carry_stats.progressive_carries > 0 {
                                    carry_tags.push("progressive");
                                }
                                if carry_stats.carries_into_final_third > 0 {
                                    carry_tags.push("into_final_third");
                                }
                                if carry_stats.carries_into_box > 0 {
                                    carry_tags.push("into_box");
                                }
                                trace_entry!(
                                    state,
                                    json!({
                                        "tick": tick,
                                        "type": "action",
                                        "team": if holder_home { "home" } else { "away" },
                                        "player": holder.name,
                                        "action": "carry",
                                        "phase": if action_is_continuation { "continue" } else { "start" },
                                        "from": [round_one(old_pos.0), round_one(old_pos.1)],
                                        "target": [round_one(target.0), round_one(target.1)],
                                        "pos": [round_one(holder.pos.0), round_one(holder.pos.1)],
                                        "distance": round_one(carry.distance_covered),
                                        "constrained_control": carry.constrained_control,
                                        "containment_probability": round_two(carry.constrained_control_probability),
                                        "containment_position": [
                                            round_one(carry.constrained_control_position.0),
                                            round_one(carry.constrained_control_position.1)
                                        ]
                                    })
                                );
                                if !action_is_continuation {
                                    record_match_event(
                                        state,
                                        config,
                                        MatchEventInput {
                                            tick,
                                            half,
                                            possession_id: state.possession_id,
                                            event_type: "carry",
                                            team_home: holder_home,
                                            player: holder_identity,
                                            target_player: serde_json::Value::Null,
                                            assist_player: serde_json::Value::Null,
                                            outcome: "completed",
                                            xg: 0.0,
                                            origin: Some(old_pos),
                                            target: Some(carry.new_pos),
                                            tags: carry_tags,
                                            score_before: None,
                                        },
                                    );
                                }
                                if carry.constrained_control {
                                    state.action_commitment = None;
                                }
                                let _ = holder;
                                let (controlling_players, defending_players) = if holder_home {
                                    (&*home, &*away)
                                } else {
                                    (&*away, &*home)
                                };
                                state.ball.control = runner_live_control_transition(
                                    state.ball.control,
                                    holder_idx,
                                    carry.new_pos,
                                    controlling_players,
                                    defending_players,
                                    attacking_right,
                                    control_heading,
                                    1.0,
                                    carry.contact_load,
                                    1,
                                    carry.distance_covered,
                                    None,
                                    config.pitch_length,
                                    config.pitch_width,
                                );
                            }
                            RunnerHeldAction::Pass {
                                receiver_idx,
                                target,
                                is_long,
                                lane_risk,
                                retention_probability,
                                technical_probability,
                            } => {
                                if let (Some(contact), Some(context)) = (duel_contact, duel_context)
                                {
                                    let defender_idx =
                                        contact.defender_index.expect("duel contact has defender");
                                    let Some(defender) = defender_phase1_inputs
                                        .iter()
                                        .find(|defender| defender.index == defender_idx)
                                        .copied()
                                    else {
                                        break 'held_action_dispatch;
                                    };
                                    let duel_result = resolve_runner_duel(
                                        state,
                                        tick,
                                        half,
                                        holder_idx,
                                        holder_home,
                                        defender,
                                        context,
                                        contact,
                                        home,
                                        away,
                                        home_attacking_right,
                                        config,
                                        rng,
                                    );
                                    if duel_result != RunnerDuelResult::ContinuePossession {
                                        break 'held_action_dispatch;
                                    }
                                }
                                let passer = if holder_home {
                                    home.get(holder_idx)
                                } else {
                                    away.get(holder_idx)
                                };
                                let Some(passer) = passer else {
                                    break 'held_action_dispatch;
                                };
                                let passer_pos = passer.pos;
                                let passing = if is_long {
                                    passer.long_passing
                                } else {
                                    passer.short_passing
                                };
                                let intended_receiver_pos = if holder_home {
                                    home.get(receiver_idx).map(|receiver| receiver.pos)
                                } else {
                                    away.get(receiver_idx).map(|receiver| receiver.pos)
                                };
                                let pass_randoms = preview_randoms::<3>(rng);
                                let pass = pass_phase_plan(&PassPhasePlanInput {
                                    transition: frozen_pass_transition,
                                    passer_pos,
                                    ideal_target: target,
                                    passing,
                                    is_long,
                                    lane_risk,
                                    retention_probability,
                                    technical_probability,
                                    technical_roll: pass_randoms[0],
                                    pitch_length: config.pitch_length,
                                    pitch_width: config.pitch_width,
                                    ball_pass_speed: config.ball_pass_speed,
                                    ball_long_pass_speed: config.ball_long_pass_speed,
                                    tick_duration: config.tick_duration,
                                    random_1: pass_randoms[1],
                                    random_2: pass_randoms[2],
                                    intended_receiver_pos,
                                });
                                advance_randoms(rng, pass.randoms_used);
                                if holder_home {
                                    if let Some(holder) = home.get_mut(holder_idx) {
                                        holder.passes_attempted += 1;
                                        holder.hold_ticks = 0;
                                        holder.consecutive_carries = 0;
                                        update_runner_text(&mut holder.state, "off_ball");
                                        clear_player_goal(holder);
                                    }
                                } else if let Some(holder) = away.get_mut(holder_idx) {
                                    holder.passes_attempted += 1;
                                    holder.hold_ticks = 0;
                                    holder.consecutive_carries = 0;
                                    update_runner_text(&mut holder.state, "off_ball");
                                    clear_player_goal(holder);
                                }
                                state.ball.state = RunnerBallState::InFlight;
                                state.ball.position = passer_pos;
                                state.ball.holder_idx = None;
                                state.ball.holder_team_home = None;
                                state.ball.loose_velocity = (0.0, 0.0);
                                state.ball.contested_ticks = 0;
                                state.last_passer_team_home = Some(holder_home);
                                state.last_passer_idx = holder_idx as i32;
                                let mut offside_flags = if holder_home {
                                    flag_offside_indices(
                                        home,
                                        away,
                                        holder_idx,
                                        passer_pos,
                                        attacking_right,
                                        config,
                                    )
                                } else {
                                    flag_offside_indices(
                                        away,
                                        home,
                                        holder_idx,
                                        passer_pos,
                                        attacking_right,
                                        config,
                                    )
                                };
                                if config.runner_force_receiver_offside
                                    && receiver_idx < RUNNER_TEAM_SIZE
                                {
                                    offside_flags[receiver_idx] = true;
                                }
                                set_offside_phase(
                                    state,
                                    holder_home,
                                    holder_idx,
                                    passer_pos,
                                    offside_flags,
                                );
                                let arrival_snapshot = if holder_home {
                                    runner_pass_arrival_snapshot(
                                        holder_idx,
                                        Some(receiver_idx),
                                        pass.target,
                                        home,
                                        away,
                                    )
                                } else {
                                    runner_pass_arrival_snapshot(
                                        holder_idx,
                                        Some(receiver_idx),
                                        pass.target,
                                        away,
                                        home,
                                    )
                                };
                                let arrival_plan = runner_pass_arrival_plan_from_snapshot(
                                    arrival_snapshot,
                                    pass.target,
                                    passer_pos,
                                    pass.speed,
                                    pass.ticks_needed,
                                    config,
                                );
                                state.ball.flight = Some(RunnerFlight {
                                    kind: RunnerFlightKind::Pass,
                                    replay_id: next_replay_flight_id(state),
                                    replay_start_tick: tick,
                                    origin: passer_pos,
                                    target: pass.target,
                                    ticks_elapsed: 0,
                                    ticks_total: pass.ticks_needed,
                                    passer_idx: holder_idx,
                                    passer_team_home: holder_home,
                                    intended_receiver_idx: Some(receiver_idx),
                                    offside_flags,
                                    last_passer_team_home: state.last_passer_team_home,
                                    last_passer_idx: state.last_passer_idx,
                                    on_target: false,
                                    speed: pass.speed,
                                    xg: 0.0,
                                    gk_attributes: None,
                                    is_long,
                                    target_is_space: pass.target_kind_code == 1,
                                    retention_probability: pass.retention_probability,
                                    technical_probability: pass.technical_probability,
                                    technical_roll: pass.technical_roll,
                                    delivery_miss: pass.delivery_miss,
                                    arrival_snapshot: Some(arrival_snapshot),
                                    arrival_plan: Some(arrival_plan),
                                    clearance_transition: None,
                                    possession_id: state.possession_id,
                                });
                                trace_entry!(
                                    state,
                                    json!({
                                        "tick": tick,
                                        "type": "action",
                                        "team": if holder_home { "home" } else { "away" },
                                        "player": if holder_home {
                                            runner_player_name(home, holder_idx)
                                        } else {
                                            runner_player_name(away, holder_idx)
                                        },
                                        "action": "pass",
                                        "target_player": receiver_idx,
                                        "target": [round_one(pass.target.0), round_one(pass.target.1)],
                                        "pass_type": if is_long { "long" } else { "short" },
                                        "target_kind": if pass.target_kind_code == 1 { "space" } else { "feet" },
                                        "retention_probability": pass.retention_probability,
                                        "technical_probability": pass.technical_probability,
                                        "technical_roll": pass.technical_roll,
                                        "delivery_miss": pass.delivery_miss
                                    })
                                );
                            }
                            RunnerHeldAction::Clear { target } => {
                                let holder = if holder_home {
                                    home.get_mut(holder_idx)
                                } else {
                                    away.get_mut(holder_idx)
                                };
                                let Some(holder) = holder else { return };
                                holder.clearances += 1;
                                holder.passes_attempted += 1;
                                holder.hold_ticks = 0;
                                holder.consecutive_carries = 0;
                                update_runner_text(&mut holder.state, "off_ball");
                                clear_player_goal(holder);
                                let clearer_pos = holder.pos;
                                let clearer_name = holder.name.clone();
                                let clear = clear_phase_plan(&ClearPhasePlanInput {
                                    clearer_pos,
                                    target,
                                    ball_long_pass_speed: config.ball_long_pass_speed,
                                    tick_duration: config.tick_duration,
                                });
                                state.ball.state = RunnerBallState::InFlight;
                                state.ball.position = clearer_pos;
                                state.ball.holder_idx = None;
                                state.ball.holder_team_home = None;
                                state.ball.loose_velocity = (0.0, 0.0);
                                state.ball.contested_ticks = 0;
                                state.last_passer_team_home = Some(holder_home);
                                state.last_passer_idx = holder_idx as i32;
                                let offside_flags = if holder_home {
                                    flag_offside_indices(
                                        home,
                                        away,
                                        holder_idx,
                                        clearer_pos,
                                        attacking_right,
                                        config,
                                    )
                                } else {
                                    flag_offside_indices(
                                        away,
                                        home,
                                        holder_idx,
                                        clearer_pos,
                                        attacking_right,
                                        config,
                                    )
                                };
                                set_offside_phase(
                                    state,
                                    holder_home,
                                    holder_idx,
                                    clearer_pos,
                                    offside_flags,
                                );
                                state.ball.flight = Some(RunnerFlight {
                                    kind: RunnerFlightKind::Clearance,
                                    replay_id: next_replay_flight_id(state),
                                    replay_start_tick: tick,
                                    origin: clear.origin,
                                    target: clear.target,
                                    ticks_elapsed: 0,
                                    ticks_total: clear.ticks_needed,
                                    passer_idx: holder_idx,
                                    passer_team_home: holder_home,
                                    intended_receiver_idx: None,
                                    offside_flags,
                                    last_passer_team_home: state.last_passer_team_home,
                                    last_passer_idx: state.last_passer_idx,
                                    on_target: false,
                                    speed: clear.speed,
                                    xg: 0.0,
                                    gk_attributes: None,
                                    is_long: true,
                                    target_is_space: true,
                                    retention_probability: 0.0,
                                    technical_probability: 0.0,
                                    technical_roll: 1.0,
                                    delivery_miss: false,
                                    arrival_snapshot: None,
                                    arrival_plan: None,
                                    clearance_transition: frozen_clearance_transition,
                                    possession_id: state.possession_id,
                                });
                                trace_entry!(
                                    state,
                                    json!({
                                        "tick": tick,
                                        "type": "action",
                                        "team": if holder_home { "home" } else { "away" },
                                        "player": clearer_name,
                                        "action": "clear",
                                        "target": [round_one(clear.target.0), round_one(clear.target.1)]
                                    })
                                );
                            }
                            RunnerHeldAction::Shoot { target, .. } => {
                                let (shooter_name, shot_origin, execution) = if holder_home {
                                    let Some(holder) = home.get(holder_idx) else {
                                        return;
                                    };
                                    (
                                        holder.name.clone(),
                                        holder.pos,
                                        evaluate_real_shot_execution(
                                            holder_idx,
                                            holder,
                                            true,
                                            away,
                                            contest_defenders,
                                            state.ball.control,
                                            attacking_right,
                                            tick,
                                            &state.shot_quality_cache,
                                            config,
                                        ),
                                    )
                                } else {
                                    let Some(holder) = away.get(holder_idx) else {
                                        return;
                                    };
                                    (
                                        holder.name.clone(),
                                        holder.pos,
                                        evaluate_real_shot_execution(
                                            holder_idx,
                                            holder,
                                            false,
                                            home,
                                            contest_defenders,
                                            state.ball.control,
                                            attacking_right,
                                            tick,
                                            &state.shot_quality_cache,
                                            config,
                                        ),
                                    )
                                };
                                let shot = execution.outcome;
                                let xg = shot.xg;
                                let on_target_prob = shot.on_target_prob;
                                let gk_attributes = execution.gk_attributes;
                                let body_release_probability = shot.body_release_probability;
                                let release_probability = shot.release_probability;
                                let block_probability = shot.block_probability;
                                let blocker_idx = shot.blocker_index;
                                let block_point = shot.block_point;
                                let shot_model = frozen_shot_model.unwrap_or_else(|| {
                                    crate::execution_transition::ShotActionModel::new(
                                        shot_origin,
                                        target,
                                        config.contest_radius,
                                        config.pitch_length,
                                        config.pitch_width,
                                    )
                                });
                                let shot_transition = shot_model.condition(
                                    body_release_probability,
                                    release_probability,
                                    block_probability,
                                );
                                let body_release_roll = rng.random();
                                if shot_transition.body_release.fails(body_release_roll) {
                                    let mishit_pos =
                                        shot_model.mishit.sample(rng.random(), rng.random());
                                    trace_entry!(
                                        state,
                                        json!({
                                            "tick": tick,
                                            "type": "event",
                                            "event": "shot_mishit",
                                            "team": if holder_home { "home" } else { "away" },
                                            "player": shooter_name,
                                            "body_release_probability": round_two(body_release_probability),
                                            "body_release_roll": round_two(body_release_roll),
                                            "origin": [round_one(shot_origin.0), round_one(shot_origin.1)],
                                            "loose_pos": [round_one(mishit_pos.0), round_one(mishit_pos.1)]
                                        })
                                    );
                                    if let Some(holder) = if holder_home {
                                        home.get_mut(holder_idx)
                                    } else {
                                        away.get_mut(holder_idx)
                                    } {
                                        holder.turnovers += 1;
                                        holder.hold_ticks = 0;
                                        holder.consecutive_carries = 0;
                                        update_runner_text(&mut holder.state, "off_ball");
                                        clear_player_goal(holder);
                                    }
                                    set_contested_and_clear_goals(
                                        state,
                                        home,
                                        away,
                                        mishit_pos,
                                        (0.0, 0.0),
                                    );
                                    record_shot_mishit(
                                        state,
                                        config,
                                        tick,
                                        half,
                                        state.possession_id,
                                        holder_home,
                                        if holder_home {
                                            player_identity(home, holder_idx)
                                        } else {
                                            player_identity(away, holder_idx)
                                        },
                                        shot_origin,
                                        mishit_pos,
                                    );
                                    break 'held_action_dispatch;
                                }
                                let shot_last_passer_team_home = state.last_passer_team_home;
                                let shot_last_passer_idx = state.last_passer_idx;
                                if state.last_passer_team_home == Some(holder_home)
                                    && state.last_passer_idx >= 0
                                    && state.last_passer_idx as usize != holder_idx
                                {
                                    if holder_home {
                                        if let Some(passer) =
                                            home.get_mut(state.last_passer_idx as usize)
                                        {
                                            passer.key_passes += 1;
                                        }
                                    } else if let Some(passer) =
                                        away.get_mut(state.last_passer_idx as usize)
                                    {
                                        passer.key_passes += 1;
                                    }
                                }
                                let holder = if holder_home {
                                    home.get_mut(holder_idx)
                                } else {
                                    away.get_mut(holder_idx)
                                };
                                let Some(holder) = holder else { return };
                                holder.shots += 1;
                                holder.xg += xg;
                                holder.hold_ticks = 0;
                                holder.consecutive_carries = 0;
                                update_runner_text(&mut holder.state, "off_ball");
                                clear_player_goal(holder);
                                let contest_roll = rng.random();
                                let shot_execution_outcome =
                                    shot_transition.sample(body_release_roll, contest_roll);
                                if shot_execution_outcome
                                    == crate::execution_transition::ShotExecutionOutcome::Blocked
                                {
                                    let in_box = crate::physics::is_attacking_box_pos(
                                        shot_origin,
                                        attacking_right,
                                        config.pitch_length,
                                        config.pitch_width,
                                    );
                                    let shot_log = ShotLogEntryOutput {
                                        x: round_one(shot_origin.0),
                                        y: round_one(shot_origin.1),
                                        xg,
                                        in_box,
                                        outcome: "blocked".to_string(),
                                        target_x: Some(round_one(block_point.0)),
                                        target_y: Some(round_one(block_point.1)),
                                    };
                                    let blocker_identity = blocker_idx
                                        .map(|idx| {
                                            if holder_home {
                                                player_identity(away, idx)
                                            } else {
                                                player_identity(home, idx)
                                            }
                                        })
                                        .unwrap_or(serde_json::Value::Null);
                                    if holder_home {
                                        if let Some(blocker_idx) = blocker_idx {
                                            if let Some(blocker) = away.get_mut(blocker_idx) {
                                                blocker.blocks += 1;
                                            }
                                        }
                                        if let Some(shooter) = home.get_mut(holder_idx) {
                                            shooter.shot_log.push(shot_log_json(&shot_log));
                                        }
                                    } else {
                                        if let Some(blocker_idx) = blocker_idx {
                                            if let Some(blocker) = home.get_mut(blocker_idx) {
                                                blocker.blocks += 1;
                                            }
                                        }
                                        if let Some(shooter) = away.get_mut(holder_idx) {
                                            shooter.shot_log.push(shot_log_json(&shot_log));
                                        }
                                    }
                                    record_match_event(
                                        state,
                                        config,
                                        MatchEventInput {
                                            tick,
                                            half,
                                            possession_id: state.possession_id,
                                            event_type: "shot",
                                            team_home: holder_home,
                                            player: if holder_home {
                                                player_identity(home, holder_idx)
                                            } else {
                                                player_identity(away, holder_idx)
                                            },
                                            target_player: blocker_identity,
                                            assist_player: serde_json::Value::Null,
                                            outcome: "blocked",
                                            xg,
                                            origin: Some(shot_origin),
                                            target: Some(block_point),
                                            tags: EventTags::from_slice(&[
                                                if in_box { "in_box" } else { "outside_box" },
                                                "blocked",
                                            ]),
                                            score_before: None,
                                        },
                                    );
                                    set_contested_and_clear_goals(
                                        state,
                                        home,
                                        away,
                                        block_point,
                                        crate::physics::residual_ball_velocity(
                                            shot_origin,
                                            block_point,
                                            config.ball_shot_speed,
                                            0.14,
                                        ),
                                    );
                                    let replay_id = next_replay_flight_id(state);
                                    queue_replay_frame(
                                        state,
                                        tick,
                                        half,
                                        home,
                                        away,
                                        config,
                                        Some(RunnerReplayBallFlight {
                                            id: replay_id,
                                            from: [
                                                round_one(shot_origin.1),
                                                round_one(shot_origin.0),
                                            ],
                                            to: [
                                                round_one(block_point.1),
                                                round_one(block_point.0),
                                            ],
                                            end: [
                                                round_one(block_point.1),
                                                round_one(block_point.0),
                                            ],
                                            flight_type: "shot",
                                            on_target: false,
                                            start_tick: tick,
                                            elapsed_ticks: 1,
                                            total_ticks: 1,
                                            complete: true,
                                            end_reason: Some("blocked"),
                                        }),
                                        Some("BLOCKED"),
                                        Some(450),
                                        None,
                                        None,
                                    );
                                    trace_entry!(
                                        state,
                                        json!({
                                            "tick": tick,
                                            "type": "event",
                                            "event": "shot_blocked",
                                            "team": if holder_home { "home" } else { "away" },
                                            "player": shooter_name,
                                            "blocker_idx": blocker_idx,
                                            "block_probability": round_two(block_probability),
                                            "release_probability": round_two(release_probability),
                                            "contest_roll": round_two(contest_roll),
                                            "origin": [round_one(shot_origin.0), round_one(shot_origin.1)],
                                            "block_point": [round_one(block_point.0), round_one(block_point.1)],
                                        })
                                    );
                                    break 'held_action_dispatch;
                                }
                                let shot_randoms = preview_randoms::<3>(rng);
                                let shot = shot_phase_plan(&ShotPhasePlanInput {
                                    shooter_name: shooter_name.as_str(),
                                    shooter_pos: shot_origin,
                                    explicit_xg: Some(xg),
                                    on_target_prob,
                                    goal_reward_constant: 1.0,
                                    attacking_right,
                                    pitch_length: config.pitch_length,
                                    pitch_width: config.pitch_width,
                                    goal_width: config.goal_width,
                                    ball_shot_speed: config.ball_shot_speed,
                                    tick_duration: config.tick_duration,
                                    random_1: shot_randoms[0],
                                    random_2: shot_randoms[1],
                                    random_3: shot_randoms[2],
                                });
                                advance_randoms(rng, shot.randoms_used);
                                if shot.on_target {
                                    holder.shots_on_target += 1;
                                }
                                state.ball.state = RunnerBallState::InFlight;
                                state.ball.position = shot_origin;
                                state.ball.holder_idx = None;
                                state.ball.holder_team_home = None;
                                state.ball.loose_velocity = (0.0, 0.0);
                                state.ball.contested_ticks = 0;
                                state.ball.flight = Some(RunnerFlight {
                                    kind: RunnerFlightKind::Shot,
                                    replay_id: next_replay_flight_id(state),
                                    replay_start_tick: tick,
                                    origin: shot_origin,
                                    target: shot.target,
                                    ticks_elapsed: 0,
                                    ticks_total: shot.ticks_needed,
                                    passer_idx: holder_idx,
                                    passer_team_home: holder_home,
                                    intended_receiver_idx: None,
                                    offside_flags: [false; RUNNER_TEAM_SIZE],
                                    last_passer_team_home: shot_last_passer_team_home,
                                    last_passer_idx: shot_last_passer_idx,
                                    on_target: shot.on_target,
                                    speed: shot.speed,
                                    xg,
                                    gk_attributes: Some(gk_attributes),
                                    is_long: false,
                                    target_is_space: false,
                                    retention_probability: 0.0,
                                    technical_probability: 0.0,
                                    technical_roll: 1.0,
                                    delivery_miss: false,
                                    arrival_snapshot: None,
                                    arrival_plan: None,
                                    clearance_transition: None,
                                    possession_id: state.possession_id,
                                });
                                trace_entry!(
                                    state,
                                    json!({
                                        "tick": tick,
                                        "type": "action",
                                        "team": if holder_home { "home" } else { "away" },
                                        "player": shooter_name,
                                        "action": "shot",
                                        "xg": round_one(xg),
                                        "release_probability": round_two(release_probability),
                                        "block_probability": round_two(block_probability),
                                        "contest_roll": round_two(contest_roll),
                                        "target": [round_one(shot.target.0), round_one(shot.target.1)]
                                    })
                                );
                            }
                        }
                    }
                    if state.ball.state == RunnerBallState::Held
                        && state.ball.holder_idx == Some(holder_idx)
                        && state.ball.holder_team_home == Some(holder_home)
                    {
                        let holder_pos = if holder_home {
                            home.get(holder_idx).map(|holder| holder.pos)
                        } else {
                            away.get(holder_idx).map(|holder| holder.pos)
                        }
                        .unwrap_or(state.ball.position);
                        advance_action_commitment(state, holder_pos);
                    }
                    if !receipt_follow_up {
                        apply_held_tick_movement(
                            home,
                            away,
                            holder_home,
                            holder_idx,
                            tick,
                            state.home_plan_signals,
                            state.away_plan_signals,
                            &defender_phase1_inputs,
                            config,
                        );
                    }
                }
            }
        }
        RunnerBallState::InFlight => {
            if let Some(mut flight) = state.ball.flight.clone() {
                let flight_tick = tick_ball_flight(&FlightTickInput {
                    origin: flight.origin,
                    target: flight.target,
                    ticks_elapsed: flight.ticks_elapsed,
                    ticks_total: flight.ticks_total,
                });
                flight.ticks_elapsed = flight_tick.ticks_elapsed;
                state.ball.position = flight_tick.position;
                move_flight_players(
                    home,
                    away,
                    flight.clone(),
                    state,
                    tick,
                    config,
                    home_attacking_right,
                    rng,
                );
                if flight.kind == RunnerFlightKind::Pass && flight_interception_due(&flight) {
                    settle_pass_interception_at_contact(
                        state,
                        tick,
                        half,
                        flight,
                        home,
                        away,
                        config,
                        home_attacking_right,
                    );
                } else if !flight_tick.complete {
                    state.ball.flight = Some(flight);
                } else {
                    if is_out_of_bounds(flight.target, config) {
                        handle_out_of_bounds_flight(
                            state,
                            tick,
                            half,
                            flight,
                            home,
                            away,
                            config,
                            home_attacking_right,
                        );
                        push_rng_trace(state, tick, "tick_end", rng);
                        trace_entry!(
                            state,
                            json!({
                                "tick": tick,
                                "type": "state",
                                "ball_state": ball_state_name(state.ball.state),
                                "holder_team": state.ball.holder_team_home.map(|home| if home { "home" } else { "away" })
                            })
                        );
                        return;
                    }
                    match flight.kind {
                        RunnerFlightKind::Shot => {
                            let (shooter_name, shooter_color, shooter_xg, logged_xg_sum) = if flight
                                .passer_team_home
                            {
                                home.get(flight.passer_idx)
                                    .map(|player| {
                                        (
                                            player.name.clone(),
                                            player.color.clone(),
                                            player.xg,
                                            shot_log_sum(player),
                                        )
                                    })
                                    .unwrap_or_else(|| ("".to_string(), "".to_string(), 0.0, 0.0))
                            } else {
                                away.get(flight.passer_idx)
                                    .map(|player| {
                                        (
                                            player.name.clone(),
                                            player.color.clone(),
                                            player.xg,
                                            shot_log_sum(player),
                                        )
                                    })
                                    .unwrap_or_else(|| ("".to_string(), "".to_string(), 0.0, 0.0))
                            };
                            let shooter_identity = if flight.passer_team_home {
                                player_identity(home, flight.passer_idx)
                            } else {
                                player_identity(away, flight.passer_idx)
                            };
                            let keeper_identity = if flight.passer_team_home {
                                player_identity(away, 0)
                            } else {
                                player_identity(home, 0)
                            };
                            let assister_idx = if flight.last_passer_team_home
                                == Some(flight.passer_team_home)
                                && flight.last_passer_idx >= 0
                                && flight.last_passer_idx as usize != flight.passer_idx
                            {
                                Some(flight.last_passer_idx as usize)
                            } else {
                                None
                            };
                            let assister_identity = assister_idx
                                .map(|idx| {
                                    if flight.passer_team_home {
                                        player_identity(home, idx)
                                    } else {
                                        player_identity(away, idx)
                                    }
                                })
                                .unwrap_or(serde_json::Value::Null);
                            let score_before = (state.home_score, state.away_score);
                            let gk = if flight.passer_team_home {
                                away.get(0)
                            } else {
                                home.get(0)
                            };
                            let keeper_name =
                                gk.map(|player| player.name.clone()).unwrap_or_default();
                            let gk_attributes =
                                flight.gk_attributes.unwrap_or_else(|| GkSaveAttributes {
                                    gk_saving: gk.map(|player| player.gk_saving).unwrap_or(50.0),
                                    gk_positioning: gk
                                        .map(|player| player.gk_positioning)
                                        .unwrap_or(50.0),
                                    gk_reaction: gk
                                        .map(|player| player.gk_reaction)
                                        .unwrap_or(50.0),
                                    gk_position_error_factor: config.gk_position_error_factor,
                                    gk_reaction_delay_factor: config.gk_reaction_delay_factor,
                                    gk_save_base: config.gk_save_base,
                                });
                            let gk_pos = gk.map(|player| player.pos).unwrap_or((
                                if flight.passer_team_home {
                                    config.pitch_length - 4.5
                                } else {
                                    4.5
                                },
                                config.pitch_width / 2.0,
                            ));
                            let save_roll = if flight.on_target { rng.random() } else { 0.0 };
                            let arrival = shot_arrival_plan(&ShotArrivalPlanInput {
                                shooter_name: shooter_name.as_str(),
                                keeper_name: keeper_name.as_str(),
                                shot_origin: flight.origin,
                                shot_target: flight.target,
                                attacking_right: attacking_right_for(
                                    flight.passer_team_home,
                                    home_attacking_right,
                                ),
                                on_target: flight.on_target,
                                pitch_length: config.pitch_length,
                                pitch_width: config.pitch_width,
                                gk_pos,
                                gk_attributes,
                                save_roll,
                                total_xg: shooter_xg,
                                logged_xg_sum,
                            });
                            if flight.passer_team_home {
                                if let Some(shooter) = home.get_mut(flight.passer_idx) {
                                    shooter.post_shot_xg += arrival.psxg_delta;
                                }
                            } else if let Some(shooter) = away.get_mut(flight.passer_idx) {
                                shooter.post_shot_xg += arrival.psxg_delta;
                            }
                            match arrival.outcome_code {
                                1 => {
                                    let gk_pos = if flight.passer_team_home {
                                        away.get(0)
                                            .map(|player| player.pos)
                                            .unwrap_or(state.ball.position)
                                    } else {
                                        home.get(0)
                                            .map(|player| player.pos)
                                            .unwrap_or(state.ball.position)
                                    };
                                    if flight.passer_team_home {
                                        if let Some(gk) = away.get_mut(0) {
                                            gk.psxg_faced += arrival.psxg_delta;
                                            gk.saves += 1;
                                        }
                                    } else if let Some(gk) = home.get_mut(0) {
                                        gk.psxg_faced += arrival.psxg_delta;
                                        gk.saves += 1;
                                    }
                                    give_ball_to_player(
                                        state,
                                        home,
                                        away,
                                        0,
                                        !flight.passer_team_home,
                                        gk_pos,
                                        None,
                                        home_attacking_right,
                                        config,
                                    );
                                    let holder_idx = state.ball.holder_idx;
                                    let holder_team =
                                        state.ball.holder_team_home.map(|team_home| {
                                            if team_home {
                                                "home"
                                            } else {
                                                "away"
                                            }
                                        });
                                    queue_replay_flight_terminal_frame(
                                        state,
                                        tick,
                                        half,
                                        home,
                                        away,
                                        config,
                                        &flight,
                                        state.ball.position,
                                        state.ball.position,
                                        RunnerReplayFlightEnd::Saved,
                                        Some("SAVE"),
                                        Some(1200),
                                        holder_idx,
                                        holder_team,
                                    );
                                }
                                2 => {
                                    let (assister_name, assister_color) = if flight
                                        .last_passer_team_home
                                        == Some(flight.passer_team_home)
                                        && flight.last_passer_idx >= 0
                                        && flight.last_passer_idx as usize != flight.passer_idx
                                    {
                                        let scoring_team = if flight.passer_team_home {
                                            &*home
                                        } else {
                                            &*away
                                        };
                                        scoring_team
                                            .get(flight.last_passer_idx as usize)
                                            .map(|player| {
                                                (player.name.clone(), player.color.clone())
                                            })
                                            .unwrap_or_default()
                                    } else {
                                        (String::new(), String::new())
                                    };
                                    let goal_plan = score_goal_plan(&ScoreGoalPlanInput {
                                        scorer_name: shooter_name.as_str(),
                                        scoring_team_home: flight.passer_team_home,
                                        conceding_team_home: !flight.passer_team_home,
                                        home_score: state.home_score,
                                        away_score: state.away_score,
                                        last_passer_team_home: flight.last_passer_team_home,
                                        last_passer_idx: flight.last_passer_idx,
                                        scorer_idx: flight.passer_idx as i32,
                                        scoring_team_size: 11,
                                        assister_name: assister_name.as_str(),
                                        assister_color: assister_color.as_str(),
                                        tick,
                                        tick_duration: config.tick_duration,
                                    });
                                    state.home_score = goal_plan.home_score;
                                    state.away_score = goal_plan.away_score;
                                    if flight.passer_team_home {
                                        if goal_plan.has_assist && goal_plan.assister_idx >= 0 {
                                            if let Some(assister) =
                                                home.get_mut(goal_plan.assister_idx as usize)
                                            {
                                                assister.assists += 1;
                                            }
                                        }
                                        if let Some(scorer) = home.get_mut(flight.passer_idx) {
                                            scorer.goals += 1;
                                        }
                                        if let Some(gk) = away.get_mut(0) {
                                            gk.psxg_faced += arrival.psxg_delta;
                                            gk.goals_conceded += 1;
                                        }
                                    } else {
                                        if goal_plan.has_assist && goal_plan.assister_idx >= 0 {
                                            if let Some(assister) =
                                                away.get_mut(goal_plan.assister_idx as usize)
                                            {
                                                assister.assists += 1;
                                            }
                                        }
                                        if let Some(scorer) = away.get_mut(flight.passer_idx) {
                                            scorer.goals += 1;
                                        }
                                        if let Some(gk) = home.get_mut(0) {
                                            gk.psxg_faced += arrival.psxg_delta;
                                            gk.goals_conceded += 1;
                                        }
                                    }
                                    state.goals.push(json!({
                                "minute": goal_plan.minute,
                                "team_side": if flight.passer_team_home { "home" } else { "away" },
                                "scorer": shooter_name,
                                "assister": goal_plan.assister_name,
                                "scorer_color": shooter_color,
                                "assister_color": goal_plan.assister_color
                            }));
                                    queue_replay_flight_terminal_frame(
                                        state,
                                        tick,
                                        half,
                                        home,
                                        away,
                                        config,
                                        &flight,
                                        state.ball.position,
                                        flight.target,
                                        RunnerReplayFlightEnd::Goal,
                                        Some("GOAL"),
                                        Some(goal_plan.pause_ms),
                                        Some(flight.passer_idx),
                                        Some(if flight.passer_team_home {
                                            "home"
                                        } else {
                                            "away"
                                        }),
                                    );
                                    set_dead_ball_and_clear_goals(
                                        state,
                                        home,
                                        away,
                                        "kickoff",
                                        goal_plan.restart_team_home,
                                        goal_plan.restart_ticks,
                                        state.ball.position,
                                    );
                                    reset_players_to_current_formation_slots(
                                        home,
                                        home_attacking_right,
                                    );
                                    reset_players_to_current_formation_slots(
                                        away,
                                        !home_attacking_right,
                                    );
                                    trace_entry!(
                                        state,
                                        json!({
                                            "tick": tick,
                                            "type": "event",
                                            "event": "goal",
                                            "team": if flight.passer_team_home { "home" } else { "away" },
                                            "scorer": shooter_name,
                                            "minute": goal_plan.minute
                                        })
                                    );
                                }
                                _ => {
                                    set_dead_ball_and_clear_goals(
                                        state,
                                        home,
                                        away,
                                        "goal_kick",
                                        !flight.passer_team_home,
                                        config.goal_kick_restart_ticks,
                                        state.ball.position,
                                    );
                                    queue_replay_flight_terminal_frame(
                                        state,
                                        tick,
                                        half,
                                        home,
                                        away,
                                        config,
                                        &flight,
                                        state.ball.position,
                                        flight.target,
                                        RunnerReplayFlightEnd::Missed,
                                        Some("MISS"),
                                        Some(1200),
                                        Some(flight.passer_idx),
                                        Some(if flight.passer_team_home {
                                            "home"
                                        } else {
                                            "away"
                                        }),
                                    );
                                }
                            }
                            if flight.passer_team_home {
                                if let Some(shooter) = home.get_mut(flight.passer_idx) {
                                    shooter.shot_log.push(shot_log_json(&arrival.shot_log));
                                }
                            } else if let Some(shooter) = away.get_mut(flight.passer_idx) {
                                shooter.shot_log.push(shot_log_json(&arrival.shot_log));
                            }
                            record_match_event(
                                state,
                                config,
                                MatchEventInput {
                                    tick,
                                    half,
                                    possession_id: flight.possession_id,
                                    event_type: "shot",
                                    team_home: flight.passer_team_home,
                                    player: shooter_identity,
                                    target_player: keeper_identity,
                                    assist_player: if arrival.outcome_code == 2 {
                                        assister_identity
                                    } else {
                                        serde_json::Value::Null
                                    },
                                    outcome: arrival.shot_log.outcome.as_str(),
                                    xg: flight.xg,
                                    origin: Some(flight.origin),
                                    target: Some(flight.target),
                                    tags: shot_event_tags(
                                        &flight,
                                        arrival.in_box,
                                        arrival.shot_log.outcome.as_str(),
                                    ),
                                    score_before: Some(score_before),
                                },
                            );
                            trace_entry!(
                                state,
                                json!({
                                    "tick": tick,
                                    "type": "event",
                                    "event": "shot_arrival",
                                    "outcome": arrival.shot_log.outcome,
                                    "speed": round_one(flight.speed),
                                    "save_prob": arrival.save_prob,
                                    "save_roll": save_roll,
                                    "shot_origin": [flight.origin.0, flight.origin.1],
                                    "shot_target": [flight.target.0, flight.target.1],
                                    "gk_pos": [gk_pos.0, gk_pos.1]
                                })
                            );
                        }
                        RunnerFlightKind::Pass => {
                            let arrival = flight.arrival_plan.clone().unwrap_or_else(|| {
                                flight.arrival_snapshot.map_or_else(
                                    || {
                                        if flight.passer_team_home {
                                            runner_pass_arrival_plan(
                                                flight.passer_idx,
                                                flight.intended_receiver_idx,
                                                flight.target,
                                                flight.origin,
                                                flight.speed,
                                                flight.ticks_total,
                                                home,
                                                away,
                                                config,
                                            )
                                        } else {
                                            runner_pass_arrival_plan(
                                                flight.passer_idx,
                                                flight.intended_receiver_idx,
                                                flight.target,
                                                flight.origin,
                                                flight.speed,
                                                flight.ticks_total,
                                                away,
                                                home,
                                                config,
                                            )
                                        }
                                    },
                                    |snapshot| {
                                        runner_pass_arrival_plan_from_snapshot(
                                            snapshot,
                                            flight.target,
                                            flight.origin,
                                            flight.speed,
                                            flight.ticks_total,
                                            config,
                                        )
                                    },
                                )
                            });
                            let receiver_idx = runner_receiver_arrival_index(&arrival);
                            let opponent_idx = (arrival.opponent_control > arrival.loose_control)
                                .then_some(arrival.opponent_index)
                                .flatten();
                            let pass_transition =
                                crate::execution_transition::PassExecutionTransition::new(
                                    flight.technical_probability,
                                    0.0,
                                );
                            let control_side = pass_transition.delivery_control_side(
                                flight.technical_roll,
                                receiver_idx.is_some(),
                                opponent_idx.is_some(),
                            );
                            if control_side
                                != crate::execution_transition::ExecutionControlSide::Retained
                            {
                                let team = if flight.passer_team_home {
                                    &mut *home
                                } else {
                                    &mut *away
                                };
                                if let Some(passer) = team.get_mut(flight.passer_idx) {
                                    passer.turnovers += 1;
                                }
                            }
                            let passer_identity = if flight.passer_team_home {
                                player_identity(home, flight.passer_idx)
                            } else {
                                player_identity(away, flight.passer_idx)
                            };
                            match control_side {
                                crate::execution_transition::ExecutionControlSide::Retained => {
                                    let receiver_idx = receiver_idx
                                        .unwrap_or(flight.intended_receiver_idx.unwrap_or(0));
                                    let receiver_identity = if flight.passer_team_home {
                                        player_identity(home, receiver_idx)
                                    } else {
                                        player_identity(away, receiver_idx)
                                    };
                                    let receiver_offside_flagged = flight
                                        .offside_flags
                                        .get(receiver_idx)
                                        .copied()
                                        .unwrap_or(false);
                                    let receiver_phase_offside = offside_phase_flagged_receiver(
                                        state,
                                        flight.passer_team_home,
                                        receiver_idx,
                                    )
                                    .is_some();
                                    let (
                                        receive_pos,
                                        loose_pos,
                                        receive_ok,
                                        first_touch_error,
                                        receiver_name,
                                    ) = {
                                        let team = if flight.passer_team_home {
                                            &mut *home
                                        } else {
                                            &mut *away
                                        };
                                        if let Some(receiver) = team.get_mut(receiver_idx) {
                                            let receive_randoms = preview_randoms::<3>(rng);
                                            let receive =
                                                pass_receive_plan(&PassReceivePlanInput {
                                                    receiver_pos: receiver.pos,
                                                    target_pos: flight.target,
                                                    receiver_iq: receiver.iq,
                                                    receiver_offside_flagged,
                                                    pitch_length: config.pitch_length,
                                                    pitch_width: config.pitch_width,
                                                    first_touch_error_divisor: config
                                                        .first_touch_error_divisor,
                                                    error_roll: receive_randoms[0],
                                                    loose_x_roll: receive_randoms[1],
                                                    loose_y_roll: receive_randoms[2],
                                                });
                                            advance_randoms(rng, receive.randoms_used);
                                            let name = receiver.name.clone();
                                            (
                                                receiver.pos,
                                                receive.loose_pos,
                                                receive.outcome_code == 0
                                                    && !receive.first_touch_error,
                                                receive.first_touch_error,
                                                name,
                                            )
                                        } else {
                                            (
                                                flight.target,
                                                flight.target,
                                                false,
                                                false,
                                                String::new(),
                                            )
                                        }
                                    };
                                    if receiver_offside_flagged || receiver_phase_offside {
                                        let team = if flight.passer_team_home {
                                            &mut *home
                                        } else {
                                            &mut *away
                                        };
                                        if let Some(receiver) = team.get_mut(receiver_idx) {
                                            receiver.offsides += 1;
                                        }
                                        set_dead_ball_and_clear_goals(
                                            state,
                                            home,
                                            away,
                                            "offside",
                                            !flight.passer_team_home,
                                            2,
                                            receive_pos,
                                        );
                                        queue_replay_flight_terminal_frame(
                                            state,
                                            tick,
                                            half,
                                            home,
                                            away,
                                            config,
                                            &flight,
                                            state.ball.position,
                                            flight.target,
                                            RunnerReplayFlightEnd::Offside,
                                            None,
                                            None,
                                            None,
                                            None,
                                        );
                                        trace_entry!(
                                            state,
                                            json!({
                                                "tick": tick,
                                                "type": "event",
                                                "event": "offside",
                                                "player": receiver_name,
                                                "team": if flight.passer_team_home { "home" } else { "away" }
                                            })
                                        );
                                        let mut tags = pass_execution_tags(
                                            &flight,
                                            receive_pos,
                                            config,
                                            home_attacking_right,
                                        );
                                        tags.push("offside");
                                        record_match_event(
                                            state,
                                            config,
                                            MatchEventInput {
                                                tick,
                                                half,
                                                possession_id: flight.possession_id,
                                                event_type: "pass",
                                                team_home: flight.passer_team_home,
                                                player: passer_identity,
                                                target_player: receiver_identity,
                                                assist_player: serde_json::Value::Null,
                                                outcome: "offside",
                                                xg: 0.0,
                                                origin: Some(flight.origin),
                                                target: Some(receive_pos),
                                                tags,
                                                score_before: None,
                                            },
                                        );
                                    } else if receive_ok {
                                        if flight.passer_team_home {
                                            if let Some(passer) = home.get_mut(flight.passer_idx) {
                                                passer.passes_completed += 1;
                                                let pass_stats = track_pass_stats(&PassStatInput {
                                                    origin: flight.origin,
                                                    target: receive_pos,
                                                    attacking_right: attacking_right_for(
                                                        flight.passer_team_home,
                                                        home_attacking_right,
                                                    ),
                                                    pitch_length: config.pitch_length,
                                                    pitch_width: config.pitch_width,
                                                });
                                                passer.crosses_attempted +=
                                                    pass_stats.crosses_attempted;
                                                passer.crosses_completed +=
                                                    pass_stats.crosses_completed;
                                                passer.long_passes += pass_stats.long_passes;
                                                passer.completed_long_passes +=
                                                    pass_stats.completed_long_passes;
                                                passer.progressive_passes +=
                                                    pass_stats.progressive_passes;
                                                passer.passes_into_final_third +=
                                                    pass_stats.passes_into_final_third;
                                                passer.passes_into_box +=
                                                    pass_stats.passes_into_box;
                                            }
                                        } else if let Some(passer) = away.get_mut(flight.passer_idx)
                                        {
                                            passer.passes_completed += 1;
                                            let pass_stats = track_pass_stats(&PassStatInput {
                                                origin: flight.origin,
                                                target: receive_pos,
                                                attacking_right: attacking_right_for(
                                                    flight.passer_team_home,
                                                    home_attacking_right,
                                                ),
                                                pitch_length: config.pitch_length,
                                                pitch_width: config.pitch_width,
                                            });
                                            passer.crosses_attempted +=
                                                pass_stats.crosses_attempted;
                                            passer.crosses_completed +=
                                                pass_stats.crosses_completed;
                                            passer.long_passes += pass_stats.long_passes;
                                            passer.completed_long_passes +=
                                                pass_stats.completed_long_passes;
                                            passer.progressive_passes +=
                                                pass_stats.progressive_passes;
                                            passer.passes_into_final_third +=
                                                pass_stats.passes_into_final_third;
                                            passer.passes_into_box += pass_stats.passes_into_box;
                                        }
                                        record_pass_network(
                                            state,
                                            flight.passer_team_home,
                                            flight.passer_idx,
                                            receiver_idx,
                                        );
                                        clear_offside_phase_after_touch(state);
                                        give_ball_to_player(
                                            state,
                                            home,
                                            away,
                                            receiver_idx,
                                            flight.passer_team_home,
                                            receive_pos,
                                            Some(flight.origin),
                                            home_attacking_right,
                                            config,
                                        );
                                        let holder_idx = state.ball.holder_idx;
                                        let holder_team =
                                            state.ball.holder_team_home.map(|team_home| {
                                                if team_home {
                                                    "home"
                                                } else {
                                                    "away"
                                                }
                                            });
                                        queue_replay_flight_terminal_frame(
                                            state,
                                            tick,
                                            half,
                                            home,
                                            away,
                                            config,
                                            &flight,
                                            state.ball.position,
                                            state.ball.position,
                                            RunnerReplayFlightEnd::Received,
                                            None,
                                            None,
                                            holder_idx,
                                            holder_team,
                                        );
                                        trace_entry!(
                                            state,
                                            json!({
                                                "tick": tick,
                                                "type": "action",
                                                "team": if flight.passer_team_home { "home" } else { "away" },
                                                "player": receiver_name,
                                                "action": "receive",
                                                "pos": [round_one(receive_pos.0), round_one(receive_pos.1)],
                                                "first_touch_error": first_touch_error,
                                                "retention_probability": flight.retention_probability,
                                                "technical_probability": flight.technical_probability,
                                                "technical_roll": flight.technical_roll,
                                                "delivery_miss": flight.delivery_miss,
                                                "receiver_control": arrival.receiver_control,
                                                "opponent_control": arrival.opponent_control,
                                                "loose_control": arrival.loose_control
                                            })
                                        );
                                        record_match_event(
                                            state,
                                            config,
                                            MatchEventInput {
                                                tick,
                                                half,
                                                possession_id: flight.possession_id,
                                                event_type: "pass",
                                                team_home: flight.passer_team_home,
                                                player: passer_identity,
                                                target_player: receiver_identity,
                                                assist_player: serde_json::Value::Null,
                                                outcome: "completed",
                                                xg: 0.0,
                                                origin: Some(flight.origin),
                                                target: Some(receive_pos),
                                                tags: pass_execution_tags(
                                                    &flight,
                                                    receive_pos,
                                                    config,
                                                    home_attacking_right,
                                                ),
                                                score_before: None,
                                            },
                                        );
                                    } else {
                                        clear_offside_phase_after_touch(state);
                                        set_contested_and_clear_goals(
                                            state,
                                            home,
                                            away,
                                            loose_pos,
                                            crate::physics::residual_ball_velocity(
                                                flight.target,
                                                loose_pos,
                                                flight.speed,
                                                0.26,
                                            ),
                                        );
                                        queue_replay_flight_terminal_frame(
                                            state,
                                            tick,
                                            half,
                                            home,
                                            away,
                                            config,
                                            &flight,
                                            state.ball.position,
                                            state.ball.position,
                                            RunnerReplayFlightEnd::FirstTouchError,
                                            None,
                                            None,
                                            None,
                                            None,
                                        );
                                        trace_entry!(
                                            state,
                                            json!({
                                                "tick": tick,
                                                "type": "event",
                                                "event": "first_touch_error",
                                                "player": receiver_name
                                            })
                                        );
                                        let mut tags = pass_execution_tags(
                                            &flight,
                                            loose_pos,
                                            config,
                                            home_attacking_right,
                                        );
                                        tags.push("first_touch_error");
                                        record_match_event(
                                            state,
                                            config,
                                            MatchEventInput {
                                                tick,
                                                half,
                                                possession_id: flight.possession_id,
                                                event_type: "pass",
                                                team_home: flight.passer_team_home,
                                                player: passer_identity,
                                                target_player: receiver_identity,
                                                assist_player: serde_json::Value::Null,
                                                outcome: "first_touch_error",
                                                xg: 0.0,
                                                origin: Some(flight.origin),
                                                target: Some(loose_pos),
                                                tags,
                                                score_before: None,
                                            },
                                        );
                                    }
                                }
                                crate::execution_transition::ExecutionControlSide::Opposing => {
                                    let opponent_idx = opponent_idx.unwrap_or(0);
                                    let winner_name = {
                                        let team = if flight.passer_team_home {
                                            &mut *away
                                        } else {
                                            &mut *home
                                        };
                                        if let Some(winner) = team.get_mut(opponent_idx) {
                                            winner.interceptions += 1;
                                            winner.name.clone()
                                        } else {
                                            String::new()
                                        }
                                    };
                                    let contact_pos = arrival.contact_pos;
                                    let interceptor_identity = if flight.passer_team_home {
                                        player_identity(away, opponent_idx)
                                    } else {
                                        player_identity(home, opponent_idx)
                                    };
                                    clear_offside_phase_after_touch(state);
                                    give_ball_to_player(
                                        state,
                                        home,
                                        away,
                                        opponent_idx,
                                        !flight.passer_team_home,
                                        contact_pos,
                                        None,
                                        home_attacking_right,
                                        config,
                                    );
                                    let winner_pos = state.ball.position;
                                    let holder_idx = state.ball.holder_idx;
                                    let holder_team = state
                                        .ball
                                        .holder_team_home
                                        .map(|team_home| if team_home { "home" } else { "away" });
                                    queue_replay_flight_terminal_frame(
                                        state,
                                        tick,
                                        half,
                                        home,
                                        away,
                                        config,
                                        &flight,
                                        winner_pos,
                                        winner_pos,
                                        RunnerReplayFlightEnd::Intercepted,
                                        None,
                                        None,
                                        holder_idx,
                                        holder_team,
                                    );
                                    trace_entry!(
                                        state,
                                        json!({
                                            "tick": tick,
                                            "type": "event",
                                            "event": "interception",
                                            "team": if flight.passer_team_home { "away" } else { "home" },
                                            "player": winner_name,
                                            "contact": [round_one(contact_pos.0), round_one(contact_pos.1)],
                                            "pos": [round_one(winner_pos.0), round_one(winner_pos.1)],
                                            "retention_probability": flight.retention_probability,
                                            "technical_probability": flight.technical_probability,
                                            "technical_roll": flight.technical_roll,
                                            "delivery_miss": flight.delivery_miss,
                                            "receiver_control": arrival.receiver_control,
                                            "opponent_control": arrival.opponent_control,
                                            "loose_control": arrival.loose_control
                                        })
                                    );
                                    let mut tags = pass_execution_tags(
                                        &flight,
                                        winner_pos,
                                        config,
                                        home_attacking_right,
                                    );
                                    if !flight.delivery_miss {
                                        tags.push("arrival_interception");
                                    }
                                    tags.push("pass_cut_out");
                                    record_match_event(
                                        state,
                                        config,
                                        MatchEventInput {
                                            tick,
                                            half,
                                            possession_id: flight.possession_id,
                                            event_type: "interception",
                                            team_home: !flight.passer_team_home,
                                            player: interceptor_identity,
                                            target_player: passer_identity,
                                            assist_player: serde_json::Value::Null,
                                            outcome: "won",
                                            xg: 0.0,
                                            origin: Some(flight.origin),
                                            target: Some(winner_pos),
                                            tags,
                                            score_before: None,
                                        },
                                    );
                                }
                                crate::execution_transition::ExecutionControlSide::Unresolved => {
                                    set_contested_and_clear_goals(
                                        state,
                                        home,
                                        away,
                                        arrival.contact_pos,
                                        crate::physics::residual_ball_velocity(
                                            flight.origin,
                                            arrival.contact_pos,
                                            flight.speed,
                                            0.26,
                                        ),
                                    );
                                    queue_replay_flight_terminal_frame(
                                        state,
                                        tick,
                                        half,
                                        home,
                                        away,
                                        config,
                                        &flight,
                                        state.ball.position,
                                        state.ball.position,
                                        RunnerReplayFlightEnd::Loose,
                                        None,
                                        None,
                                        None,
                                        None,
                                    );
                                    trace_entry!(
                                        state,
                                        json!({
                                            "tick": tick,
                                            "type": "event",
                                            "event": "pass_loose",
                                            "target": [round_one(arrival.contact_pos.0), round_one(arrival.contact_pos.1)],
                                            "retention_probability": flight.retention_probability,
                                            "technical_probability": flight.technical_probability,
                                            "technical_roll": flight.technical_roll,
                                            "delivery_miss": flight.delivery_miss,
                                            "receiver_control": arrival.receiver_control,
                                            "opponent_control": arrival.opponent_control,
                                            "loose_control": arrival.loose_control
                                        })
                                    );
                                    let mut tags = pass_execution_tags(
                                        &flight,
                                        arrival.contact_pos,
                                        config,
                                        home_attacking_right,
                                    );
                                    if !flight.delivery_miss {
                                        tags.push("arrival_loose");
                                    }
                                    tags.push("second_ball");
                                    record_match_event(
                                        state,
                                        config,
                                        MatchEventInput {
                                            tick,
                                            half,
                                            possession_id: flight.possession_id,
                                            event_type: "pass",
                                            team_home: flight.passer_team_home,
                                            player: passer_identity,
                                            target_player: serde_json::Value::Null,
                                            assist_player: serde_json::Value::Null,
                                            outcome: "loose",
                                            xg: 0.0,
                                            origin: Some(flight.origin),
                                            target: Some(arrival.contact_pos),
                                            tags,
                                            score_before: None,
                                        },
                                    );
                                }
                            }
                        }
                        RunnerFlightKind::Clearance => {
                            let clearer_identity = if flight.passer_team_home {
                                player_identity(home, flight.passer_idx)
                            } else {
                                player_identity(away, flight.passer_idx)
                            };
                            let transition = flight.clearance_transition.unwrap_or_else(|| {
                                let home_arrivals = clearance_players(home);
                                let away_arrivals = clearance_players(away);
                                let arrival = clearance_arrival_plan(&ClearanceArrivalPlanInput {
                                    target_pos: flight.target,
                                    passer_team_home: flight.passer_team_home,
                                    home_players: &home_arrivals,
                                    away_players: &away_arrivals,
                                });
                                RunnerClearanceTransition {
                                    winner_pos: arrival.player_index.map_or(
                                        flight.target,
                                        |winner_idx| {
                                            if arrival.winner_code == 0 {
                                                home.get(winner_idx)
                                            } else {
                                                away.get(winner_idx)
                                            }
                                            .map(|winner| winner.pos)
                                            .unwrap_or(flight.target)
                                        },
                                    ),
                                    arrival,
                                }
                            });
                            let arrival = transition.arrival;
                            let winner_home = if arrival.passer_completed {
                                flight.passer_team_home
                            } else {
                                !flight.passer_team_home
                            };
                            let winner_idx = arrival.player_index.unwrap_or(0);
                            let winner_identity = if winner_home {
                                player_identity(home, winner_idx)
                            } else {
                                player_identity(away, winner_idx)
                            };
                            let winner_name = {
                                let team = if winner_home { &mut *home } else { &mut *away };
                                if let Some(winner) = team.get_mut(winner_idx) {
                                    winner.name.clone()
                                } else {
                                    String::new()
                                }
                            };
                            let winner_pos = transition.winner_pos;
                            let receiver_offside_flagged = winner_home == flight.passer_team_home
                                && flight
                                    .offside_flags
                                    .get(winner_idx)
                                    .copied()
                                    .unwrap_or(false);
                            if receiver_offside_flagged {
                                let team = if winner_home { &mut *home } else { &mut *away };
                                if let Some(receiver) = team.get_mut(winner_idx) {
                                    receiver.offsides += 1;
                                }
                                set_dead_ball_and_clear_goals(
                                    state,
                                    home,
                                    away,
                                    "offside",
                                    !flight.passer_team_home,
                                    2,
                                    winner_pos,
                                );
                                queue_replay_flight_terminal_frame(
                                    state,
                                    tick,
                                    half,
                                    home,
                                    away,
                                    config,
                                    &flight,
                                    state.ball.position,
                                    flight.target,
                                    RunnerReplayFlightEnd::Offside,
                                    None,
                                    None,
                                    None,
                                    None,
                                );
                                trace_entry!(
                                    state,
                                    json!({
                                        "tick": tick,
                                        "type": "event",
                                        "event": "offside",
                                        "player": winner_name,
                                        "team": if winner_home { "home" } else { "away" },
                                        "source": "clearance"
                                    })
                                );
                                record_match_event(
                                    state,
                                    config,
                                    MatchEventInput {
                                        tick,
                                        half,
                                        possession_id: flight.possession_id,
                                        event_type: "clearance",
                                        team_home: flight.passer_team_home,
                                        player: clearer_identity,
                                        target_player: winner_identity,
                                        assist_player: serde_json::Value::Null,
                                        outcome: "offside",
                                        xg: 0.0,
                                        origin: Some(flight.origin),
                                        target: Some(winner_pos),
                                        tags: EventTags::from_slice(&[
                                            "long",
                                            "second_ball",
                                            "offside",
                                        ]),
                                        score_before: None,
                                    },
                                );
                            } else {
                                if arrival.passer_completed {
                                    if flight.passer_team_home {
                                        if let Some(passer) = home.get_mut(flight.passer_idx) {
                                            passer.passes_completed += 1;
                                        }
                                    } else if let Some(passer) = away.get_mut(flight.passer_idx) {
                                        passer.passes_completed += 1;
                                    }
                                }
                                give_ball_to_player(
                                    state,
                                    home,
                                    away,
                                    winner_idx,
                                    winner_home,
                                    winner_pos,
                                    None,
                                    home_attacking_right,
                                    config,
                                );
                                let holder_idx = state.ball.holder_idx;
                                let holder_team = state.ball.holder_team_home.map(|team_home| {
                                    if team_home {
                                        "home"
                                    } else {
                                        "away"
                                    }
                                });
                                queue_replay_flight_terminal_frame(
                                    state,
                                    tick,
                                    half,
                                    home,
                                    away,
                                    config,
                                    &flight,
                                    state.ball.position,
                                    state.ball.position,
                                    RunnerReplayFlightEnd::Cleared,
                                    None,
                                    None,
                                    holder_idx,
                                    holder_team,
                                );
                                trace_entry!(
                                    state,
                                    json!({
                                        "tick": tick,
                                        "type": "event",
                                        "event": "clearance_arrival",
                                        "team": if winner_home { "home" } else { "away" },
                                        "player": winner_name,
                                        "passer_completed": arrival.passer_completed
                                    })
                                );
                                record_match_event(
                                    state,
                                    config,
                                    MatchEventInput {
                                        tick,
                                        half,
                                        possession_id: flight.possession_id,
                                        event_type: "clearance",
                                        team_home: flight.passer_team_home,
                                        player: clearer_identity,
                                        target_player: winner_identity,
                                        assist_player: serde_json::Value::Null,
                                        outcome: if arrival.passer_completed {
                                            "retained"
                                        } else {
                                            "conceded"
                                        },
                                        xg: 0.0,
                                        origin: Some(flight.origin),
                                        target: Some(winner_pos),
                                        tags: EventTags::from_slice(&["long", "second_ball"]),
                                        score_before: None,
                                    },
                                );
                            }
                        }
                    }
                }
            }
        }
        RunnerBallState::Contested => {
            let ticked_ball = tick_contested_ball(&ContestedTickInput {
                position: state.ball.position,
                loose_velocity: state.ball.loose_velocity,
                contested_ticks: state.ball.contested_ticks,
            });
            state.ball.position = pitch_clamp(
                ticked_ball.position,
                config.pitch_length,
                config.pitch_width,
            );
            state.ball.loose_velocity = ticked_ball.loose_velocity;
            state.ball.contested_ticks = ticked_ball.contested_ticks;

            let attacking_team_home = state
                .last_passer_team_home
                .or(state.possession_team_home)
                .unwrap_or(true);
            if let Some((winner_home, player_idx, winner_access)) = runner_live_second_ball_winner(
                attacking_team_home,
                home,
                away,
                state.ball.position,
                state.ball.contested_ticks,
                config,
                rng,
            ) {
                let winner_pos = if winner_home {
                    home.get(player_idx)
                        .map(|player| player.pos)
                        .unwrap_or(state.ball.position)
                } else {
                    away.get(player_idx)
                        .map(|player| player.pos)
                        .unwrap_or(state.ball.position)
                };
                if !enforce_offside_phase_at_touch(
                    state,
                    tick,
                    half,
                    home,
                    away,
                    winner_home,
                    player_idx,
                    winner_pos,
                    config,
                ) {
                    let had_challenge = state.ball.contest_challenge.is_some();
                    settle_contest_challenge(
                        state,
                        tick,
                        half,
                        player_idx,
                        winner_home,
                        home,
                        away,
                        config,
                    );
                    record_unprovenanced_opponent_recovery(
                        state,
                        config,
                        tick,
                        half,
                        player_idx,
                        winner_home,
                        winner_pos,
                        home,
                        away,
                        had_challenge,
                    );
                    give_ball_to_player(
                        state,
                        home,
                        away,
                        player_idx,
                        winner_home,
                        winner_pos,
                        None,
                        home_attacking_right,
                        config,
                    );
                    trace_entry!(
                        state,
                        json!({
                            "tick": tick,
                            "type": "event",
                            "event": "contested_won",
                            "team": if winner_home { "home" } else { "away" },
                            "player_idx": player_idx,
                            "access": round_two(winner_access)
                        })
                    );
                }
            } else {
                move_contested_team(
                    home,
                    away,
                    state.ball.position,
                    home_attacking_right,
                    tick,
                    state.home_plan_signals,
                    config,
                    &mut state.team_shape_arena,
                );
                move_contested_team(
                    away,
                    home,
                    state.ball.position,
                    !home_attacking_right,
                    tick,
                    state.away_plan_signals,
                    config,
                    &mut state.team_shape_arena,
                );
            }
        }
        RunnerBallState::Dead => {
            clear_team_goals(home);
            clear_team_goals(away);
            if let (Some(reason), Some(team_home)) =
                (state.dead_reason.as_deref(), state.restart_team_home)
            {
                let (has_shape, shape_ball_pos) = apply_restart_shape(
                    reason,
                    team_home,
                    home,
                    away,
                    config,
                    home_attacking_right,
                    false,
                );
                if has_shape {
                    state.ball.position = shape_ball_pos;
                }
            }
            if state.restart_ticks_remaining > 0 {
                state.restart_ticks_remaining -= 1;
            }
            if state.restart_ticks_remaining <= 0 {
                restart_dead_ball(
                    state,
                    tick,
                    half,
                    home,
                    away,
                    config,
                    home_attacking_right,
                    rng,
                );
            }
        }
    }
    if receipt_follow_up {
        if let Some(mut event) = state.pending_on_ball_goal_event.take() {
            if let Some(payload) = event.as_object_mut() {
                payload.insert("tick".to_string(), json!(tick));
            }
            trace_entry!(state, event);
        }
        if held_attack_choices > 0 || held_defense_choices > 0 {
            trace_entry!(
                state,
                json!({
                    "tick": tick,
                    "type": "event",
                    "event": "off_ball_choice",
                    "attack_choices": held_attack_choices,
                    "defense_choices": held_defense_choices,
                    "attack_goal_choices": held_attack_choices,
                    "defense_goal_choices": held_defense_choices
                })
            );
        }
        return;
    }
    if state_before == RunnerBallState::InFlight && state.ball.state == RunnerBallState::Held {
        tick_match_phase(
            state,
            tick,
            half,
            home,
            away,
            config,
            home_attacking_right,
            held_tick_arena,
            rng,
            true,
        );
    }
    tick_stunned_players(home);
    tick_stunned_players(away);
    push_rng_trace(state, tick, "tick_end", rng);
    match state_before {
        RunnerBallState::Held => match (state.ball.state, state.ball.holder_team_home) {
            (RunnerBallState::Held, Some(true)) => state.home_possession_ticks += 1,
            (RunnerBallState::Held, Some(false)) => state.away_possession_ticks += 1,
            _ => {}
        },
        RunnerBallState::Contested => state.neutral_ticks += 1,
        _ => {}
    }
    if state_before == RunnerBallState::Held {
        if let Some(mut event) = state.pending_on_ball_goal_event.take() {
            if let Some(payload) = event.as_object_mut() {
                payload.insert("tick".to_string(), json!(tick));
            }
            trace_entry!(state, event);
        }
        if held_attack_choices > 0 || held_defense_choices > 0 {
            trace_entry!(
                state,
                json!({
                    "tick": tick,
                    "type": "event",
                    "event": "off_ball_choice",
                    "attack_choices": held_attack_choices,
                    "defense_choices": held_defense_choices,
                    "attack_goal_choices": held_attack_choices,
                    "defense_goal_choices": held_defense_choices
                })
            );
        }
    }
    trace_entry!(
        state,
        json!({
            "tick": tick,
            "type": "state",
            "ball_state": ball_state_name(state.ball.state),
            "match_clock": match_clock_payload(state.match_clock),
            "holder_team": state.ball.holder_team_home.map(|home| if home { "home" } else { "away" }),
            "home_phase": phase_name(state.home_phase_code),
            "away_phase": phase_name(state.away_phase_code),
            "home_ticks_since_possession_change": state.home_ticks_since_possession_change,
            "away_ticks_since_possession_change": state.away_ticks_since_possession_change,
            "home_had_possession_last_tick": state.home_had_possession_last_tick,
            "away_had_possession_last_tick": state.away_had_possession_last_tick
        })
    );
    publish_team_communication(state, home, true, tick, config);
    publish_team_communication(state, away, false, tick, config);
}

pub fn run_match_v2(request: MatchV2RunRequest) -> MatchV2RunResponse {
    let _ = all_ball_states();
    let config = runtime_config(&request.config);
    let mut rng = RunnerRng::new(request.seed.unwrap_or(0));
    let pitch_length = config.pitch_length;
    let pitch_width = config.pitch_width;
    let home_formation_data = formation_data(&request.home_formation);
    let away_formation_data = formation_data(&request.away_formation);
    let mut home_players = build_players(
        &request.home_cards,
        home_formation_data,
        true,
        pitch_length,
        pitch_width,
    );
    let mut away_players = build_players(
        &request.away_cards,
        away_formation_data,
        false,
        pitch_length,
        pitch_width,
    );
    let total_ticks = config.total_ticks.max(0) as usize;
    let position_sample_capacity = total_ticks.saturating_add(9) / 10;
    for player in home_players.iter_mut().chain(away_players.iter_mut()) {
        player.position_samples.reserve(position_sample_capacity);
        player.shot_log.reserve(8);
    }
    let frame_interval = config.frame_interval.max(1);
    let sampled_frame_count = |start_tick: i32, end_tick: i32| {
        if end_tick <= start_tick {
            0
        } else {
            ((end_tick - start_tick - 1) / frame_interval + 1) as usize
        }
    };
    let replay_capacity = 3usize
        .saturating_add(sampled_frame_count(0, config.half_ticks))
        .saturating_add(sampled_frame_count(config.half_ticks, config.total_ticks))
        .saturating_add(total_ticks / 10 + 16);
    let event_capacity = (total_ticks / 3 + 32).min(1024);
    let trace_id = format!(
        "rust-match-v2:{}:{}:{}:{}",
        request.home_formation,
        request.away_formation,
        request.home_cards.len(),
        request.away_cards.len()
    );
    let mut replay = Vec::with_capacity(replay_capacity);
    replay.push(RunnerReplayEntry::Raw(replay_header(
        &home_players,
        &away_players,
        &request.home_formation,
        &request.away_formation,
        pitch_width,
        pitch_length,
    )));
    let (mut holder_idx, mut holder_team, mut ball_pos) = apply_kickoff(
        true,
        true,
        &mut home_players,
        &mut away_players,
        &config,
        None,
    );
    let rng_trace_enabled = request
        .config
        .get("rng_trace")
        .and_then(|value| value.as_bool())
        .unwrap_or_else(|| std::env::var("PSL_ENGINE_V2_RNG_TRACE").is_ok());
    let trace_enabled = config.trace_detail != "off" || rng_trace_enabled;
    let mut state = RunnerMatchState {
        ball: RunnerBall {
            state: RunnerBallState::Held,
            position: ball_pos,
            holder_idx: Some(holder_idx),
            holder_team_home: Some(holder_team == "home"),
            control: PossessionControlState::default(),
            flight: None,
            loose_velocity: (0.0, 0.0),
            contested_ticks: 0,
            contest_challenge: None,
            offside_phase: None,
        },
        home_score: 0,
        away_score: 0,
        goals: Vec::with_capacity(8),
        events: Vec::with_capacity(event_capacity),
        event_seq: 0,
        possession_id: 1,
        possession_team_home: Some(true),
        home_possession_ticks: 0,
        away_possession_ticks: 0,
        neutral_ticks: 0,
        match_clock: MatchClock::default(),
        action_commitment: None,
        dead_reason: None,
        restart_team_home: None,
        restart_ticks_remaining: 0,
        last_passer_team_home: None,
        last_passer_idx: -1,
        pass_network: [[[0; RUNNER_TEAM_SIZE]; RUNNER_TEAM_SIZE]; 2],
        held_action_cursor: 0,
        pending_on_ball_goal_event: None,
        next_replay_flight_id: 1,
        pending_replay_frames: Vec::with_capacity(8),
        trace_entries: Vec::new(),
        trace_decisions: Vec::new(),
        shot_quality_cache: RefCell::new(HashMap::new()),
        held_action_buffer: Vec::with_capacity(RUNNER_MAX_HELD_ACTIONS),
        carry_defender_response_arena: RunnerCarryDefenderResponseArena::new(),
        held_decision_arena: RunnerHeldDecisionArena::new(),
        pass_candidate_buffer: vec![EMPTY_TEAM_PASS_CANDIDATE; MAX_TEAM_PASS_CANDIDATES],
        pass_workspace: TeamPassWorkspace::new(),
        specialized_goal_arena: RunnerSpecializedGoalArena::new(),
        off_ball_attack_arena: RunnerOffBallAttackArena::new(),
        team_plan_arena: RunnerTeamPlanArena::new(),
        team_shape_arena: RunnerTeamShapeArena::new(),
        fixed_defense_arena: RunnerFixedDefenseArena::new(),
        home_phase_code: 1,
        away_phase_code: 3,
        home_had_possession_last_tick: false,
        away_had_possession_last_tick: false,
        home_ticks_since_possession_change: 99,
        away_ticks_since_possession_change: 99,
        home_plan: TeamPlanState::default(),
        away_plan: TeamPlanState::default(),
        home_plan_signals: TeamPlanSignals::default(),
        away_plan_signals: TeamPlanSignals::default(),
        team_communication: TeamCommunicationBus::default(),
        trace_enabled,
        rng_trace_enabled,
    };
    give_ball_to_player(
        &mut state,
        &mut home_players,
        &mut away_players,
        holder_idx,
        holder_team == "home",
        ball_pos,
        None,
        true,
        &config,
    );
    initialize_team_communication(&mut state, 0, &config);
    replay.push(RunnerReplayEntry::Frame(frame(
        0,
        config.tick_duration,
        1,
        &home_players,
        &away_players,
        ball_pos,
        Some(holder_idx),
        Some(holder_team),
        (0, 0),
        Some(true),
        None,
        None,
        None,
    )));
    record_half_frames(
        &mut replay,
        &mut state,
        0,
        config.half_ticks,
        1,
        &mut home_players,
        &mut away_players,
        &config,
        true,
        &mut rng,
    );
    reset_formation_slots(
        &mut home_players,
        home_formation_data,
        false,
        pitch_length,
        pitch_width,
    );
    reset_formation_slots(
        &mut away_players,
        away_formation_data,
        true,
        pitch_length,
        pitch_width,
    );
    let kickoff = apply_kickoff(
        false,
        false,
        &mut home_players,
        &mut away_players,
        &config,
        Some(&mut state),
    );
    holder_idx = kickoff.0;
    holder_team = kickoff.1;
    ball_pos = kickoff.2;
    state.dead_reason = None;
    state.restart_team_home = None;
    state.restart_ticks_remaining = 0;
    state.last_passer_team_home = None;
    state.last_passer_idx = -1;
    initialize_team_communication(&mut state, config.half_ticks, &config);
    replay.push(RunnerReplayEntry::Frame(frame(
        (config.half_ticks - 1).max(0),
        config.tick_duration,
        2,
        &home_players,
        &away_players,
        ball_pos,
        Some(holder_idx),
        Some(holder_team),
        (state.home_score, state.away_score),
        Some(true),
        None,
        None,
        None,
    )));
    record_half_frames(
        &mut replay,
        &mut state,
        config.half_ticks,
        config.total_ticks,
        2,
        &mut home_players,
        &mut away_players,
        &config,
        false,
        &mut rng,
    );
    let possession_total =
        state.home_possession_ticks + state.away_possession_ticks + state.neutral_ticks;
    let home_possession = possession_pct(state.home_possession_ticks, possession_total);
    let away_possession = round_one(100.0 - home_possession);
    let home_stats = team_stats(&home_players, home_possession, &state.events, true);
    let away_stats = team_stats(&away_players, away_possession, &state.events, false);
    let match_clock = match_clock_payload(state.match_clock);
    MatchV2RunResponse {
        home_score: state.home_score,
        away_score: state.away_score,
        goals: state.goals,
        events: state.events,
        home_stats,
        away_stats,
        match_clock: match_clock.clone(),
        home_player_stats: player_stat_skeleton(&home_players, true, &state.pass_network),
        away_player_stats: player_stat_skeleton(&away_players, false, &state.pass_network),
        home_ratings: team_ratings(&home_players, state.away_score),
        away_ratings: team_ratings(&away_players, state.home_score),
        replay_url: None,
        trace_id: if let Some(seed) = request.seed {
            format!("{trace_id}:seed:{seed}")
        } else {
            trace_id
        },
        replay,
        trace: serde_json::json!({
            "trace_id": "rust-match-v2",
            "entries": state.trace_entries,
            "decisions": state.trace_decisions,
            "total_entries": state.home_possession_ticks + state.away_possession_ticks + state.neutral_ticks,
            "match_clock": match_clock,
        }),
        engine: "rust_match_v2".to_string(),
        contract_version: 2,
    }
}
